// 更新购买比例合计（局装+整装锁定为100%）
// changedField: 'partial' | 'full' | null - 表示哪个字段被修改
function updatePurchaseRatioTotal(changedField = null) {
    const partialEl = document.getElementById('purchaseRatioPartial');
    const fullEl = document.getElementById('purchaseRatioFull');
    const totalEl = document.getElementById('purchaseRatioTotal');
    
    if (!partialEl || !fullEl) return 100;
    
    let partialRatio = parseFloat(partialEl.value) || 0;
    let fullRatio = parseFloat(fullEl.value) || 0;
    
    // 限制范围在0-100之间
    partialRatio = Math.max(0, Math.min(100, partialRatio));
    fullRatio = Math.max(0, Math.min(100, fullRatio));
    
    // 联动锁定：修改一个时，另一个自动调整为100减去该值
    if (changedField === 'partial') {
        fullRatio = 100 - partialRatio;
        fullEl.value = fullRatio;
    } else if (changedField === 'full') {
        partialRatio = 100 - fullRatio;
        partialEl.value = partialRatio;
    }
    
    const total = partialRatio + fullRatio;
    
    if (totalEl) {
        totalEl.value = total + '%';
        // 始终显示绿色（因为现在强制锁定为100%）
        totalEl.style.backgroundColor = 'rgba(16, 185, 129, 0.15)';
        totalEl.style.borderColor = 'var(--success-color)';
        totalEl.style.color = 'var(--success-color)';
    }
    return total;
}

// 获取当前模型类型
function getCurrentModelType() {
    const model = ModelManager.getCurrentModel();
    return model?.modelType || 'holding_pool';
}

// 判断是否为流转型放款池信托
function isCirculationPoolModel() {
    return getCurrentModelType() === 'circulation_pool';
}

// 更新配置区域显示状态（根据当前模型类型）
function updateConfigSectionVisibility() {
    const isCirculationType = isCirculationPoolModel();
    
    // 【v3.44.5】持有型配置区域
    const holdingConfigSection = document.getElementById('holdingConfigSection');
    if (holdingConfigSection) {
        holdingConfigSection.style.display = isCirculationType ? 'none' : 'block';
    }
    
    // 循环池配置区域
    const circulationConfigSection = document.getElementById('circulationConfigSection');
    if (circulationConfigSection) {
        circulationConfigSection.style.display = isCirculationType ? 'block' : 'none';
    }
    
    // 去化率设置（仅流转型）
    const absorptionSection = document.getElementById('absorptionSection');
    if (absorptionSection) {
        absorptionSection.style.display = isCirculationType ? 'block' : 'none';
    }
    
    // 风险参数UI切换
    const holdingRiskParams = document.getElementById('holdingRiskParams');
    const circulationRiskParams = document.getElementById('circulationRiskParams');
    const holdingRiskNote = document.getElementById('holdingRiskNote');
    const circulationRiskNote = document.getElementById('circulationRiskNote');
    if (holdingRiskParams) holdingRiskParams.style.display = isCirculationType ? 'none' : 'grid';
    if (circulationRiskParams) circulationRiskParams.style.display = isCirculationType ? 'grid' : 'none';
    if (holdingRiskNote) holdingRiskNote.style.display = isCirculationType ? 'none' : 'block';
    if (circulationRiskNote) circulationRiskNote.style.display = isCirculationType ? 'block' : 'none';
    
    // 【v3.44.6】资金端结构控制
    // 持有型：固定使用结构化资金，隐藏切换按钮，显示持有型提示
    // 流转型：显示平层/结构化切换，默认平层
    const fundingTypeRow = document.getElementById('fundingTypeRow');
    const holdingFundingNote = document.getElementById('holdingFundingNote');
    const flatFundingConfig = document.getElementById('flatFundingConfig');
    const structuredFundingConfig = document.getElementById('structuredFundingConfig');
    
    // 结构化资金说明切换
    const holdingStructuredInfo = document.getElementById('holdingStructuredInfo');
    const circulationStructuredInfo = document.getElementById('circulationStructuredInfo');
    
    if (isCirculationType) {
        // 流转型：显示切换按钮，默认平层
        if (fundingTypeRow) fundingTypeRow.style.display = 'block';
        if (holdingFundingNote) holdingFundingNote.style.display = 'none';
        // 切换到平层模式
        const flatRadio = document.querySelector('input[name="fundingType"][value="flat"]');
        if (flatRadio) {
            flatRadio.checked = true;
            // 更新选中状态
            document.querySelectorAll('.funding-type-option').forEach(opt => {
                opt.classList.toggle('selected', opt.dataset.type === 'flat');
            });
        }
        if (flatFundingConfig) flatFundingConfig.style.display = 'block';
        if (structuredFundingConfig) structuredFundingConfig.style.display = 'none';
        // 结构化说明切换为流转型
        if (holdingStructuredInfo) holdingStructuredInfo.style.display = 'none';
        if (circulationStructuredInfo) circulationStructuredInfo.style.display = 'block';
    } else {
        // 持有型：隐藏切换按钮，固定结构化
        if (fundingTypeRow) fundingTypeRow.style.display = 'none';
        if (holdingFundingNote) holdingFundingNote.style.display = 'block';
        // 强制选中结构化
        const structuredRadio = document.querySelector('input[name="fundingType"][value="structured"]');
        if (structuredRadio) {
            structuredRadio.checked = true;
            document.querySelectorAll('.funding-type-option').forEach(opt => {
                opt.classList.toggle('selected', opt.dataset.type === 'structured');
            });
        }
        if (flatFundingConfig) flatFundingConfig.style.display = 'none';
        if (structuredFundingConfig) structuredFundingConfig.style.display = 'block';
        // 结构化说明切换为持有型
        if (holdingStructuredInfo) holdingStructuredInfo.style.display = 'block';
        if (circulationStructuredInfo) circulationStructuredInfo.style.display = 'none';
    }
    
    // 更新购买比例合计
    if (isCirculationType) {
        updatePurchaseRatioTotal();
    }
    
    console.log('配置区域显示状态已更新:', { isCirculationType, holdingVisible: !isCirculationType, absorptionVisible: isCirculationType, fundingType: isCirculationType ? 'flat' : 'structured' });
}

