// ========================================
// API 服务
// ========================================

const API = {
    baseUrl: 'tables/structured_finance_assets',
    maxLimit: 1000, // 与本地REST服务保持一致
    
    // 获取当前模型ID
    getCurrentModelId() {
        return ModelManager.currentModelId || 'default';
    },
    
    async getAssets(page = 1, limit = 100, search = '') {
        try {
            const modelId = this.getCurrentModelId();
            let url = `${this.baseUrl}`;
            const params = new URLSearchParams();
            params.append('page', page.toString());
            // 限制limit不超过API最大值
            params.append('limit', Math.min(limit, this.maxLimit).toString());
            params.append('modelId', modelId);
            if (search) params.append('q', search);
            
            const fullUrl = `${url}?${params.toString()}`;
            const response = await fetch(fullUrl);
            
            if (!response.ok) {
                console.warn(`API响应状态: ${response.status}`);
                return { data: [], total: 0, page: 1, limit: limit };
            }
            
            const result = await response.json();
            return { 
                data: result.data || [], 
                total: result.total || 0, 
                page: result.page, 
                limit: result.limit 
            };
        } catch (error) {
            console.error('API getAssets 错误:', error);
            return { data: [], total: 0, page: 1, limit: limit };
        }
    },
    
    // 获取所有资产（自动分页，高并发优化）- 仅当前模型
    // 【优化】使用服务端搜索过滤 + 客户端二次过滤，减少不必要的数据传输
    // 全局缓存，避免重复加载
    _allAssetsCache: null,
    _cacheModelId: null,
    _cacheTimestamp: 0,
    _cacheDuration: 60000, // 缓存1分钟
    
    async getAllAssets(forceRefresh = false) {
        try {
            const modelId = this.getCurrentModelId();
            const now = Date.now();
            
            // 检查缓存是否有效
            if (!forceRefresh && this._allAssetsCache && 
                this._cacheModelId === modelId &&
                (now - this._cacheTimestamp) < this._cacheDuration) {
                const cached = this._allAssetsCache.filter(a => a.modelId === modelId);
                console.log(`【缓存命中】当前模型 ${modelId} 共 ${cached.length} 条`);
                return { data: cached, total: cached.length };
            }
            
            console.log(`【快速加载】开始并行获取所有数据...`);
            const startTime = performance.now();
            
            // 第一步：获取总数
            const firstResult = await this.getAssetsRaw(1, 1, { modelId });
            const serverTotal = firstResult.total || 0;
            
            if (serverTotal === 0) {
                this._allAssetsCache = [];
                this._cacheModelId = modelId;
                this._cacheTimestamp = now;
                return { data: [], total: 0 };
            }
            
            // 第二步：计算需要多少页，使用最大limit一次获取尽量多的数据
            const pageSize = this.maxLimit; // 100条/页
            const totalPages = Math.ceil(serverTotal / pageSize);
            
            console.log(`【快速加载】服务端共 ${serverTotal} 条，需请求 ${totalPages} 页`);
            
            // 第三步：超高并发获取所有页面（50页并发）
            const CONCURRENT_LIMIT = 50;
            let allData = [];
            
            for (let batchStart = 1; batchStart <= totalPages; batchStart += CONCURRENT_LIMIT) {
                const batchEnd = Math.min(batchStart + CONCURRENT_LIMIT - 1, totalPages);
                const pagePromises = [];
                
                for (let page = batchStart; page <= batchEnd; page++) {
                    pagePromises.push(this.getAssetsRaw(page, pageSize, { modelId }));
                }
                
                const results = await Promise.all(pagePromises);
                
                for (const result of results) {
                    if (Array.isArray(result.data)) {
                        allData = allData.concat(result.data);
                    }
                }
                
                // 进度提示
                const progress = Math.min(100, Math.round((batchEnd / totalPages) * 100));
                console.log(`【快速加载】进度: ${progress}% (${allData.length}/${serverTotal})`);
            }
            
            // 缓存当前模型数据，避免跨模型复用时出现陈旧数据
            this._allAssetsCache = allData;
            this._cacheModelId = modelId;
            this._cacheTimestamp = now;
            
            const modelAssets = allData.filter(asset => asset.modelId === modelId);
            
            const elapsed = ((performance.now() - startTime) / 1000).toFixed(2);
            console.log(`【快速加载完成】耗时 ${elapsed}s，总计 ${allData.length} 条，当前模型 ${modelAssets.length} 条`);
            
            return { data: modelAssets, total: modelAssets.length };
        } catch (error) {
            console.error('API getAllAssets 错误:', error);
            return { data: [], total: 0 };
        }
    },

    async getAllModelAssetsRaw() {
        try {
            const firstResult = await this.getAssetsRaw(1, 1);
            const serverTotal = firstResult.total || 0;
            if (serverTotal === 0) return [];

            const pageSize = this.maxLimit;
            const totalPages = Math.ceil(serverTotal / pageSize);
            let allAssets = [];

            for (let page = 1; page <= totalPages; page++) {
                const result = await this.getAssetsRaw(page, pageSize);
                if (Array.isArray(result.data)) {
                    allAssets = allAssets.concat(result.data);
                }
            }

            return allAssets;
        } catch (error) {
            console.error('API getAllModelAssetsRaw 错误:', error);
            return [];
        }
    },
    
    // 清除缓存（导入新数据后调用）
    clearAssetsCache() {
        this._allAssetsCache = null;
        this._cacheModelId = null;
        this._cacheTimestamp = 0;
        console.log('【缓存已清除】');
    },
    
    // 【调试用】获取所有模型的资产统计
    async getModelAssetStats() {
        const allAssets = await this.getAllModelAssetsRaw();
        const stats = {};
        (allAssets || []).forEach(asset => {
            const mid = asset.modelId || 'unknown';
            stats[mid] = (stats[mid] || 0) + 1;
        });
        console.log('=== 各模型资产统计 ===');
        Object.entries(stats).forEach(([modelId, count]) => {
            console.log(`  ${modelId}: ${count}条`);
        });
        return stats;
    },
    
    // 带模型过滤的资产获取（尝试服务端过滤）
    async getAssetsWithModelFilter(page, limit, modelId) {
        try {
            const params = new URLSearchParams();
            params.append('page', page.toString());
            params.append('limit', Math.min(limit, this.maxLimit).toString());
            params.append('modelId', modelId);
            
            const response = await fetch(`${this.baseUrl}?${params.toString()}`);
            
            if (!response.ok) {
                return { data: [], total: 0 };
            }
            
            return await response.json();
        } catch (error) {
            return { data: [], total: 0 };
        }
    },
    
    // 获取原始资产数据（不过滤模型）
    async getAssetsRaw(page = 1, limit = 100, options = {}) {
        try {
            let url = `${this.baseUrl}`;
            const params = new URLSearchParams();
            params.append('page', page.toString());
            params.append('limit', Math.min(limit, this.maxLimit).toString());
            if (options.modelId) params.append('modelId', options.modelId);
            if (options.q) params.append('q', options.q);
            
            const fullUrl = `${url}?${params.toString()}`;
            const response = await fetch(fullUrl);
            
            if (!response.ok) {
                return { data: [], total: 0, page: 1, limit: limit };
            }
            
            return await response.json();
        } catch (error) {
            console.error('API getAssetsRaw 错误:', error);
            return { data: [], total: 0, page: 1, limit: limit };
        }
    },
    
    /**
     * 【v3.44.4重构】创建单条资产
     * 强制要求modelId，防止孤立数据
     */
    async createAsset(data) {
        const modelId = this.getCurrentModelId();
        
        // 【数据完整性检查】确保modelId存在且有效
        if (!modelId || modelId === 'unknown') {
            console.error('【数据完整性】创建资产失败：无有效的模型ID');
            throw new Error('请先选择或创建一个信托模型');
        }
        
        // 验证模型是否存在于本地配置
        const modelExists = ModelManager.models.some(m => m.id === modelId);
        if (!modelExists) {
            console.error('【数据完整性】创建资产失败：模型不存在于本地配置', modelId);
            throw new Error('当前模型配置无效，请刷新页面或重新选择模型');
        }
        
        const assetData = {
            ...data,
            modelId: modelId,
            _createdAt: Date.now()  // 添加创建时间戳用于追踪
        };
        
        const response = await fetch(this.baseUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(assetData)
        });
        return await response.json();
    },
    
    /**
     * 【v3.45.30重构】超高性能批量创建资产
     * 优化策略：
     * 1. 批量API调用 - 每次请求提交多条数据（而非逐条）
     * 2. 超高并发 - 同时发送多个批量请求
     * 3. 预处理数据 - 一次性添加所有字段，减少循环开销
     * 4. 流式处理 - 不等待所有请求完成才更新进度
     */
    async createAssetsBatch(dataArray, progressCallback = null, options = {}) {
        const modelId = this.getCurrentModelId();
        const forceModelId = options.forceModelId || modelId;
        
        // 【数据完整性检查】
        if (!modelId || modelId === 'unknown') {
            console.error('【批量导入】失败：无有效的模型ID');
            throw new Error('请先选择或创建一个信托模型');
        }
        
        const modelExists = ModelManager.models.some(m => m.id === forceModelId);
        if (!modelExists) {
            console.error('【批量导入】失败：模型不存在', forceModelId);
            throw new Error('当前模型配置无效');
        }
        
        const totalCount = dataArray.length;
        console.log(`【批量导入 v3.45.30】开始 - 模型: ${forceModelId}, 数量: ${totalCount}`);
        const startTime = performance.now();
        const results = { success: 0, failed: 0, errors: [] };
        
        // 【优化1】预处理 - 一次性为所有数据添加字段
        // 批量导入统一以目标模型为准，避免外部模板携带旧 modelId 造成孤立数据
        const timestamp = Date.now();
        const assetsWithModelId = dataArray.map((data, index) => {
            return {
                ...data,
                modelId: forceModelId,
                _batchId: `batch_${timestamp}`,
                _batchIndex: index
            };
        });
        
        try {
            const res = await fetch(`${this.baseUrl}/batch`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ rows: assetsWithModelId })
            });
            if (!res.ok) {
                throw new Error(`批量接口返回 ${res.status}`);
            }
            const payload = await res.json();
            results.success = payload.success ?? (payload.data?.length || 0);
            results.failed = payload.failed ?? Math.max(0, totalCount - results.success);
            if (progressCallback) {
                progressCallback(100, results.success, results.failed);
            }
        } catch (error) {
            console.error('【批量导入】批量接口失败:', error);
            results.failed = totalCount;
            results.errors.push(error.message);
        }
        
        const elapsed = ((performance.now() - startTime) / 1000).toFixed(2);
        const speed = Math.round(results.success / parseFloat(elapsed));
        console.log(`【批量导入 v3.45.30】完成 - 成功${results.success}条, 失败${results.failed}条, 耗时${elapsed}s, 速度${speed}条/秒`);
        
        // 清除缓存，强制下次重新加载
        this.clearAssetsCache();
        
        return results;
    },
    
    /**
     * 【v3.45.30重构】超高性能批量删除资产
     * 优化策略：
     * 1. 并行获取数据 - 同时发起多个分页请求
     * 2. 超高并发删除 - 150个并发DELETE请求
     * 3. 移除延迟 - 不再等待
     * 4. 边获取边删除 - 流水线处理
     */
    async deleteAssetsByModel(modelId, progressCallback = null) {
        if (!modelId) {
            throw new Error('模型ID不能为空');
        }
        
        console.log(`【批量删除 v3.45.30】开始删除模型 ${modelId} 的所有数据...`);
        const startTime = performance.now();

        try {
            const res = await fetch(`${this.baseUrl}/by-model/${encodeURIComponent(modelId)}`, { method: 'DELETE' });
            if (!res.ok) {
                throw new Error(`按模型删除接口返回 ${res.status}`);
            }
            const payload = await res.json();
            const deleted = payload.deleted || 0;
            if (progressCallback) progressCallback(100, deleted);
            this.clearAssetsCache();
            const elapsed = ((performance.now() - startTime) / 1000).toFixed(2);
            console.log(`【批量删除】后端按模型删除完成 - ${deleted}条, 耗时${elapsed}s`);
            return { deleted, failed: 0, total: deleted };
        } catch (batchError) {
            console.warn('【批量删除】按模型删除接口不可用，降级逐条删除:', batchError);
        }
        
        // 【优化1】先快速获取总数和第一批数据
        let modelAssets = [];
        let totalExpected = 0;
        
        try {
            const pageSize = this.maxLimit;
            // 第一次请求获取当前模型总数
            const firstResult = await this.getAssetsRaw(1, pageSize, { modelId });
            totalExpected = firstResult.total || 0;
            
            if (totalExpected === 0) {
                console.log(`【批量删除】服务端无数据`);
                return { deleted: 0 };
            }
            
            console.log(`【批量删除】模型 ${modelId} 服务端共 ${totalExpected} 条数据`);
            
            // 【优化2】并行获取所有分页数据
            const totalPages = Math.ceil(totalExpected / pageSize);
            
            if (totalPages === 1) {
                // 只有一页，直接使用第一次请求的结果
                modelAssets = firstResult.data || [];
            } else {
                // 多页时并行获取
                console.log(`【批量删除】并行获取 ${totalPages} 页数据...`);
                const pagePromises = [];
                
                // 第一页已经有了
                let allData = firstResult.data || [];
                
                // 并行请求剩余页面（最多同时10个请求）
                const FETCH_CONCURRENT = 10;
                for (let page = 2; page <= totalPages; page += FETCH_CONCURRENT) {
                    const batch = [];
                    for (let p = page; p < page + FETCH_CONCURRENT && p <= totalPages; p++) {
                        batch.push(this.getAssetsRaw(p, pageSize, { modelId }));
                    }
                    const results = await Promise.all(batch);
                    results.forEach(r => {
                        if (r.data) allData = allData.concat(r.data);
                    });
                }
                
                modelAssets = allData;
            }
            
            console.log(`【批量删除】筛选出模型 ${modelId} 的 ${modelAssets.length} 条数据`);
            
        } catch (error) {
            console.error(`【批量删除】服务器查询失败:`, error);
            if (this._allAssetsCache && this._allAssetsCache.length > 0) {
                modelAssets = this._allAssetsCache.filter(a => a.modelId === modelId);
                console.log(`【批量删除】使用缓存数据，找到 ${modelAssets.length} 条`);
            }
        }
        
        if (modelAssets.length === 0) {
            console.log(`【批量删除】模型 ${modelId} 无数据需要删除`);
            return { deleted: 0 };
        }
        
        const assetIds = modelAssets.map(a => a.id);
        const totalToDelete = assetIds.length;
        console.log(`【批量删除】开始删除 ${totalToDelete} 条数据...`);
        
        let deleted = 0;
        let failed = 0;
        
        // 【v3.45.31】极限优化 - 超高并发删除
        const CONCURRENT_LIMIT = 300;  // 极限并发
        
        // 极简删除函数
        const deleteOne = async (id) => {
            try {
                const res = await fetch(`${this.baseUrl}/${id}`, { method: 'DELETE' });
                return res.ok || res.status === 204 || res.status === 404;
            } catch {
                return false;
            }
        };
        
        // 直接高并发处理
        for (let i = 0; i < totalToDelete; i += CONCURRENT_LIMIT) {
            const batch = assetIds.slice(i, Math.min(i + CONCURRENT_LIMIT, totalToDelete));
            const batchResults = await Promise.all(batch.map(deleteOne));
            
            const batchDeleted = batchResults.filter(Boolean).length;
            deleted += batchDeleted;
            failed += batch.length - batchDeleted;
            
            // 更新进度
            const progress = Math.round(((i + batch.length) / totalToDelete) * 100);
            if (progressCallback) {
                progressCallback(progress, deleted);
            }
        }
        
        const elapsed = ((performance.now() - startTime) / 1000).toFixed(2);
        const speed = Math.round(deleted / parseFloat(elapsed));
        console.log(`【批量删除 v3.45.31】完成 - 成功${deleted}条, 失败${failed}条, 耗时${elapsed}s, 速度${speed}条/秒`);
        
        // 清除缓存
        this.clearAssetsCache();
        
        return { deleted, failed, total: totalToDelete };
    },
    
    /**
     * 【v3.44.4新增】验证数据完整性
     * 检查是否存在孤立数据（modelId不存在于本地配置）
     */
    async validateDataIntegrity() {
        console.log('【数据完整性检查】开始...');
        
        const allAssets = await this.getAllModelAssetsRaw();
        const localModelIds = ModelManager.models.map(m => m.id);
        
        const issues = {
            orphanAssets: [],      // 孤立资产（modelId不存在）
            unknownModelAssets: [], // modelId为unknown的资产
            totalAssets: allAssets.length,
            validAssets: 0
        };
        
        allAssets.forEach(asset => {
            const modelId = asset.modelId;
            if (!modelId || modelId === 'unknown') {
                issues.unknownModelAssets.push(asset.id);
            } else if (!localModelIds.includes(modelId)) {
                issues.orphanAssets.push({ id: asset.id, modelId });
            } else {
                issues.validAssets++;
            }
        });
        
        console.log('【数据完整性检查】结果:', {
            总资产数: issues.totalAssets,
            有效资产: issues.validAssets,
            孤立资产: issues.orphanAssets.length,
            未知模型资产: issues.unknownModelAssets.length
        });
        
        return issues;
    },
    
    /**
     * 【v3.44.4重构】更新资产
     * 确保modelId不被篡改
     */
    async updateAsset(id, data) {
        const modelId = this.getCurrentModelId();
        
        // 防止modelId被修改为其他值
        const assetData = {
            ...data,
            modelId: modelId,
            _updatedAt: Date.now()
        };
        
        // 移除可能导致问题的字段
        delete assetData.id;
        delete assetData.gs_project_id;
        delete assetData.gs_table_name;
        
        const response = await fetch(`${this.baseUrl}/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(assetData)
        });
        
        // 更新成功后清除缓存
        if (response.ok) {
            this.clearAssetsCache();
        }
        
        return await response.json();
    },
    
    /**
     * 【v3.44.4重构】删除单条资产
     */
    async deleteAsset(id) {
        const response = await fetch(`${this.baseUrl}/${id}`, { method: 'DELETE' });
        
        // 删除成功后更新缓存
        if (response.ok && this._allAssetsCache) {
            this._allAssetsCache = this._allAssetsCache.filter(a => a.id !== id);
        }
        
        return response.ok;
    },
    
    /**
     * 【v3.44.4新增】批量删除资产（通用）
     * @param {string[]} ids - 要删除的资产ID数组
     * @param {Function} progressCallback - 进度回调
     */
    /**
     * 【v3.45.30重构】超高性能批量删除
     * 优化：200并发 + Promise.all + 无延迟
     */
    async deleteAssetsBatch(ids, progressCallback = null) {
        if (!ids || ids.length === 0) return { deleted: 0 };
        
        const totalCount = ids.length;
        console.log(`【批量删除 v3.45.30】开始删除 ${totalCount} 条数据...`);
        const startTime = performance.now();
        
        let deleted = 0;
        
        // 【v3.45.31】极限优化 - 超高并发
        const CONCURRENT_LIMIT = 300;
        
        // 极简删除函数
        const deleteOne = async (id) => {
            try {
                const res = await fetch(`${this.baseUrl}/${id}`, { method: 'DELETE' });
                return res.ok || res.status === 204 || res.status === 404;
            } catch {
                return false;
            }
        };
        
        // 直接高并发删除
        for (let i = 0; i < totalCount; i += CONCURRENT_LIMIT) {
            const batch = ids.slice(i, Math.min(i + CONCURRENT_LIMIT, totalCount));
            const batchResults = await Promise.all(batch.map(deleteOne));
            
            deleted += batchResults.filter(Boolean).length;
            
            // 更新进度
            const progress = Math.round(((i + batch.length) / totalCount) * 100);
            if (progressCallback) {
                progressCallback(progress, deleted);
            }
        }
        
        const elapsed = ((performance.now() - startTime) / 1000).toFixed(2);
        const speed = Math.round(deleted / parseFloat(elapsed));
        console.log(`【批量删除 v3.45.31】完成 - 删除${deleted}条, 耗时${elapsed}s, 速度${speed}条/秒`);
        
        // 清除缓存
        this.clearAssetsCache();
        
        return { deleted };
    }
};

// ========================================
// 工具函数
// ========================================

// 定义资产类型字符串（使用Unicode确保一致性）
const ASSET_TYPES = {
    FULL: '\u6574\u88C5',      // 整装 (U+6574 U+88C5)
    PARTIAL: '\u5C40\u88C5'    // 局装 (U+5C40 U+88C5)
};

// 判断是否为整装资产
function isFullAsset(assetType) {
    const type = (assetType || '').toString().trim();
    return type === ASSET_TYPES.FULL || 
           type.includes(ASSET_TYPES.FULL) || 
           type === '整装' || 
           type.includes('整装');
}

// 判断是否为局装资产
function isPartialAsset(assetType) {
    const type = (assetType || '').toString().trim();
    return type === ASSET_TYPES.PARTIAL || 
           type.includes(ASSET_TYPES.PARTIAL) || 
           type === '局装' || 
           type.includes('局装');
}

const Utils = {
    formatCurrency(value, decimals = 2) {
        return new Intl.NumberFormat('zh-CN', {
            style: 'currency',
            currency: 'CNY',
            minimumFractionDigits: decimals,
            maximumFractionDigits: decimals
        }).format(value || 0);
    },
    
    parseDisplayNumber(value) {
        if (typeof value === 'number') return value;
        const cleaned = String(value || '')
            .replace(/[¥,%\s,]/g, '')
            .replace(/[（）]/g, match => match === '（' ? '(' : ')');
        if (!cleaned) return 0;
        if (cleaned.startsWith('(') && cleaned.endsWith(')')) {
            return -(parseFloat(cleaned.slice(1, -1)) || 0);
        }
        return parseFloat(cleaned) || 0;
    },
    
    // 会计格式货币：负数显示为括号 (xxx)
    formatCurrencyAccounting(value, decimals = 2) {
        const num = value || 0;
        const absValue = Math.abs(num);
        const formatted = new Intl.NumberFormat('zh-CN', {
            style: 'currency',
            currency: 'CNY',
            minimumFractionDigits: decimals,
            maximumFractionDigits: decimals
        }).format(absValue);
        // 负数用括号包裹
        if (num < 0) {
            return '(' + formatted + ')';
        }
        return formatted;
    },
    
    // 会计格式数字：负数显示为括号 (xxx)
    formatNumberAccounting(value, decimals = 0) {
        const num = value || 0;
        const absValue = Math.abs(num);
        const formatted = new Intl.NumberFormat('zh-CN', {
            minimumFractionDigits: decimals,
            maximumFractionDigits: decimals
        }).format(absValue);
        if (num < 0) {
            return '(' + formatted + ')';
        }
        return formatted;
    },
    
    formatNumber(value) {
        return new Intl.NumberFormat('zh-CN').format(value || 0);
    },
    
    formatPercent(value) {
        return (value || 0).toFixed(2) + '%';
    },
    
    // 🆕 v3.45.54: 格式化为万元显示
    formatCurrencyWan(value, decimals = 2) {
        const wan = (value || 0) / 10000;
        return wan.toFixed(decimals) + '万';
    },
    
    formatDate(dateStr) {
        if (!dateStr) return '-';
        const date = new Date(dateStr);
        return date.toLocaleDateString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit'
        });
    },
    
    formatMonth(date) {
        return date.toLocaleDateString('zh-CN', {
            year: 'numeric',
            month: 'short'
        });
    },
    
    parseDate(dateStr) {
        if (!dateStr) return null;
        if (typeof dateStr === 'number') {
            const excelEpoch = new Date(1899, 11, 30);
            return new Date(excelEpoch.getTime() + dateStr * 86400000);
        }
        return new Date(dateStr);
    },
    
    calculateProgress(deducted, total) {
        if (!total || total === 0) return 0;
        return Math.min(100, Math.round((deducted / total) * 100));
    },
    
    addMonths(date, months) {
        const result = new Date(date);
        result.setMonth(result.getMonth() + months);
        return result;
    },
    
    getMonthDiff(date1, date2) {
        return (date2.getFullYear() - date1.getFullYear()) * 12 + 
               (date2.getMonth() - date1.getMonth());
    }
};

// ========================================
// EIR（有效利率）计算 - 基于年金模型
// ========================================

/**
 * 计算等额本金还款模式下的EIR（有效年利率）
 * 
 * 场景：资产以折扣价入池，每期平均偿还本金
 * PV = Σ(PMT / (1+r)^t) for t=1 to n
 * 其中 PMT = FV / n（每期偿还额）
 * 
 * @param {number} discountRate - 入池折扣率（如0.88表示88%）
 * @param {number} periods - 还款期数（月）
 * @returns {number} 年化EIR（百分比形式，如4.35表示4.35%）
 */
function calculateEIR(discountRate, periods) {
    if (discountRate >= 1 || periods <= 0) return 0;
    
    // PV = discountRate（假设面值为1）
    // PMT = 1 / periods（每期偿还额）
    const pv = discountRate;
    const pmt = 1 / periods;
    
    // 使用牛顿法求解月度IRR
    // 目标：找到r使得 PV = Σ(PMT / (1+r)^t)
    let r = 0.01; // 初始猜测月利率1%
    const maxIterations = 100;
    const tolerance = 1e-10;
    
    for (let i = 0; i < maxIterations; i++) {
        // 计算当前r下的现值和导数
        let npv = 0;
        let dnpv = 0; // NPV对r的导数
        
        for (let t = 1; t <= periods; t++) {
            const discountFactor = Math.pow(1 + r, t);
            npv += pmt / discountFactor;
            dnpv -= t * pmt / (discountFactor * (1 + r));
        }
        
        npv -= pv; // NPV = 现金流现值 - 初始投资
        
        // 牛顿迭代
        if (Math.abs(dnpv) < 1e-15) break;
        const rNew = r - npv / dnpv;
        
        if (Math.abs(rNew - r) < tolerance) {
            r = rNew;
            break;
        }
        r = rNew;
        
        // 防止负利率
        if (r < 0) r = 0.0001;
        if (r > 1) r = 0.5; // 防止发散
    }
    
    // 月度IRR转年化EIR
    const annualEIR = (Math.pow(1 + r, 12) - 1) * 100;
    return annualEIR;
}

/**
 * 计算不同期限下的EIR表
 * @param {number} discountRate - 入池折扣率
 * @param {Array} periodsList - 期限数组（月）
 * @returns {Object} 各期限对应的EIR
 */
function calculateEIRTable(discountRate, periodsList) {
    const result = {};
    periodsList.forEach(p => {
        result[p] = calculateEIR(discountRate, p);
    });
    return result;
}

/**
 * 计算加权平均EIR
 * @param {number} discountRate - 入池折扣率
 * @param {Object} periodWeights - {期限: 权重} 如 {18: 0.2, 24: 0.3, 36: 0.5}
 * @returns {number} 加权平均年化EIR
 */
function calculateWeightedEIR(discountRate, periodWeights) {
    let totalWeight = 0;
    let weightedSum = 0;
    
    for (const [period, weight] of Object.entries(periodWeights)) {
        const eir = calculateEIR(discountRate, parseInt(period));
        weightedSum += eir * weight;
        totalWeight += weight;
    }
    
    return totalWeight > 0 ? weightedSum / totalWeight : 0;
}

// ========================================
// Toast 通知
// ========================================

function showToast(message, type = 'success') {
    const container = document.getElementById('toastContainer');
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    
    const icons = {
        success: 'fa-check-circle',
        error: 'fa-exclamation-circle',
        warning: 'fa-exclamation-triangle'
    };
    
    toast.innerHTML = `<i class="fas ${icons[type]}"></i><span>${message}</span>`;
    container.appendChild(toast);
    
    setTimeout(() => {
        toast.style.animation = 'slideIn 0.3s ease reverse';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

