async function updateDashboard(forceReload = false) {
    try {
        // 【优化】如果AppState已有数据且不强制刷新，直接使用现有数据
        if (!forceReload && AppState.assets && AppState.assets.length > 0 && AppState.assetsModelId === API.getCurrentModelId()) {
            console.log(`【快速刷新】仪表盘使用现有数据: ${AppState.assets.length} 条`);
            updateAllStats();
            updateCategoryStats();
            updateMonthlyCashflowChart();
            updateAssetStructureChart();
            updateAssetDurationChart();
            updateCombinedCashflowChart();
            return;
        }
        
        console.log('开始加载仪表盘数据...');
        
        // 获取全部数据用于精确统计
        const result = await API.getAllAssets();
        const assets = Array.isArray(result.data) ? result.data : [];
        const total = result.total || assets.length;
        
        console.log(`仪表盘加载完成: ${assets.length} 条数据`);
        
        AppState.assets = assets;
        AppState.assetsModelId = API.getCurrentModelId();
        AppState.totalAssetCount = total;
        AppState.sampleRatio = 1; // 全量数据，不需要比例估算
        
        updateAllStats();
        updateCategoryStats();
        updateMonthlyCashflowChart();
        updateAssetStructureChart();
        updateAssetDurationChart();
        updateCombinedCashflowChart();
        
        // 【优化】更新侧边栏显示的资产数量
        ModelManager.renderModelList();
    } catch (error) {
        console.error('加载仪表盘数据失败:', error);
        AppState.assets = [];
        AppState.assetsModelId = API.getCurrentModelId();
        AppState.totalAssetCount = 0;
        AppState.sampleRatio = 1;
        updateAllStats();
        updateCategoryStats();
    }
}

function updateAllStats() {
    const assets = AppState.assets;
    const totalAssets = assets.length;
    
    // 调试：检查资产类型分布
    const typeDistribution = {};
    assets.forEach(a => {
        const type = a.asset_type || '未知';
        typeDistribution[type] = (typeDistribution[type] || 0) + 1;
    });
    console.log('资产类型分布:', typeDistribution);
    
    // 分类统计 - 使用统一的资产类型判断函数
    const fullAssets = assets.filter(a => isFullAsset(a.asset_type));
    const partialAssets = assets.filter(a => isPartialAsset(a.asset_type));
    
    console.log(`统计: 整装 ${fullAssets.length} 条, 局装 ${partialAssets.length} 条, 总计 ${totalAssets} 条`);
    
    // 计算各类总额（全量数据，精确计算）
    const fullTotal = fullAssets.reduce((sum, a) => sum + (parseFloat(a.total_deduction) || 0), 0);
    const fullDeducted = fullAssets.reduce((sum, a) => sum + (parseFloat(a.deducted_amount) || 0), 0);
    const partialTotal = partialAssets.reduce((sum, a) => sum + (parseFloat(a.total_deduction) || 0), 0);
    const partialDeducted = partialAssets.reduce((sum, a) => sum + (parseFloat(a.deducted_amount) || 0), 0);
    
    // 全部资产 = 整装 + 局装 (确保勾稽)
    const totalAmount = fullTotal + partialTotal;
    const deductedAmount = fullDeducted + partialDeducted;
    const remainingAmount = totalAmount - deductedAmount;
    
    // 保存分类数据供其他函数使用
    AppState.fullAssets = fullAssets;
    AppState.partialAssets = partialAssets;
    AppState.stats = {
        fullTotal, fullDeducted, partialTotal, partialDeducted,
        totalAmount, deductedAmount, remainingAmount
    };
    
    document.getElementById('totalAssetsAll').textContent = Utils.formatNumber(totalAssets);
    document.getElementById('totalAmountAll').textContent = Utils.formatCurrency(totalAmount, 0);
    document.getElementById('deductedAmountAll').textContent = Utils.formatCurrency(deductedAmount, 0);
    document.getElementById('remainingAmountAll').textContent = Utils.formatCurrency(remainingAmount, 0);
}

function updateCategoryStats() {
    // 使用已计算的分类数据
    const fullAssets = AppState.fullAssets || [];
    const partialAssets = AppState.partialAssets || [];
    const stats = AppState.stats || {};
    
    // 整装资产统计
    const fullCount = fullAssets.length;
    const fullRate = stats.fullTotal > 0 ? (stats.fullDeducted / stats.fullTotal * 100) : 0;
    
    document.getElementById('countFull').textContent = Utils.formatNumber(fullCount);
    document.getElementById('totalFull').textContent = Utils.formatCurrency(stats.fullTotal || 0, 0);
    document.getElementById('deductedFull').textContent = Utils.formatCurrency(stats.fullDeducted || 0, 0);
    document.getElementById('rateFull').textContent = Utils.formatPercent(fullRate);
    
    // 局装资产统计
    const partialCount = partialAssets.length;
    const partialRate = stats.partialTotal > 0 ? (stats.partialDeducted / stats.partialTotal * 100) : 0;
    
    document.getElementById('countPartial').textContent = Utils.formatNumber(partialCount);
    document.getElementById('totalPartial').textContent = Utils.formatCurrency(stats.partialTotal || 0, 0);
    document.getElementById('deductedPartial').textContent = Utils.formatCurrency(stats.partialDeducted || 0, 0);
    document.getElementById('ratePartial').textContent = Utils.formatPercent(partialRate);
}

