function updateAssetDurationChart() {
    const ctx = document.getElementById('assetDurationChart');
    if (!ctx) return;
    
    if (AppState.charts.duration) AppState.charts.duration.destroy();
    
    // 按剩余期限分组
    const durationBuckets = {
        '0-12月': { full: 0, partial: 0 },
        '13-24月': { full: 0, partial: 0 },
        '25-36月': { full: 0, partial: 0 },
        '37-48月': { full: 0, partial: 0 },
        '49-60月': { full: 0, partial: 0 },
        '60月以上': { full: 0, partial: 0 }
    };
    
    AppState.assets.forEach(asset => {
        const schedule = getAssetFutureSchedule(asset);
        const remainingPeriods = schedule.remainingPeriods;
        
        let bucket;
        if (remainingPeriods <= 12) bucket = '0-12月';
        else if (remainingPeriods <= 24) bucket = '13-24月';
        else if (remainingPeriods <= 36) bucket = '25-36月';
        else if (remainingPeriods <= 48) bucket = '37-48月';
        else if (remainingPeriods <= 60) bucket = '49-60月';
        else bucket = '60月以上';
        
        const remainingAmount = schedule.futureRecoverable;
        
        if (isFullAsset(asset.asset_type)) {
            durationBuckets[bucket].full += remainingAmount;
        } else {
            durationBuckets[bucket].partial += remainingAmount;
        }
    });
    
    const labels = Object.keys(durationBuckets);
    const fullData = labels.map(k => durationBuckets[k].full);
    const partialData = labels.map(k => durationBuckets[k].partial);
    
    AppState.charts.duration = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: labels,
            datasets: [
                {
                    label: '整装资产',
                    data: fullData,
                    backgroundColor: 'rgba(49, 130, 206, 0.75)',
                    borderColor: '#3182ce',
                    borderWidth: 1
                },
                {
                    label: '局装资产',
                    data: partialData,
                    backgroundColor: 'rgba(113, 128, 150, 0.65)',
                    borderColor: '#718096',
                    borderWidth: 1
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    position: 'top'
                },
                tooltip: {
                    callbacks: {
                        label: (context) => `${context.dataset.label}: ${Utils.formatCurrency(context.raw)}`
                    }
                }
            },
            scales: {
                y: {
                    beginAtZero: true,
                    ticks: { callback: (value) => '¥' + Utils.formatNumber(value / 10000) + '万' },
                    grid: { color: 'rgba(0, 0, 0, 0.05)' }
                },
                x: { grid: { display: false } }
            }
        }
    });
}

function calculateMonthlyCashflowByType(months) {
    const today = new Date();
    const cashflowResult = calculateDetailedCashflow(today, months, AppState.assets || []);
    return {
        labels: cashflowResult.periods.map(period => period.label),
        fullAmounts: cashflowResult.periods.map(period => period.fullAmount || 0),
        partialAmounts: cashflowResult.periods.map(period => period.partialAmount || 0),
        deductedAmounts: cashflowResult.periods.map(period => period.deductedAmount || 0),
        totalAmounts: cashflowResult.periods.map(period => period.totalAmount || 0)
    };
}

// ========================================
// 资产管理
// ========================================

async function loadAssets(page = 1, search = '', forceRefresh = false) {
    try {
        if (forceRefresh) {
            API.clearAssetsCache();
        }
        const result = await API.getAssets(page, AppState.pageSize, search);
        let assets = Array.isArray(result.data) ? result.data : [];
        
        // 应用类型筛选
        if (AppState.currentAssetTypeFilter) {
            assets = assets.filter(a => a.asset_type === AppState.currentAssetTypeFilter);
        }
        
        AppState.assets = assets;
        AppState.assetsModelId = API.getCurrentModelId();
        AppState.currentPage = result.page || 1;
        AppState.totalPages = Math.ceil((result.total || 0) / AppState.pageSize);
        
        renderAssetsTable();
        renderPagination();
    } catch (error) {
        console.error('加载资产数据失败:', error);
        showToast('加载数据失败', 'error');
    }
}

function renderAssetsTable() {
    const tbody = document.getElementById('assetsTableBody');
    
    if (AppState.assets.length === 0) {
        tbody.innerHTML = `
            <tr><td colspan="9">
                <div class="empty-state">
                    <i class="fas fa-database"></i>
                    <h3>暂无资产数据</h3>
                    <p>请点击"新增资产"或导入数据</p>
                </div>
            </td></tr>
        `;
        return;
    }
    
    tbody.innerHTML = AppState.assets.map(asset => {
        const progress = Utils.calculateProgress(
            parseFloat(asset.deducted_amount) || 0,
            parseFloat(asset.total_deduction) || 0
        );
        const typeClass = isFullAsset(asset.asset_type) ? 'full' : 'partial';
        
        return `
            <tr>
                <td><strong>${asset.asset_id || '-'}</strong></td>
                <td><span class="asset-type-badge ${typeClass}">${asset.asset_type || '-'}</span></td>
                <td>${Utils.formatCurrency(asset.total_deduction)}</td>
                <td>${Utils.formatCurrency(asset.deducted_amount)}</td>
                <td>${Utils.formatDate(asset.lease_start_date)}</td>
                <td>${asset.total_periods || '-'} 期</td>
                <td>${Utils.formatCurrency(asset.period_deduction)}</td>
                <td>
                    <div class="progress-bar">
                        <div class="progress-bar-fill" style="width: ${progress}%"></div>
                    </div>
                    <div class="progress-text">${progress}%</div>
                </td>
                <td>
                    <div class="action-btns">
                        <button class="action-btn edit" onclick="editAsset('${asset.id}')" title="编辑">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="action-btn delete" onclick="deleteAsset('${asset.id}')" title="删除">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

function renderPagination() {
    const container = document.getElementById('assetsPagination');
    
    if (AppState.totalPages <= 1) {
        container.innerHTML = '';
        return;
    }
    
    let html = `<button onclick="goToPage(${AppState.currentPage - 1})" ${AppState.currentPage === 1 ? 'disabled' : ''}>
        <i class="fas fa-chevron-left"></i></button>`;
    
    for (let i = 1; i <= AppState.totalPages; i++) {
        if (i === 1 || i === AppState.totalPages || 
            (i >= AppState.currentPage - 2 && i <= AppState.currentPage + 2)) {
            html += `<button class="${i === AppState.currentPage ? 'active' : ''}" 
                    onclick="goToPage(${i})">${i}</button>`;
        } else if (i === AppState.currentPage - 3 || i === AppState.currentPage + 3) {
            html += `<button disabled>...</button>`;
        }
    }
    
    html += `<button onclick="goToPage(${AppState.currentPage + 1})" 
            ${AppState.currentPage === AppState.totalPages ? 'disabled' : ''}>
        <i class="fas fa-chevron-right"></i></button>`;
    
    container.innerHTML = html;
}

function goToPage(page) {
    if (page < 1 || page > AppState.totalPages) return;
    loadAssets(page, document.getElementById('searchInput').value);
}

