/**
 * 更新单个模式的瀑布图
 */
function updateModeWaterfallChart(canvasId, chartData, title) {
    const ctx = document.getElementById(canvasId);
    if (!ctx) return;
    
    // 销毁旧图表
    const existingChart = Chart.getChart(ctx);
    if (existingChart) existingChart.destroy();
    
    // 只显示季度数据（每3个月）
    const quarterLabels = [];
    const quarterSeniorInterest = [];
    const quarterSubordInterest = [];
    const quarterSeniorPrincipal = [];
    const quarterSubordPrincipal = [];
    const quarterExcess = [];
    
    for (let i = 0; i < chartData.labels.length; i++) {
        if ((i + 1) % 3 === 0) { // 每个季度末
            quarterLabels.push(chartData.labels[i]);
            quarterSeniorInterest.push(chartData.seniorInterest[i]);
            quarterSubordInterest.push(chartData.subordinateInterest[i]);
            quarterSeniorPrincipal.push(chartData.seniorPrincipalRepay[i]);
            quarterSubordPrincipal.push(chartData.subordinatePrincipalRepay[i]);
            quarterExcess.push(chartData.excessReturn[i]);
        }
    }
    
    new Chart(ctx, {
        type: 'bar',
        data: {
            labels: quarterLabels,
            datasets: [
                { label: '优先级利息', data: quarterSeniorInterest, backgroundColor: '#e53e3e', stack: 'stack1' },
                { label: '劣后级收益', data: quarterSubordInterest, backgroundColor: '#718096', stack: 'stack1' },
                { label: '优先级本金', data: quarterSeniorPrincipal, backgroundColor: '#d69e2e', stack: 'stack1' },
                { label: '劣后级本金', data: quarterSubordPrincipal, backgroundColor: '#3182ce', stack: 'stack1' },
                { label: '超额/沉淀', data: quarterExcess, backgroundColor: '#38a169', stack: 'stack1' }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            plugins: {
                title: { display: false },
                legend: { display: true, position: 'bottom', labels: { boxWidth: 12, font: { size: 10 } } },
                tooltip: {
                    callbacks: { label: (context) => `${context.dataset.label}: ${Utils.formatCurrency(context.raw)}` }
                }
            },
            scales: {
                y: { stacked: true, ticks: { callback: (v) => '¥' + (v/10000).toFixed(0) + '万' } },
                x: { stacked: true, grid: { display: false } }
            }
        }
    });
}

