/**
 * 【v3.45.7重构】更新两种模式的明细表格
 * 分别更新过手摊还和固定摊还两个独立表格
 * @param {Object} ptCashflow - 过手摊还现金流
 * @param {Object} faCashflow - 固定摊还现金流
 * @param {Array} cashflowPeriods - 信托期内原始现金流（不含空置期）
 * @param {Array} fullLifecyclePeriods - 全生命周期原始现金流（可选，用于显示超期回款）
 * @param {Object} vacancyCashflow - 🆕 v3.45.58 含空置期但不含风险费用的原始回款（用于计算纯空置期影响）
 */
function updateComparisonTables(ptCashflow, faCashflow, cashflowPeriods = null, fullLifecyclePeriods = null, vacancyCashflow = null, monthlyPtCashflow = null, trustConfig = null) {
    // 获取展开状态
    const expandMonthlyPT = document.getElementById('expandMonthlyPT')?.checked || false;
    const expandMonthlyFA = document.getElementById('expandMonthlyFA')?.checked || false;
    
    // 【v3.44.6】获取资产端原始现金流（不含空置期和风险参数）
    // 优先使用传入的参数，其次从 fullAnalysisResults 获取
    const originalCashflowPeriods = cashflowPeriods || 
        (typeof fullAnalysisResults !== 'undefined' && fullAnalysisResults?.cashflowAnalysis?.periods) || 
        null;
    
    // 【v3.45.7】获取全生命周期原始现金流
    const fullLifecycleOriginalPeriods = fullLifecyclePeriods || 
        AppState.fullLifecycleOriginalPeriods || 
        null;
    
    // 🆕 v3.45.58: 获取含空置期的原始回款（用于计算纯空置期影响）
    const vacancyPeriods = vacancyCashflow?.periods || AppState.vacancyCashflowPeriods || null;
    
    // 更新过手摊还表格（传入原始现金流数据、全生命周期数据和空置期现金流）
    updatePTCashflowTable('ptCashflowTableBody', ptCashflow.periods, expandMonthlyPT, originalCashflowPeriods, fullLifecycleOriginalPeriods, vacancyPeriods);
    
    // 更新固定摊还表格（传入原始现金流数据、全生命周期数据和空置期现金流）
    updateFACashflowTable('faCashflowTableBody', faCashflow.periods, expandMonthlyFA, originalCashflowPeriods, fullLifecycleOriginalPeriods, vacancyPeriods);
    
    // 🆕 v3.46.1: 更新月度过手摊还表格
    const monthlyPt = monthlyPtCashflow || AppState.monthlyPtCashflow || null;
    if (monthlyPt) {
        updateMonthlyPTCashflowTable(monthlyPt, ptCashflow);
    }
    
    // 🆕 v3.46.2: 更新月度偿付瀑布表格
    const waterfallConfig = trustConfig || AppState.trustAnalysisConfig || null;
    if (monthlyPt && waterfallConfig) {
        updateMonthlyWaterfallTable(monthlyPt, waterfallConfig, originalCashflowPeriods, vacancyPeriods);
    }
    
    // 保存现金流数据到全局状态，供展开/折叠时使用
    AppState.cashflow = faCashflow;
    AppState.ptCashflow = ptCashflow;
    AppState.faCashflow = faCashflow;
    AppState.monthlyPtCashflow = monthlyPt; // 🆕 v3.46.1: 保存月度过手摊还数据
    AppState.trustAnalysisConfig = waterfallConfig; // 🆕 v3.46.2: 保存信托配置
    AppState.originalCashflowPeriods = originalCashflowPeriods; // 保存原始现金流供展开时使用
    AppState.fullLifecycleOriginalPeriods = fullLifecycleOriginalPeriods; // 【v3.45.7】保存全生命周期数据
    AppState.vacancyCashflowPeriods = vacancyPeriods; // 🆕 v3.45.58 保存含空置期原始回款
}

/**
 * 【v3.45.7重构】更新过手摊还现金流表格
 * 修复：原始回款 vs 信托端回款的显示逻辑
 * - 原始回款：不含空置期的理论回款（信托期内）
 * - 信托端回款：含空置期调整后的实际到账
 * - 超期回款：超出信托期的原始回款（来自全生命周期）
 * @param {Array} fullLifecyclePeriods - 全生命周期原始现金流（可选）
 * @param {Array} vacancyPeriods - 🆕 v3.45.58 含空置期的原始回款（用于计算纯空置期影响）
 */
function updatePTCashflowTable(tableBodyId, periods, expandMonthly = false, cashflowPeriods = null, fullLifecyclePeriods = null, vacancyPeriods = null) {
    const tbody = document.getElementById(tableBodyId);
    const summaryBar = document.getElementById('ptSummaryBar');
    if (!tbody) return;
    
    // 只处理季度末数据
    const quarterPeriods = periods.filter(p => p.isQuarterEnd);
    
    // 🆕 v3.45.32: 累计超额仍使用自累加，因为Excel导出也使用自累加
    let cumulativeExcess = 0;
    let rowsHtml = [];
    
    // 🆕 v3.45.19: 按季度汇总资产端原始回款
    // 原始回款 = 已代扣金额（第一月）+ 未来回款（按期展开）
    // 原始回款总额应该等于总代扣金额（不考虑空置期、违约等影响）
    const getOriginalCashflow = (quarterIndex) => {
        if (!cashflowPeriods || cashflowPeriods.length === 0) return 0;
        const startMonth = quarterIndex * 3;
        let total = 0;
        for (let i = startMonth; i < startMonth + 3 && i < cashflowPeriods.length; i++) {
            const period = cashflowPeriods[i];
            // 🆕 v3.45.19: 原始回款 = totalAmount = 已代扣(第一月) + 未来回款
            // totalAmount 在 calculateDetailedCashflow 中已定义为：periodDeductedAmount + futureAmount
            total += (period?.totalAmount || 0);
        }
        return total;
    };
    
    // 🆕 v3.45.58: 按季度汇总含空置期的原始回款（用于计算纯空置期影响）
    const getVacancyCashflow = (quarterIndex) => {
        if (!vacancyPeriods || vacancyPeriods.length === 0) return null;
        const startMonth = quarterIndex * 3;
        let total = 0;
        for (let i = startMonth; i < startMonth + 3 && i < vacancyPeriods.length; i++) {
            const period = vacancyPeriods[i];
            total += (period?.totalAmount || 0);
        }
        return total;
    };
    
    // 计算合计数据
    const totals = {
        originalCashflow: 0,
        assetInflow: 0,
        defaultAmount: 0,
        recoveryAmount: 0,
        managementFee: 0,
        taxAmount: 0,
        netInflow: 0,
        seniorInterest: 0,
        seniorPrincipal: 0,
        subordinateInterest: 0,
        subordinatePrincipal: 0,
        excessReturn: 0
    };
    
    quarterPeriods.forEach((p, index) => {
        const netInflow = p.netInflow !== undefined ? p.netInflow : p.assetInflow;
        const originalCashflow = getOriginalCashflow(index);
        
        // 累加合计
        totals.originalCashflow += originalCashflow;
        totals.assetInflow += (p.assetInflow || 0);
        totals.defaultAmount += (p.defaultAmount || 0);
        totals.recoveryAmount += (p.recoveryAmount || 0);
        totals.managementFee += (p.managementFee || 0);
        totals.taxAmount += (p.taxAmount || 0);
        totals.netInflow += netInflow;
        totals.seniorInterest += (p.seniorInterest || 0);
        totals.seniorPrincipal += (p.seniorPrincipalRepay || 0);
        totals.subordinateInterest += (p.subordinateInterest || 0);
        totals.subordinatePrincipal += (p.subordinatePrincipalRepay || 0);
        totals.excessReturn += (p.excessReturn || 0);
        
        const excessReturn = p.excessReturn || 0;
        cumulativeExcess += excessReturn;
        
        // 🆕 v3.45.22: 月度明细展开（过手摊还）
        // 原始回款 = 已代扣（第一月）+ 未来回款（不含空置期）
        // 资产回款 = 已代扣（第一月）+ 未来回款（含空置期影响）
        // 空置期影响 = 资产回款 - 原始回款
        if (expandMonthly && p.monthlyDetails && p.monthlyDetails.length > 0) {
            p.monthlyDetails.forEach((m, mIdx) => {
                const periodData = cashflowPeriods && cashflowPeriods[index * 3 + mIdx];
                const futureAmount = periodData?.futureAmount || 0;
                const deductedAmt = periodData?.deductedAmount || m.deductedAmount || 0;
                const hasDeducted = deductedAmt > 0.01;
                
                // 原始回款列：第一月 = 已代扣 + 未来回款，后续月 = 未来回款
                const monthOriginal = futureAmount + deductedAmt;
                
                // 🆕 v3.45.30: 完整月度明细行（17列）- 过手摊还
                const monthVacancy = (m.assetInflow || 0) - monthOriginal;
                const monthVacancyDisplay = Math.abs(monthVacancy) < 0.01 ? '-' : `${monthVacancy > 0 ? '+' : ''}${Utils.formatCurrency(monthVacancy)}`;
                const monthVacancyColor = monthVacancy > 0.01 ? '#059669' : (monthVacancy < -0.01 ? '#dc2626' : '#94a3b8');
                
                const monthRow = `
                    <tr class="monthly-row" ${hasDeducted ? 'style="background: #fef2f2;"' : ''}>
                        <td style="color: #94a3b8; padding-left: 14px;">${m.month}</td>
                        <td style="font-size: 0.62rem;">${m.label}${hasDeducted ? '<span style="color:#dc2626;font-size:7px;">(垫)</span>' : ''}</td>
                        <td class="number" style="color: #805ad5;">${Utils.formatCurrency(monthOriginal)}</td>
                        <td class="number">${Utils.formatCurrency(m.assetInflow || 0)}</td>
                        <td class="number" style="color: ${monthVacancyColor};">${monthVacancyDisplay}</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number">${Utils.formatCurrency(m.netInflow || 0)}</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                    </tr>
                `;
                rowsHtml.push(monthRow);
            });
        }
        
        const quarterRowClass = expandMonthly ? 'quarter-row' : '';
        const seniorCleared = (p.seniorBalance || 0) <= 0.01;
        const subCleared = (p.subordinateBalance || 0) <= 0.01;
        const highlightClass = (seniorCleared && subCleared) ? 'highlight-row' : '';
        
        // 🆕 v3.45.58: 计算纯空置期影响 = 含空置期原始回款 - 不含空置期原始回款
        // 修复：之前用 (p.assetInflow - originalCashflow) 计算，但 p.assetInflow 已包含违约/回收/管理费
        const vacancyCashflowForQuarter = getVacancyCashflow(index);
        const quarterVacancyEffect = vacancyCashflowForQuarter !== null 
            ? (vacancyCashflowForQuarter - originalCashflow)  // 纯空置期影响
            : (p.assetInflow || 0) - originalCashflow;        // 回退到旧逻辑
        const vacancyColor = quarterVacancyEffect > 0.01 ? '#059669' : (quarterVacancyEffect < -0.01 ? '#dc2626' : '#94a3b8');
        const vacancyDisplay = Math.abs(quarterVacancyEffect) < 0.01 ? '-' : 
            `${quarterVacancyEffect > 0 ? '+' : ''}${Utils.formatCurrency(quarterVacancyEffect)}`;
        
        // 累计空置期影响
        totals.vacancyEffect = (totals.vacancyEffect || 0) + quarterVacancyEffect;
        
        // 🆕 v3.45.30: 完整表格行（17列）- 过手摊还
        const quarterRow = `
            <tr class="${quarterRowClass} ${highlightClass}">
                <td><strong>Q${Math.ceil(p.period / 3)}</strong></td>
                <td>${p.label}</td>
                <td class="number" style="color: #805ad5;">${Utils.formatCurrency(originalCashflow)}</td>
                <td class="number">${Utils.formatCurrency(p.assetInflow || 0)}</td>
                <td class="number" style="color: ${vacancyColor};">${vacancyDisplay}</td>
                <td class="number" style="color: #dc2626;">${Utils.formatCurrency(p.defaultAmount || 0)}</td>
                <td class="number" style="color: #059669;">${Utils.formatCurrency(p.recoveryAmount || 0)}</td>
                <td class="number" style="color: #94a3b8;">${Utils.formatCurrency(p.managementFee || 0)}</td>
                <td class="number">${Utils.formatCurrency(netInflow)}</td>
                <td class="number" style="color: #3182ce;">${Utils.formatCurrency(p.seniorInterest || 0)}</td>
                <td class="number" style="color: #3182ce;">${Utils.formatCurrency(p.seniorPrincipalRepay || 0)}</td>
                <td class="number ${seniorCleared ? 'text-success' : ''}">${Utils.formatCurrency(p.seniorBalance || 0)}</td>
                <td class="number" style="color: #e53e3e;">${Utils.formatCurrency(p.subordinateInterest || 0)}</td>
                <td class="number" style="color: #e53e3e;">${Utils.formatCurrency(p.subordinatePrincipalRepay || 0)}</td>
                <td class="number ${subCleared ? 'text-success' : ''}">${Utils.formatCurrency(p.subordinateBalance || 0)}</td>
                <td class="number" style="color: #38a169; font-weight: 500;">${Utils.formatCurrency(excessReturn)}</td>
                <td class="number" style="color: #38a169; font-weight: 600;">${Utils.formatCurrency(cumulativeExcess)}</td>
            </tr>
        `;
        rowsHtml.push(quarterRow);
    });
    
    // 🆕 v3.45.19: 计算已代扣金额（从cashflowPeriods获取，用于单独显示）
    let totalDeductedAmount = 0;
    if (cashflowPeriods && cashflowPeriods.length > 0) {
        cashflowPeriods.forEach(p => {
            totalDeductedAmount += (p?.deductedAmount || 0);
        });
    }
    
    // 【v3.45.19】统计口径修正：
    // - totals.originalCashflow 已经是 totalAmount 的累加，已包含已代扣金额
    // - 原始回款 = totals.originalCashflow（已含已代扣+未来回款）
    // - 资产回款 = totals.assetInflow（已含已代扣+未来回款+空置期影响）
    // - 空置期影响 = 资产回款 - 原始回款
    const originalTotal = totals.originalCashflow;  // 原始回款（已含已代扣，不含空置期）
    const assetTotal = totals.assetInflow;  // 资产回款（已含已代扣，含空置期影响）
    
    // 🆕 v3.45.19: 调试日志
    console.log('【过手摊还汇总 v3.45.19】数据验证:');
    console.log(`  已代扣金额: ${Utils.formatCurrency(totalDeductedAmount)}`);
    console.log(`  原始回款合计: ${Utils.formatCurrency(originalTotal)}`);
    console.log(`  资产回款合计: ${Utils.formatCurrency(assetTotal)}`);
    console.log(`  空置期影响: ${Utils.formatCurrency(assetTotal - originalTotal)}`);
    
    // 空置期影响 = 资产回款 - 原始回款
    // 理论上：如果原始回款 = 总代扣金额，空置期影响应该体现为时间分布的变化
    const vacancyEffect = assetTotal - originalTotal;
    
    // 计算全生命周期
    let fullLifecycleTotal = originalTotal;
    let beyondTrustPeriodAmount = 0;
    if (fullLifecyclePeriods && fullLifecyclePeriods.length > 0) {
        fullLifecycleTotal = fullLifecyclePeriods.reduce((sum, p) => sum + (p?.totalAmount || 0), 0);
        beyondTrustPeriodAmount = Math.max(0, fullLifecycleTotal - originalTotal);
    }
    
    // 🆕 v3.45.19: 更新汇总栏（表格上方小字）
    if (summaryBar) {
        const trustMonths = quarterPeriods.length * 3;
        const ptBeyondPercent = fullLifecycleTotal > 0 ? (beyondTrustPeriodAmount / fullLifecycleTotal * 100).toFixed(1) : 0;
        
        let summaryHtml = `
            <span class="summary-item"><strong>期限:</strong> <span class="summary-value">${trustMonths}月</span></span>
            <span class="summary-item" title="已代扣(安全垫)+未来回款(不含空置期)，应等于总代扣金额"><strong>原始回款:</strong> <span class="summary-value val-purple">${Utils.formatCurrency(originalTotal)}</span></span>
            <span class="summary-item" title="已代扣(安全垫)+未来回款(含空置期影响)"><strong>资产回款:</strong> <span class="summary-value val-blue">${Utils.formatCurrency(assetTotal)}</span></span>
        `;
        
        // 🆕 v3.45.18: 显示空置期影响（替代前期移入）
        // 空置期影响 = 每12个月续租导致的回款推迟效应
        if (Math.abs(vacancyEffect) > 0.01) {
            const effectTitle = '整装资产每12个月续租产生的空置期推迟效应，影响未来回款的时间分布';
            const effectColor = vacancyEffect > 0 ? 'val-teal' : 'val-orange';
            summaryHtml += `
                <span class="summary-item" title="${effectTitle}"><strong>空置期影响:</strong> <span class="summary-value ${effectColor}">${vacancyEffect > 0 ? '+' : ''}${Utils.formatCurrency(vacancyEffect)}</span></span>
            `;
        }
        
        // 显示已代扣金额（安全垫）
        if (totalDeductedAmount > 0.01) {
            summaryHtml += `
                <span class="summary-item" title="已代扣金额(安全垫)，第一月到账，原始回款和资产回款均包含此项"><strong>已代扣:</strong> <span class="summary-value" style="color: #dc2626;">${Utils.formatCurrency(totalDeductedAmount)}</span></span>
            `;
        }
        
        summaryHtml += `
            <span class="summary-item"><strong>净回款:</strong> <span class="summary-value val-yellow">${Utils.formatCurrency(totals.netInflow)}</span></span>
            <span class="summary-item"><strong>累计超额:</strong> <span class="summary-value val-green">${Utils.formatCurrency(cumulativeExcess)}</span></span>
        `;
        
        // 60期后回款
        summaryHtml += `
            <span class="summary-item summary-highlight" title="资产期限超出信托期的原始回款"><strong>${trustMonths}期后:</strong> <span class="summary-value val-orange">${Utils.formatCurrency(beyondTrustPeriodAmount)}${beyondTrustPeriodAmount > 0.01 ? ' (' + ptBeyondPercent + '%)' : ''}</span></span>
        `;
        
        // 全周期原始回款
        summaryHtml += `
            <span class="summary-item" title="资产全生命周期的原始回款总额"><strong>全周期:</strong> <span class="summary-value val-teal">${Utils.formatCurrency(fullLifecycleTotal)}</span></span>
        `;
        
        summaryBar.innerHTML = summaryHtml;
        summaryBar.style.display = 'flex';
    }
    
    tbody.innerHTML = rowsHtml.join('');
}

/**
 * 🆕 v3.46.1: 更新月度过手摊还现金流表格
 * 每月一行，展示完整的瀑布分配明细
 * @param {Object} monthlyPtCashflow - 月度过手摊还计算结果
 * @param {Object} quarterlyPtCashflow - 季度过手摊还计算结果（用于对比）
 */
function updateMonthlyPTCashflowTable(monthlyPtCashflow, quarterlyPtCashflow) {
    const tbody = document.getElementById('monthlyPtCashflowTableBody');
    const summaryBar = document.getElementById('monthlyPtSummaryBar');
    const compareDiv = document.getElementById('monthlyVsQuarterlyCompare');
    if (!tbody) return;
    
    const periods = monthlyPtCashflow.periods;
    if (!periods || periods.length === 0) {
        tbody.innerHTML = '<tr><td colspan="16" class="loading">无数据</td></tr>';
        return;
    }
    
    let cumulativeExcess = 0;
    let rowsHtml = [];
    
    // 合计
    const totals = {
        assetInflow: 0, defaultAmount: 0, recoveryAmount: 0,
        managementFee: 0, taxAmount: 0, netInflow: 0,
        seniorInterest: 0, seniorPrincipal: 0,
        subordinateInterest: 0, subordinatePrincipal: 0,
        excessReturn: 0
    };
    
    periods.forEach((p) => {
        const monthNumber = p.period;
        const isQuarterEnd = monthNumber % 3 === 0;
        const seniorCleared = (p.seniorBalance || 0) <= 0.01;
        const subCleared = (p.subordinateBalance || 0) <= 0.01;
        const highlightClass = (seniorCleared && subCleared) ? 'highlight-row' : '';
        // 季度末行加粗背景，便于视觉分隔
        const quarterEndStyle = isQuarterEnd ? 'background: #f8fafc; border-bottom: 2px solid #e2e8f0;' : '';
        const hasDeducted = (p.deductedAmount || 0) > 0.01;
        
        const excessReturn = p.excessReturn || 0;
        cumulativeExcess += excessReturn;
        
        // 累加合计
        totals.assetInflow += (p.assetInflow || 0);
        totals.defaultAmount += (p.defaultAmount || 0);
        totals.recoveryAmount += (p.recoveryAmount || 0);
        totals.managementFee += (p.managementFee || 0);
        totals.taxAmount += (p.taxAmount || 0);
        totals.netInflow += (p.netInflow || 0);
        totals.seniorInterest += (p.seniorInterest || 0);
        totals.seniorPrincipal += (p.seniorPrincipalRepay || 0);
        totals.subordinateInterest += (p.subordinateInterest || 0);
        totals.subordinatePrincipal += (p.subordinatePrincipalRepay || 0);
        totals.excessReturn += excessReturn;
        
        const row = `
            <tr class="${highlightClass}" style="${quarterEndStyle}">
                <td>${isQuarterEnd ? '<strong>' + monthNumber + '</strong>' : monthNumber}${hasDeducted ? '<span style="color:#dc2626;font-size:7px;">(垫)</span>' : ''}</td>
                <td style="font-size: 0.62rem;">${p.label}</td>
                <td class="number">${Utils.formatCurrency(p.assetInflow || 0)}</td>
                <td class="number" style="color: #dc2626;">${Utils.formatCurrency(p.defaultAmount || 0)}</td>
                <td class="number" style="color: #059669;">${Utils.formatCurrency(p.recoveryAmount || 0)}</td>
                <td class="number" style="color: #94a3b8;">${Utils.formatCurrency(p.managementFee || 0)}</td>
                <td class="number" style="color: #d97706;">${Utils.formatCurrency(p.taxAmount || 0)}</td>
                <td class="number">${Utils.formatCurrency(p.netInflow || 0)}</td>
                <td class="number" style="color: #3182ce;">${Utils.formatCurrency(p.seniorInterest || 0)}</td>
                <td class="number" style="color: #3182ce;">${Utils.formatCurrency(p.seniorPrincipalRepay || 0)}</td>
                <td class="number ${seniorCleared ? 'text-success' : ''}">${Utils.formatCurrency(p.seniorBalance || 0)}</td>
                <td class="number" style="color: #e53e3e;">${Utils.formatCurrency(p.subordinateInterest || 0)}</td>
                <td class="number" style="color: #e53e3e;">${Utils.formatCurrency(p.subordinatePrincipalRepay || 0)}</td>
                <td class="number ${subCleared ? 'text-success' : ''}">${Utils.formatCurrency(p.subordinateBalance || 0)}</td>
                <td class="number" style="color: #38a169; font-weight: 500;">${Utils.formatCurrency(excessReturn)}</td>
                <td class="number" style="color: #38a169; font-weight: 600;">${Utils.formatCurrency(cumulativeExcess)}</td>
            </tr>
        `;
        rowsHtml.push(row);
    });
    
    tbody.innerHTML = rowsHtml.join('');
    
    // 更新汇总栏
    if (summaryBar) {
        const trustMonths = periods.length;
        let summaryHtml = `
            <span class="summary-item"><strong>期限:</strong> <span class="summary-value">${trustMonths}月</span></span>
            <span class="summary-item"><strong>资产回款:</strong> <span class="summary-value val-blue">${Utils.formatCurrency(totals.assetInflow)}</span></span>
            <span class="summary-item"><strong>净回款:</strong> <span class="summary-value val-yellow">${Utils.formatCurrency(totals.netInflow)}</span></span>
            <span class="summary-item"><strong>优先息:</strong> <span class="summary-value" style="color:#3182ce;">${Utils.formatCurrency(totals.seniorInterest)}</span></span>
            <span class="summary-item"><strong>劣后息:</strong> <span class="summary-value" style="color:#e53e3e;">${Utils.formatCurrency(totals.subordinateInterest)}</span></span>
            <span class="summary-item"><strong>税金:</strong> <span class="summary-value" style="color:#d97706;">${Utils.formatCurrency(totals.taxAmount)}</span></span>
            <span class="summary-item"><strong>累计超额:</strong> <span class="summary-value val-green">${Utils.formatCurrency(cumulativeExcess)}</span></span>
        `;
        summaryBar.innerHTML = summaryHtml;
        summaryBar.style.display = 'flex';
    }
    
    // 月度 vs 季度对比
    if (compareDiv && quarterlyPtCashflow) {
        const qExcess = quarterlyPtCashflow.totalExcess || 0;
        const mExcess = monthlyPtCashflow.totalExcess || 0;
        const excessDiff = mExcess - qExcess;
        const qSeniorInt = quarterlyPtCashflow.totalSeniorInterest || 0;
        const mSeniorInt = monthlyPtCashflow.totalSeniorInterest || 0;
        const intDiff = mSeniorInt - qSeniorInt;
        const qSubInt = quarterlyPtCashflow.totalSubordinateInterest || 0;
        const mSubInt = monthlyPtCashflow.totalSubordinateInterest || 0;
        const subIntDiff = mSubInt - qSubInt;
        const qTax = quarterlyPtCashflow.totalTaxAmount || 0;
        const mTax = monthlyPtCashflow.totalTaxAmount || 0;
        const taxDiff = mTax - qTax;
        
        // 找到清偿时点
        const qClear = quarterlyPtCashflow.clearTimes || {};
        const mClear = monthlyPtCashflow.clearTimes || {};
        
        const formatDiff = (val) => {
            if (Math.abs(val) < 0.01) return '<span style="color:#94a3b8;">-</span>';
            const color = val > 0 ? '#dc2626' : '#059669';
            const sign = val > 0 ? '+' : '';
            return `<span style="color:${color};font-weight:600;">${sign}${Utils.formatCurrency(val)}</span>`;
        };
        
        compareDiv.innerHTML = `
            <div style="font-size:0.68rem;font-weight:600;color:#4338ca;margin-bottom:4px;">
                <i class="fas fa-exchange-alt"></i> 月度摊还 vs 季度摊还 对比
            </div>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:6px;font-size:0.62rem;">
                <div style="padding:4px 8px;background:#fff;border-radius:4px;border:1px solid #e5e7eb;">
                    <div style="color:#64748b;">优先级利息差异</div>
                    <div>${formatDiff(intDiff)}</div>
                    <div style="color:#94a3b8;font-size:0.56rem;">月度: ${Utils.formatCurrency(mSeniorInt)} / 季度: ${Utils.formatCurrency(qSeniorInt)}</div>
                </div>
                <div style="padding:4px 8px;background:#fff;border-radius:4px;border:1px solid #e5e7eb;">
                    <div style="color:#64748b;">劣后级利息差异</div>
                    <div>${formatDiff(subIntDiff)}</div>
                    <div style="color:#94a3b8;font-size:0.56rem;">月度: ${Utils.formatCurrency(mSubInt)} / 季度: ${Utils.formatCurrency(qSubInt)}</div>
                </div>
                <div style="padding:4px 8px;background:#fff;border-radius:4px;border:1px solid #e5e7eb;">
                    <div style="color:#64748b;">税金差异</div>
                    <div>${formatDiff(taxDiff)}</div>
                    <div style="color:#94a3b8;font-size:0.56rem;">月度: ${Utils.formatCurrency(mTax)} / 季度: ${Utils.formatCurrency(qTax)}</div>
                </div>
                <div style="padding:4px 8px;background:#fff;border-radius:4px;border:1px solid #e5e7eb;">
                    <div style="color:#64748b;">超额收益差异</div>
                    <div>${formatDiff(excessDiff)}</div>
                    <div style="color:#94a3b8;font-size:0.56rem;">月度: ${Utils.formatCurrency(mExcess)} / 季度: ${Utils.formatCurrency(qExcess)}</div>
                </div>
                <div style="padding:4px 8px;background:#fff;border-radius:4px;border:1px solid #e5e7eb;">
                    <div style="color:#64748b;">优先级还清</div>
                    <div style="font-weight:600;color:#3182ce;">月度: ${mClear.seniorClearTime ? '第' + mClear.seniorClearTime.period + '月' : '未还清'} / 季度: ${qClear.seniorClearTime ? 'Q' + qClear.seniorClearTime.quarter : '未还清'}</div>
                </div>
                <div style="padding:4px 8px;background:#fff;border-radius:4px;border:1px solid #e5e7eb;">
                    <div style="color:#64748b;">劣后级还清</div>
                    <div style="font-weight:600;color:#e53e3e;">月度: ${mClear.subordinateClearTime ? '第' + mClear.subordinateClearTime.period + '月' : '未还清'} / 季度: ${qClear.subordinateClearTime ? 'Q' + qClear.subordinateClearTime.quarter : '未还清'}</div>
                </div>
            </div>
            <div style="margin-top:4px;font-size:0.56rem;color:#6b7280;">
                <i class="fas fa-info-circle"></i> 月度摊还因每月即偿本金，减少了利息计提基础，通常优先级利息更少、超额收益更多。季度暂存利息在月度模式下不存在。
            </div>
        `;
        compareDiv.style.display = 'block';
    }
}

/**
 * 🆕 v3.46.2: 月度偿付瀑布表格（精简版） + 优先级本息覆盖倍数
 * 
 * 精简8列：资产流入 | 信保流入 | 费用 | 优先级利息 | 劣后级利息 | 优先级本金 | 劣后级本金 | 剩余资金
 * 
 * 资产流入 = 净资产回款 + 沉淀利息（不含信保释放）
 *   其中净资产回款已考虑：短期沉淀资金利息、违约损失、空置期、退租率
 * 信保流入 = 信保基金释放（仅最后一期）
 * 费用 = 管理费（信托管理费+资产服务费+保管费）+ 税金 + 前置费用
 * 
 * 优先级本息覆盖倍数 = (优先级本息 + 劣后级本金 + 剩余资金) ÷ 优先级(本金+预期收益)
 */
function updateMonthlyWaterfallTable(monthlyPtCashflow, config, originalPeriods, vacancyPeriods) {
    const tbody = document.getElementById('monthlyWaterfallTableBody');
    const summaryBar = document.getElementById('waterfallSummaryBar');
    const coveragePanel = document.getElementById('seniorCoveragePanel');
    if (!tbody) return;
    
    const periods = monthlyPtCashflow.periods;
    if (!periods || periods.length === 0) {
        tbody.innerHTML = '<tr><td colspan="10" class="loading">无数据</td></tr>';
        return;
    }
    
    let rowsHtml = [];
    
    // 合计
    const totals = {
        assetInflow: 0, guaranteeInflow: 0, fees: 0,
        seniorInterest: 0, subordinateInterest: 0,
        seniorPrincipal: 0, subordinatePrincipal: 0,
        residual: 0
    };
    
    periods.forEach((p) => {
        const monthNumber = p.period;
        const isQuarterEnd = monthNumber % 3 === 0;
        const quarterEndStyle = isQuarterEnd ? 'border-bottom: 2px solid #e2e8f0;' : '';
        
        // 【资产流入】= 净资产回款 + 沉淀利息（不含信保释放）
        // 净资产回款 = 原始回款 - 违约 + 回收 - 管理费（已考虑违约/空置/退租）
        // 沉淀利息 = 信保基金利息 + 超额沉淀利息
        const netAssetInflow = p.netInflow || 0;
        const idleInterest = p.interestIncome || 0;
        const assetInflow = netAssetInflow + idleInterest;
        
        // 【信保流入】最后一期释放
        const guaranteeInflow = p.guaranteeFundRelease || 0;
        
        // 【费用】= 管理费（已在资产端扣除，这里显示）+ 税金 + 前置费用
        // managementFee 含信托管理费+资产服务费+保管费
        const fees = (p.taxAmount || 0) + (p.upfrontFee || 0);
        // 注意：管理费已在 netInflow 中扣除，不再重复计入费用列
        // 但为了展示完整费用，将管理费也加入显示
        const displayFees = fees + (p.managementFee || 0);
        
        // 【投资人分配】
        const seniorInterest = p.seniorInterest || 0;
        const subordinateInterest = p.subordinateInterest || 0;
        const seniorPrincipalRepay = p.seniorPrincipalRepay || 0;
        const subordinatePrincipalRepay = p.subordinatePrincipalRepay || 0;
        
        // 【剩余资金】
        const residual = p.excessReturn || 0;
        
        // 累加
        totals.assetInflow += assetInflow;
        totals.guaranteeInflow += guaranteeInflow;
        totals.fees += displayFees;
        totals.seniorInterest += seniorInterest;
        totals.subordinateInterest += subordinateInterest;
        totals.seniorPrincipal += seniorPrincipalRepay;
        totals.subordinatePrincipal += subordinatePrincipalRepay;
        totals.residual += residual;
        
        const seniorCleared = (p.seniorBalance || 0) <= 0.01;
        const subCleared = (p.subordinateBalance || 0) <= 0.01;
        const highlightClass = (seniorCleared && subCleared) ? 'highlight-row' : '';
        const dash = '<span style="color:#94a3b8;">-</span>';
        
        const row = `
            <tr class="${highlightClass}" style="${quarterEndStyle}">
                <td>${isQuarterEnd ? '<strong>' + monthNumber + '</strong>' : monthNumber}</td>
                <td style="font-size:0.6rem;">${p.label}</td>
                <td class="number" style="color:#059669;">${Utils.formatCurrency(assetInflow)}</td>
                <td class="number" style="color:#0d9488;">${guaranteeInflow > 0.01 ? Utils.formatCurrency(guaranteeInflow) : dash}</td>
                <td class="number" style="color:#b45309;">${displayFees > 0.01 ? Utils.formatCurrency(displayFees) : dash}</td>
                <td class="number" style="color:#3182ce;">${Utils.formatCurrency(seniorInterest)}</td>
                <td class="number" style="color:#e53e3e;">${Utils.formatCurrency(subordinateInterest)}</td>
                <td class="number" style="color:#3182ce;">${Utils.formatCurrency(seniorPrincipalRepay)}</td>
                <td class="number" style="color:#e53e3e;">${Utils.formatCurrency(subordinatePrincipalRepay)}</td>
                <td class="number" style="color:#7c3aed;font-weight:${residual > 0.01 ? '600' : '400'};">${residual > 0.01 ? Utils.formatCurrency(residual) : dash}</td>
            </tr>
        `;
        rowsHtml.push(row);
    });
    
    // 合计行
    rowsHtml.push(`
        <tr style="background:#f1f5f9;font-weight:600;border-top:3px double #94a3b8;">
            <td colspan="2" style="text-align:center;color:#1e293b;">合计</td>
            <td class="number" style="color:#059669;">${Utils.formatCurrency(totals.assetInflow)}</td>
            <td class="number" style="color:#0d9488;">${Utils.formatCurrency(totals.guaranteeInflow)}</td>
            <td class="number" style="color:#b45309;">${Utils.formatCurrency(totals.fees)}</td>
            <td class="number" style="color:#3182ce;">${Utils.formatCurrency(totals.seniorInterest)}</td>
            <td class="number" style="color:#e53e3e;">${Utils.formatCurrency(totals.subordinateInterest)}</td>
            <td class="number" style="color:#3182ce;">${Utils.formatCurrency(totals.seniorPrincipal)}</td>
            <td class="number" style="color:#e53e3e;">${Utils.formatCurrency(totals.subordinatePrincipal)}</td>
            <td class="number" style="color:#7c3aed;">${Utils.formatCurrency(totals.residual)}</td>
        </tr>
    `);
    
    tbody.innerHTML = rowsHtml.join('');
    
    // 汇总栏
    if (summaryBar) {
        summaryBar.innerHTML = `
            <span class="summary-item"><strong>资产流入:</strong> <span class="summary-value val-green">${Utils.formatCurrency(totals.assetInflow)}</span></span>
            <span class="summary-item"><strong>信保流入:</strong> <span class="summary-value" style="color:#0d9488;">${Utils.formatCurrency(totals.guaranteeInflow)}</span></span>
            <span class="summary-item"><strong>费用:</strong> <span class="summary-value" style="color:#b45309;">${Utils.formatCurrency(totals.fees)}</span></span>
            <span class="summary-item"><strong>优先级本息:</strong> <span class="summary-value" style="color:#3182ce;">${Utils.formatCurrency(totals.seniorInterest + totals.seniorPrincipal)}</span></span>
            <span class="summary-item"><strong>劣后级本息:</strong> <span class="summary-value" style="color:#e53e3e;">${Utils.formatCurrency(totals.subordinateInterest + totals.subordinatePrincipal)}</span></span>
            <span class="summary-item"><strong>剩余资金:</strong> <span class="summary-value" style="color:#7c3aed;">${Utils.formatCurrency(totals.residual)}</span></span>
        `;
        summaryBar.style.display = 'flex';
    }
    
    // ========================================
    // 优先级本息覆盖倍数
    // ========================================
    if (coveragePanel) {
        const seniorPrincipalTotal = monthlyPtCashflow.seniorPrincipal || 0;  // 优先级初始本金
        const seniorInterestPaid = totals.seniorInterest;   // 优先级累计利息（=预期收益）
        const seniorPrincipalPaid = totals.seniorPrincipal;  // 优先级累计偿还本金
        
        // 分子 = 优先级本息 + 劣后级本金 + 剩余资金
        const numerator = (seniorPrincipalPaid + seniorInterestPaid) + totals.subordinatePrincipal + totals.residual;
        
        // 分母 = 优先级本金 + 预期收益
        const denominator = seniorPrincipalTotal + seniorInterestPaid;
        
        const coverageRatio = denominator > 0 ? numerator / denominator : 0;
        
        // 颜色
        let coverageColor, coverageLabel, coverageIcon;
        if (coverageRatio < 1.0) {
            coverageColor = '#dc2626'; coverageLabel = '不足'; coverageIcon = 'fa-exclamation-triangle';
        } else if (coverageRatio < 1.2) {
            coverageColor = '#d97706'; coverageLabel = '一般'; coverageIcon = 'fa-exclamation-circle';
        } else if (coverageRatio < 1.5) {
            coverageColor = '#0891b2'; coverageLabel = '良好'; coverageIcon = 'fa-check-circle';
        } else {
            coverageColor = '#059669'; coverageLabel = '充足'; coverageIcon = 'fa-shield-alt';
        }
        
        coveragePanel.innerHTML = `
            <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px;">
                <div style="display:flex;align-items:center;gap:14px;">
                    <div style="text-align:center;">
                        <div style="font-size:0.62rem;color:#64748b;margin-bottom:2px;">
                            <i class="fas ${coverageIcon}" style="color:${coverageColor};"></i> 优先级本息覆盖倍数
                        </div>
                        <div style="font-size:1.8rem;font-weight:800;color:${coverageColor};line-height:1;">
                            ${coverageRatio.toFixed(2)}x
                        </div>
                        <div style="font-size:0.58rem;color:${coverageColor};font-weight:600;margin-top:2px;">${coverageLabel}</div>
                    </div>
                    <div style="width:1px;height:50px;background:#cbd5e1;"></div>
                    <div style="font-size:0.58rem;color:#475569;line-height:1.6;">
                        <div style="font-weight:600;color:#1e293b;margin-bottom:2px;">计算公式</div>
                        <div>分子 = 优先级本息 + 劣后级本金 + 剩余资金</div>
                        <div>分母 = 优先级本金 + 预期收益</div>
                    </div>
                </div>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 20px;font-size:0.6rem;">
                    <div style="color:#64748b;font-weight:600;">分子 <span style="color:#1e40af;">${Utils.formatCurrency(numerator)}</span></div>
                    <div style="color:#64748b;font-weight:600;">分母 <span style="color:#1e40af;">${Utils.formatCurrency(denominator)}</span></div>
                    <div style="color:#94a3b8;">├ 优先级利息 <span style="color:#3182ce;">${Utils.formatCurrency(seniorInterestPaid)}</span></div>
                    <div style="color:#94a3b8;">├ 优先级本金 <span style="color:#3182ce;">${Utils.formatCurrency(seniorPrincipalTotal)}</span></div>
                    <div style="color:#94a3b8;">├ 优先级本金 <span style="color:#3182ce;">${Utils.formatCurrency(seniorPrincipalPaid)}</span></div>
                    <div style="color:#94a3b8;">└ 预期收益 <span style="color:#3182ce;">${Utils.formatCurrency(seniorInterestPaid)}</span></div>
                    <div style="color:#94a3b8;">├ 劣后级本金 <span style="color:#e53e3e;">${Utils.formatCurrency(totals.subordinatePrincipal)}</span></div>
                    <div></div>
                    <div style="color:#94a3b8;">└ 剩余资金 <span style="color:#7c3aed;">${Utils.formatCurrency(totals.residual)}</span></div>
                </div>
            </div>
        `;
        coveragePanel.style.display = 'block';
    }
}

/**
 * 🆕 v3.46.2: 导出偿付瀑布表到Excel
 * Sheet1: 月度偿付瀑布明细
 * Sheet2: 优先级本息覆盖倍数
 */
function exportWaterfallToExcel() {
    const monthlyPt = AppState.monthlyPtCashflow;
    const config = AppState.trustAnalysisConfig;
    if (!monthlyPt || !monthlyPt.periods || monthlyPt.periods.length === 0) {
        showToast('请先运行信托端分析', 'warning');
        return;
    }
    
    const periods = monthlyPt.periods;
    
    // 费率（仅 Sheet2 参数展示用）
    const fee1Rate = config ? (config.serviceFee1 || 0) : 0;
    const fee2Rate = config ? (config.serviceFee2 || 0) : 0;
    const trustFeeRate = config ? (config.trustServiceFee || 0) : 0;
    
    // ==========================================
    // Sheet 1: 月度偿付瀑布明细（简化8列，与页面表格一致）
    // 资产流入(不含信保) | 信保流入 | 费用(加总) | 优先级利息 | 劣后级利息 | 优先级本金 | 劣后级本金 | 剩余资金
    // ==========================================
    const headerRow = ['月份', '期间', '资产流入（不含信保）', '信保流入', '费用（合计）', '优先级利息', '劣后级利息', '优先级本金', '劣后级本金', '剩余资金'];
    
    const dataRows = [];
    const totals = {
        assetInflow: 0, guaranteeInflow: 0, fees: 0,
        seniorInterest: 0, subordinateInterest: 0,
        seniorPrincipal: 0, subordinatePrincipal: 0,
        residual: 0
    };
    
    periods.forEach((p) => {
        // 资产流入 = 净资产回款 + 沉淀利息（不含信保释放）
        const netAssetInflow = p.netInflow || 0;
        const idleInterest = p.interestIncome || 0;
        const assetInflow = netAssetInflow + idleInterest;
        
        // 信保流入（最后一期释放）
        const guaranteeInflow = p.guaranteeFundRelease || 0;
        
        // 费用合计 = 管理费（信托管理费+资产服务费+保管费）+ 税金 + 前置费用
        const fees = (p.taxAmount || 0) + (p.upfrontFee || 0) + (p.managementFee || 0);
        
        // 投资人分配
        const seniorInterest = p.seniorInterest || 0;
        const subordinateInterest = p.subordinateInterest || 0;
        const seniorPrincipalRepay = p.seniorPrincipalRepay || 0;
        const subordinatePrincipalRepay = p.subordinatePrincipalRepay || 0;
        
        // 剩余资金
        const residual = p.excessReturn || 0;
        
        // 累加
        totals.assetInflow += assetInflow;
        totals.guaranteeInflow += guaranteeInflow;
        totals.fees += fees;
        totals.seniorInterest += seniorInterest;
        totals.subordinateInterest += subordinateInterest;
        totals.seniorPrincipal += seniorPrincipalRepay;
        totals.subordinatePrincipal += subordinatePrincipalRepay;
        totals.residual += residual;
        
        dataRows.push([
            p.period,
            p.label,
            Math.round(assetInflow * 100) / 100,
            Math.round(guaranteeInflow * 100) / 100,
            Math.round(fees * 100) / 100,
            Math.round(seniorInterest * 100) / 100,
            Math.round(subordinateInterest * 100) / 100,
            Math.round(seniorPrincipalRepay * 100) / 100,
            Math.round(subordinatePrincipalRepay * 100) / 100,
            Math.round(residual * 100) / 100
        ]);
    });
    
    // 合计行
    const totalRow = [
        '合计', '',
        Math.round(totals.assetInflow * 100) / 100,
        Math.round(totals.guaranteeInflow * 100) / 100,
        Math.round(totals.fees * 100) / 100,
        Math.round(totals.seniorInterest * 100) / 100,
        Math.round(totals.subordinateInterest * 100) / 100,
        Math.round(totals.seniorPrincipal * 100) / 100,
        Math.round(totals.subordinatePrincipal * 100) / 100,
        Math.round(totals.residual * 100) / 100
    ];
    
    const sheet1Data = [headerRow, ...dataRows, totalRow];
    
    // ==========================================
    // Sheet 2: 优先级本息覆盖倍数
    // ==========================================
    const seniorPrincipalTotal = monthlyPt.seniorPrincipal || 0;  // 优先级初始本金
    const seniorInterestPaid = totals.seniorInterest;              // 优先级累计利息
    const seniorPrincipalPaid = totals.seniorPrincipal;            // 优先级累计偿还本金
    const seniorTotalPaid = seniorPrincipalPaid + seniorInterestPaid;
    const seniorDue = seniorPrincipalTotal + seniorInterestPaid;
    
    // 分子 = 优先级本息 + 劣后级本金 + 剩余资金
    const numerator = seniorTotalPaid + totals.subordinatePrincipal + totals.residual;
    const denominator = seniorDue;
    const coverageRatio = denominator > 0 ? numerator / denominator : 0;
    
    const sheet2Data = [
        ['优先级本息覆盖倍数分析'],
        [],
        ['计算公式', '覆盖倍数 = (优先级本息 + 劣后级本金 + 剩余资金) ÷ 优先级应付本息'],
        [],
        ['项目', '金额（元）', '说明'],
        ['【分子】', '', ''],
        ['  优先级利息（实付）', Math.round(seniorInterestPaid * 100) / 100, '信托存续期内实际支付的优先级利息合计'],
        ['  优先级本金（实付）', Math.round(seniorPrincipalPaid * 100) / 100, '信托存续期内实际偿还的优先级本金合计'],
        ['  优先级本息小计', Math.round(seniorTotalPaid * 100) / 100, ''],
        ['  劣后级本金（实付）', Math.round(totals.subordinatePrincipal * 100) / 100, '劣后级本金偿还合计'],
        ['  剩余资金', Math.round(totals.residual * 100) / 100, '全部分配后剩余（超额收益）'],
        ['  分子合计', Math.round(numerator * 100) / 100, ''],
        [],
        ['【分母】', '', ''],
        ['  优先级初始本金', Math.round(seniorPrincipalTotal * 100) / 100, '募集规模 × 优先级比例'],
        ['  优先级预期收益', Math.round(seniorInterestPaid * 100) / 100, '基于实际本金余额的利息合计'],
        ['  分母合计', Math.round(denominator * 100) / 100, ''],
        [],
        ['覆盖倍数', coverageRatio.toFixed(4), coverageRatio >= 1.5 ? '充足' : coverageRatio >= 1.2 ? '良好' : coverageRatio >= 1.0 ? '一般' : '不足'],
        [],
        ['参数配置', '', ''],
        ['  优先级比例', config ? config.seniorRatio + '%' : '-', ''],
        ['  优先级利率', config ? config.seniorRate + '%/年' : '-', ''],
        ['  劣后级比例', config ? config.subordinateRatio + '%' : '-', ''],
        ['  劣后级利率', config ? config.subordinateRate + '%/年' : '-', ''],
        ['  信托期限', periods.length + '个月', ''],
        ['  信托报酬费率', config ? trustFeeRate + '%/年' : '-', ''],
        ['  资产服务费率', config ? (fee1Rate + fee2Rate) + '%/年' : '-', '（服务机构1+2）'],
        ['  有效税率', config ? config.effectiveTaxRate + '%' : '-', ''],
    ];
    
    // 构建工作簿
    const wb = XLSX.utils.book_new();
    
    // Sheet1 — 简化8列，与页面表格一致
    const ws1 = XLSX.utils.aoa_to_sheet(sheet1Data);
    ws1['!cols'] = [
        { wch: 6 },   // 月份
        { wch: 12 },  // 期间
        { wch: 20 },  // 资产流入（不含信保）
        { wch: 14 },  // 信保流入
        { wch: 14 },  // 费用（合计）
        { wch: 14 },  // 优先级利息
        { wch: 14 },  // 劣后级利息
        { wch: 14 },  // 优先级本金
        { wch: 14 },  // 劣后级本金
        { wch: 14 }   // 剩余资金
    ];
    XLSX.utils.book_append_sheet(wb, ws1, '月度偿付瀑布');
    
    // Sheet2
    const ws2 = XLSX.utils.aoa_to_sheet(sheet2Data);
    ws2['!cols'] = [
        { wch: 22 },  // 项目
        { wch: 18 },  // 金额
        { wch: 40 }   // 说明
    ];
    ws2['!merges'] = [
        { s: { r: 0, c: 0 }, e: { r: 0, c: 2 } }  // 标题合并
    ];
    XLSX.utils.book_append_sheet(wb, ws2, '优先级本息覆盖倍数');
    
    const waterfallSheet = quoteExcelSheetName('月度偿付瀑布');
    const detailEndRow = periods.length + 1;
    appendFormulaAuditSheet(wb, [
        { label: '资产流入合计', jsValue: totals.assetInflow, formula: `SUM(${waterfallSheet}!C2:C${detailEndRow})`, note: '复核月度资产流入明细合计' },
        { label: '信保流入合计', jsValue: totals.guaranteeInflow, formula: `SUM(${waterfallSheet}!D2:D${detailEndRow})`, note: '复核信保基金释放' },
        { label: '费用合计', jsValue: totals.fees, formula: `SUM(${waterfallSheet}!E2:E${detailEndRow})`, note: '复核税费、前置费、管理费合计' },
        { label: '优先级利息合计', jsValue: totals.seniorInterest, formula: `SUM(${waterfallSheet}!F2:F${detailEndRow})`, note: '复核优先级利息分配' },
        { label: '优先级本金合计', jsValue: totals.seniorPrincipal, formula: `SUM(${waterfallSheet}!H2:H${detailEndRow})`, note: '复核优先级本金偿还' },
        { label: '剩余资金合计', jsValue: totals.residual, formula: `SUM(${waterfallSheet}!J2:J${detailEndRow})`, note: '复核瀑布分配后的剩余资金' }
    ], {
        title: '偿付瀑布按钮公式校验',
        description: '复核“导出偿付瀑布”按钮生成的核心合计。'
    });
    
    // 导出
    const dateStr = new Date().toISOString().split('T')[0];
    XLSX.writeFile(wb, `月度偿付瀑布_${dateStr}.xlsx`);
    showToast('偿付瀑布Excel导出成功');
}

/**
 * 【v3.45.7重构】更新固定摊还现金流表格
 * 修复：原始回款 vs 信托端回款的显示逻辑
 * @param {Array} fullLifecyclePeriods - 全生命周期原始现金流（可选）
 * @param {Array} vacancyPeriods - 🆕 v3.45.58 含空置期的原始回款（用于计算纯空置期影响）
 */
function updateFACashflowTable(tableBodyId, periods, expandMonthly = false, cashflowPeriods = null, fullLifecyclePeriods = null, vacancyPeriods = null) {
    const tbody = document.getElementById(tableBodyId);
    const summaryBar = document.getElementById('faSummaryBar');
    if (!tbody) return;
    
    // 只处理季度末数据
    const quarterPeriods = periods.filter(p => p.isQuarterEnd);
    
    // 🆕 v3.45.32: 不再使用自累加，改为从period中读取cashReserve
    // 原因：cashReserve有Math.max(0,...)约束，自累加会与Excel导出产生差异
    let rowsHtml = [];
    
    // 🆕 v3.45.19: 按季度汇总资产端原始回款
    // 原始回款 = 已代扣金额（第一月）+ 未来回款（按期展开）
    // 原始回款总额应该等于总代扣金额（不考虑空置期、违约等影响）
    const getOriginalCashflow = (quarterIndex) => {
        if (!cashflowPeriods || cashflowPeriods.length === 0) return 0;
        const startMonth = quarterIndex * 3;
        let total = 0;
        for (let i = startMonth; i < startMonth + 3 && i < cashflowPeriods.length; i++) {
            const period = cashflowPeriods[i];
            // 🆕 v3.45.19: 原始回款 = totalAmount = 已代扣(第一月) + 未来回款
            // totalAmount 在 calculateDetailedCashflow 中已定义为：periodDeductedAmount + futureAmount
            total += (period?.totalAmount || 0);
        }
        return total;
    };
    
    // 🆕 v3.45.58: 按季度汇总含空置期的原始回款（用于计算纯空置期影响）
    const getVacancyCashflow = (quarterIndex) => {
        if (!vacancyPeriods || vacancyPeriods.length === 0) return null;
        const startMonth = quarterIndex * 3;
        let total = 0;
        for (let i = startMonth; i < startMonth + 3 && i < vacancyPeriods.length; i++) {
            const period = vacancyPeriods[i];
            total += (period?.totalAmount || 0);
        }
        return total;
    };
    
    // 计算合计数据
    const totals = {
        originalCashflow: 0,
        assetInflow: 0,
        defaultAmount: 0,
        recoveryAmount: 0,
        managementFee: 0,
        taxAmount: 0,
        netInflow: 0,
        seniorInterest: 0,
        seniorPrincipal: 0,
        subordinateInterest: 0,
        subordinatePrincipal: 0,
        periodReserve: 0
    };
    
    // 🆕 v3.45.33 fix: 用于在循环外保存最终累计沉淀值
    let finalCumulativeReserve = 0;
    
    quarterPeriods.forEach((p, index) => {
        const netInflow = p.netInflow !== undefined ? p.netInflow : p.assetInflow;
        const originalCashflow = getOriginalCashflow(index);
        
        // 🆕 v3.45.32: 从period中读取当期和累计沉淀，保持与Excel导出一致
        const periodReserve = p.periodReserveIncrease || p.excessReturn || 0;
        const cumulativeReserve = p.cashReserve || 0;  // 直接使用period中的累计沉淀
        finalCumulativeReserve = cumulativeReserve;  // 🆕 v3.45.33 fix: 保存到外部变量
        
        // 累加合计
        totals.originalCashflow += originalCashflow;
        totals.assetInflow += (p.assetInflow || 0);
        totals.defaultAmount += (p.defaultAmount || 0);
        totals.recoveryAmount += (p.recoveryAmount || 0);
        totals.managementFee += (p.managementFee || 0);
        totals.taxAmount += (p.taxAmount || 0);
        totals.netInflow += netInflow;
        totals.seniorInterest += (p.seniorInterest || 0);
        totals.seniorPrincipal += (p.seniorPrincipalRepay || 0);
        totals.subordinateInterest += (p.subordinateInterest || 0);
        totals.subordinatePrincipal += (p.subordinatePrincipalRepay || 0);
        totals.periodReserve += periodReserve;
        
        // 🆕 v3.45.22: 月度明细展开（固定摊还）
        // 原始回款 = 已代扣（第一月）+ 未来回款（不含空置期）
        // 资产回款 = 已代扣（第一月）+ 未来回款（含空置期影响）
        // 空置期影响 = 资产回款 - 原始回款
        if (expandMonthly && p.monthlyDetails && p.monthlyDetails.length > 0) {
            p.monthlyDetails.forEach((m, mIdx) => {
                const periodData = cashflowPeriods && cashflowPeriods[index * 3 + mIdx];
                const futureAmount = periodData?.futureAmount || 0;
                const deductedAmt = periodData?.deductedAmount || m.deductedAmount || 0;
                const hasDeducted = deductedAmt > 0.01;
                
                // 原始回款列：第一月 = 已代扣 + 未来回款，后续月 = 未来回款
                const monthOriginal = futureAmount + deductedAmt;
                
                // 🆕 v3.45.30: 完整月度明细行（17列）- 固定摊还
                const monthVacancy = (m.assetInflow || 0) - monthOriginal;
                const monthVacancyDisplay = Math.abs(monthVacancy) < 0.01 ? '-' : `${monthVacancy > 0 ? '+' : ''}${Utils.formatCurrency(monthVacancy)}`;
                const monthVacancyColor = monthVacancy > 0.01 ? '#059669' : (monthVacancy < -0.01 ? '#dc2626' : '#94a3b8');
                
                const monthRow = `
                    <tr class="monthly-row" ${hasDeducted ? 'style="background: #fef2f2;"' : ''}>
                        <td style="color: #94a3b8; padding-left: 14px;">${m.month}</td>
                        <td style="font-size: 0.62rem;">${m.label}${hasDeducted ? '<span style="color:#dc2626;font-size:7px;">(垫)</span>' : ''}</td>
                        <td class="number" style="color: #805ad5;">${Utils.formatCurrency(monthOriginal)}</td>
                        <td class="number">${Utils.formatCurrency(m.assetInflow || 0)}</td>
                        <td class="number" style="color: ${monthVacancyColor};">${monthVacancyDisplay}</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number">${Utils.formatCurrency(m.netInflow || 0)}</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                        <td class="number" style="color: #94a3b8;">-</td>
                    </tr>
                `;
                rowsHtml.push(monthRow);
            });
        }
        
        const quarterRowClass = expandMonthly ? 'quarter-row' : '';
        const seniorCleared = (p.seniorBalance || 0) <= 0.01;
        const subCleared = (p.subordinateBalance || 0) <= 0.01;
        const highlightClass = (seniorCleared && subCleared) ? 'highlight-row' : '';
        
        // 🆕 v3.45.58: 计算纯空置期影响 = 含空置期原始回款 - 不含空置期原始回款
        // 修复：之前用 (p.assetInflow - originalCashflow) 计算，但 p.assetInflow 已包含违约/回收/管理费
        const vacancyCashflowForQuarter = getVacancyCashflow(index);
        const quarterVacancyEffect = vacancyCashflowForQuarter !== null 
            ? (vacancyCashflowForQuarter - originalCashflow)  // 纯空置期影响
            : (p.assetInflow || 0) - originalCashflow;        // 回退到旧逻辑
        const vacancyColor = quarterVacancyEffect > 0.01 ? '#059669' : (quarterVacancyEffect < -0.01 ? '#dc2626' : '#94a3b8');
        const vacancyDisplay = Math.abs(quarterVacancyEffect) < 0.01 ? '-' : 
            `${quarterVacancyEffect > 0 ? '+' : ''}${Utils.formatCurrency(quarterVacancyEffect)}`;
        
        // 累计空置期影响
        totals.vacancyEffect = (totals.vacancyEffect || 0) + quarterVacancyEffect;
        
        // 🆕 v3.45.30: 完整表格行（17列）- 固定摊还
        const quarterRow = `
            <tr class="${quarterRowClass} ${highlightClass}">
                <td><strong>Q${Math.ceil(p.period / 3)}</strong></td>
                <td>${p.label}</td>
                <td class="number" style="color: #805ad5;">${Utils.formatCurrency(originalCashflow)}</td>
                <td class="number">${Utils.formatCurrency(p.assetInflow || 0)}</td>
                <td class="number" style="color: ${vacancyColor};">${vacancyDisplay}</td>
                <td class="number" style="color: #dc2626;">${Utils.formatCurrency(p.defaultAmount || 0)}</td>
                <td class="number" style="color: #059669;">${Utils.formatCurrency(p.recoveryAmount || 0)}</td>
                <td class="number" style="color: #94a3b8;">${Utils.formatCurrency(p.managementFee || 0)}</td>
                <td class="number">${Utils.formatCurrency(netInflow)}</td>
                <td class="number" style="color: #3182ce;">${Utils.formatCurrency(p.seniorInterest || 0)}</td>
                <td class="number" style="color: #3182ce;">${Utils.formatCurrency(p.seniorPrincipalRepay || 0)}</td>
                <td class="number ${seniorCleared ? 'text-success' : ''}">${Utils.formatCurrency(p.seniorBalance || 0)}</td>
                <td class="number" style="color: #e53e3e;">${Utils.formatCurrency(p.subordinateInterest || 0)}</td>
                <td class="number" style="color: #e53e3e;">${Utils.formatCurrency(p.subordinatePrincipalRepay || 0)}</td>
                <td class="number ${subCleared ? 'text-success' : ''}">${Utils.formatCurrency(p.subordinateBalance || 0)}</td>
                <td class="number" style="color: #d69e2e; font-weight: 500;">${Utils.formatCurrency(periodReserve)}</td>
                <td class="number" style="color: #d69e2e; font-weight: 600;">${Utils.formatCurrency(cumulativeReserve)}</td>
            </tr>
        `;
        rowsHtml.push(quarterRow);
    });
    
    // 🆕 v3.45.19: 计算已代扣金额（从cashflowPeriods获取，用于单独显示）
    let totalDeductedAmount = 0;
    if (cashflowPeriods && cashflowPeriods.length > 0) {
        cashflowPeriods.forEach(p => {
            totalDeductedAmount += (p?.deductedAmount || 0);
        });
    }
    
    // 【v3.45.19】统计口径修正（与过手摊还一致）：
    // - totals.originalCashflow 已经是 totalAmount 的累加，已包含已代扣金额
    // - 原始回款 = totals.originalCashflow（已含已代扣+未来回款）
    // - 资产回款 = totals.assetInflow（已含已代扣+未来回款+空置期影响）
    const originalTotal = totals.originalCashflow;  // 原始回款（已含已代扣，不含空置期）
    const assetTotal = totals.assetInflow;  // 资产回款（已含已代扣，含空置期影响）
    
    // 空置期影响 = 资产回款 - 原始回款
    const vacancyEffect = assetTotal - originalTotal;
    
    // 计算全生命周期原始回款总额（固定摊还）
    let fullLifecycleTotal = originalTotal;
    let beyondTrustPeriodAmount = 0;
    if (fullLifecyclePeriods && fullLifecyclePeriods.length > 0) {
        fullLifecycleTotal = fullLifecyclePeriods.reduce((sum, p) => sum + (p?.totalAmount || 0), 0);
        beyondTrustPeriodAmount = Math.max(0, fullLifecycleTotal - originalTotal);
    }
    
    // 🆕 v3.45.19: 更新汇总栏（表格上方小字）
    if (summaryBar) {
        const trustMonths = quarterPeriods.length * 3;
        const faBeyondPercent = fullLifecycleTotal > 0 ? (beyondTrustPeriodAmount / fullLifecycleTotal * 100).toFixed(1) : 0;
        
        let summaryHtml = `
            <span class="summary-item"><strong>期限:</strong> <span class="summary-value">${trustMonths}月</span></span>
            <span class="summary-item" title="已代扣(安全垫)+未来回款(不含空置期)，应等于总代扣金额"><strong>原始回款:</strong> <span class="summary-value val-purple">${Utils.formatCurrency(originalTotal)}</span></span>
            <span class="summary-item" title="已代扣(安全垫)+未来回款(含空置期影响)"><strong>资产回款:</strong> <span class="summary-value val-blue">${Utils.formatCurrency(assetTotal)}</span></span>
        `;
        
        // 🆕 v3.45.18: 显示空置期影响（替代前期移入）
        if (Math.abs(vacancyEffect) > 0.01) {
            const effectTitle = '整装资产每12个月续租产生的空置期推迟效应，影响未来回款的时间分布';
            const effectColor = vacancyEffect > 0 ? 'val-teal' : 'val-orange';
            summaryHtml += `
                <span class="summary-item" title="${effectTitle}"><strong>空置期影响:</strong> <span class="summary-value ${effectColor}">${vacancyEffect > 0 ? '+' : ''}${Utils.formatCurrency(vacancyEffect)}</span></span>
            `;
        }
        
        // 显示已代扣金额（安全垫）
        if (totalDeductedAmount > 0.01) {
            summaryHtml += `
                <span class="summary-item" title="已代扣金额(安全垫)，第一月到账，原始回款和资产回款均包含此项"><strong>已代扣:</strong> <span class="summary-value" style="color: #dc2626;">${Utils.formatCurrency(totalDeductedAmount)}</span></span>
            `;
        }
        
        summaryHtml += `
            <span class="summary-item"><strong>净回款:</strong> <span class="summary-value val-yellow">${Utils.formatCurrency(totals.netInflow)}</span></span>
            <span class="summary-item"><strong>累计沉淀:</strong> <span class="summary-value val-green">${Utils.formatCurrency(finalCumulativeReserve)}</span></span>
        `;
        
        // 60期后回款（始终显示）
        summaryHtml += `
            <span class="summary-item summary-highlight" title="资产期限超出信托期的原始回款"><strong>${trustMonths}期后:</strong> <span class="summary-value val-orange">${Utils.formatCurrency(beyondTrustPeriodAmount)}${beyondTrustPeriodAmount > 0.01 ? ' (' + faBeyondPercent + '%)' : ''}</span></span>
        `;
        
        // 全周期原始回款
        summaryHtml += `
            <span class="summary-item" title="资产全生命周期的原始回款总额"><strong>全周期:</strong> <span class="summary-value val-teal">${Utils.formatCurrency(fullLifecycleTotal)}</span></span>
        `;
        
        summaryBar.innerHTML = summaryHtml;
        summaryBar.style.display = 'flex';
    }
    
    tbody.innerHTML = rowsHtml.join('');
}

/**
 * 【流转型专用】更新循环池现金流明细表（双栏布局）
 * 左侧：资产端流入
 * 右侧：资金端还款
 */
function updateCirculationCashflowTable(assetCashflow, circulationPoolCashflow, fundingCashflow, config) {
    console.log('===== 更新循环池现金流表格（双栏） =====');
    
    const assetTbody = document.getElementById('assetInflowTableBody');
    const fundingTbody = document.getElementById('fundingOutflowTableBody');
    const fundingHead = document.getElementById('fundingTableHead');
    const fundingTypeLabel = document.getElementById('fundingTypeLabel');
    
    if (!assetTbody || !fundingTbody) {
        console.warn('未找到现金流表格元素');
        return;
    }
    
    const assetResults = circulationPoolCashflow?.assetResults || [];
    const fundingResults = circulationPoolCashflow?.fundingResults || [];
    const summary = circulationPoolCashflow?.summary || {};
    const fundingType = summary.fundingType || config?.fundingType || 'flat';
    
    console.log('数据条数:', { assetResults: assetResults.length, fundingResults: fundingResults.length, fundingType });
    
    if (assetResults.length === 0) {
        assetTbody.innerHTML = '<tr><td colspan="7" class="text-center text-secondary">暂无数据</td></tr>';
        fundingTbody.innerHTML = '<tr><td colspan="5" class="text-center text-secondary">暂无数据</td></tr>';
        return;
    }
    
    const collapseToQuarter = document.getElementById('collapseToQuarter')?.checked || false;
    
    // 更新资金端类型标签
    if (fundingTypeLabel) {
        fundingTypeLabel.textContent = fundingType === 'flat' ? '平层资金' : '结构化资金';
    }
    
    // 更新资金端表头（v3.40.0 新增税费和管理费列，v3.40.1 拆分资产/资金管理费）
    if (fundingHead) {
        if (fundingType === 'flat') {
            fundingHead.innerHTML = `
                <tr>
                    <th>期间</th>
                    <th>税费</th>
                    <th>资产管理费</th>
                    <th>资金管理费</th>
                    <th>利息支付</th>
                    <th>本金偿还</th>
                    <th>剩余本金</th>
                    <th>累计支出</th>
                </tr>
            `;
        } else {
            fundingHead.innerHTML = `
                <tr>
                    <th>期间</th>
                    <th>税费</th>
                    <th>资产管理费</th>
                    <th>资金管理费</th>
                    <th>优先级利息</th>
                    <th>优先级本金</th>
                    <th>劣后级利息</th>
                    <th>劣后级本金</th>
                    <th>剩余本金</th>
                </tr>
            `;
        }
    }
    
    // 渲染表格
    if (collapseToQuarter) {
        // 按季度汇总
        renderQuarterlyCashflow(assetResults, fundingResults, assetTbody, fundingTbody, fundingType);
    } else {
        // 按月度显示
        renderMonthlyCashflow(assetResults, fundingResults, assetTbody, fundingTbody, fundingType);
    }
    
    // 更新汇总（使用新的元素ID）
    const initialPoolEl = document.getElementById('circulationInitialPoolSize');
    const totalPurchasesEl = document.getElementById('totalPurchases');
    const totalFundingEl = document.getElementById('totalFundingOutflow');
    const finalCashEl = document.getElementById('finalCash');
    const summaryTotalTaxEl = document.getElementById('summaryTotalTax');
    const summaryTotalAssetMgmtFeeEl = document.getElementById('summaryTotalAssetMgmtFee');
    const summaryTotalFundMgmtFeeEl = document.getElementById('summaryTotalFundMgmtFee');
    
    if (initialPoolEl) initialPoolEl.textContent = Utils.formatCurrency(summary.initialPool?.total || 0);
    if (totalPurchasesEl) totalPurchasesEl.textContent = Utils.formatCurrency(summary.totalPurchases || 0);
    if (totalFundingEl) totalFundingEl.textContent = Utils.formatCurrency(summary.totalFundingOutflow || 0);
    
    // 更新累计税费和管理费汇总（v3.40.0新增，v3.40.1拆分资产/资金管理费）
    if (summaryTotalTaxEl) summaryTotalTaxEl.textContent = Utils.formatCurrency(summary.totalTax || 0);
    if (summaryTotalAssetMgmtFeeEl) summaryTotalAssetMgmtFeeEl.textContent = Utils.formatCurrency(summary.totalAssetMgmtFee || 0);
    if (summaryTotalFundMgmtFeeEl) summaryTotalFundMgmtFeeEl.textContent = Utils.formatCurrency(summary.totalFundMgmtFee || 0);
    
    // 更新风险损失（v3.41.0新增）
    const summaryTotalRiskLossEl = document.getElementById('summaryTotalRiskLoss');
    if (summaryTotalRiskLossEl) summaryTotalRiskLossEl.textContent = Utils.formatCurrency(summary.totalRiskLoss || 0);
    
    // 计算期末剩余资金（最后一期的资产 + 现金）
    const lastAssetResult = assetResults[assetResults.length - 1];
    const finalCash = (lastAssetResult?.shortAssetSizeEnd || 0) + (lastAssetResult?.longAssetSizeEnd || 0) + (lastAssetResult?.cashBalance || 0);
    if (finalCashEl) finalCashEl.textContent = Utils.formatCurrency(finalCash);
    
    // 保存到全局状态
    AppState.circulationCashflow = circulationPoolCashflow;
    
    // v3.43.0: 渲染资产规模变化图表
    renderAssetScaleChart(assetResults);
    
    console.log('表格更新完成');
}

/**
 * 渲染月度现金流表格（v3.36.0 重构，v3.43.0 区分存量/预期）
 * 资产端：池总规模、短期(存量)、短期(预期)、中长期(存量)、中长期(预期)、短期回款、中长期回款、中长期卖出、本期收益、循环购买
 * 资金端：根据平层/结构化配置显示
 */
function renderMonthlyCashflow(assetResults, fundingResults, assetTbody, fundingTbody, fundingType) {
    // v3.43.0: 更新资产端表头（区分存量/预期）
    const assetTableHead = document.getElementById('assetTableHead');
    if (assetTableHead) {
        assetTableHead.innerHTML = `
            <tr>
                <th rowspan="2">期间</th>
                <th rowspan="2">池总规模</th>
                <th colspan="2" style="background: rgba(56, 161, 105, 0.1); border-bottom: 1px solid var(--border-color);">短期资产规模</th>
                <th colspan="2" style="background: rgba(49, 130, 206, 0.1); border-bottom: 1px solid var(--border-color);">中长期资产规模</th>
                <th colspan="2" style="background: rgba(56, 161, 105, 0.1); border-bottom: 1px solid var(--border-color);">短期回款</th>
                <th colspan="2" style="background: rgba(49, 130, 206, 0.1); border-bottom: 1px solid var(--border-color);">中长期回款</th>
                <th rowspan="2">中长期卖出</th>
                <th rowspan="2">本期收益</th>
                <th rowspan="2">循环购买</th>
            </tr>
            <tr>
                <th style="background: rgba(56, 161, 105, 0.05);">存量</th>
                <th style="background: rgba(56, 161, 105, 0.05);">预期</th>
                <th style="background: rgba(49, 130, 206, 0.05);">存量</th>
                <th style="background: rgba(49, 130, 206, 0.05);">预期</th>
                <th style="background: rgba(56, 161, 105, 0.05);">存量</th>
                <th style="background: rgba(56, 161, 105, 0.05);">预期</th>
                <th style="background: rgba(49, 130, 206, 0.05);">存量</th>
                <th style="background: rgba(49, 130, 206, 0.05);">预期</th>
            </tr>
        `;
    }
    
    // 资产端表格
    let assetHtml = '';
    assetResults.forEach((r, idx) => {
        const isQuarterEnd = (idx + 1) % 3 === 0;
        const rowClass = isQuarterEnd ? 'quarter-end-row' : '';
        
        const poolSize = r.totalPoolSize || r.totalAssetSize || 0;
        // v3.43.0: 分存量/预期规模
        const shortSizeStock = r.shortAssetSizeEndStock || 0;
        const shortSizeExpected = r.shortAssetSizeEndExpected || 0;
        const longSizeStock = r.longAssetSizeEndStock || 0;
        const longSizeExpected = r.longAssetSizeEndExpected || 0;
        // v3.43.0: 分存量/预期回款
        const shortRepaymentStock = r.shortRepaymentStock || 0;
        const shortRepaymentExpected = r.shortRepaymentExpected || 0;
        const longRepaymentStock = r.longRepaymentStock || 0;
        const longRepaymentExpected = r.longRepaymentExpected || 0;
        const periodProfit = r.periodProfit || 0;
        
        assetHtml += `
            <tr class="${rowClass}">
                <td>${r.periodLabel}</td>
                <td class="number highlight-value">${Utils.formatCurrency(poolSize)}</td>
                <td class="number text-success">${Utils.formatCurrency(shortSizeStock)}</td>
                <td class="number" style="color: var(--success-color); opacity: 0.7;">${Utils.formatCurrency(shortSizeExpected)}</td>
                <td class="number text-primary">${Utils.formatCurrency(longSizeStock)}</td>
                <td class="number" style="color: var(--accent-color); opacity: 0.7;">${Utils.formatCurrency(longSizeExpected)}</td>
                <td class="number">${Utils.formatCurrency(shortRepaymentStock)}</td>
                <td class="number" style="opacity: 0.7;">${Utils.formatCurrency(shortRepaymentExpected)}</td>
                <td class="number">${Utils.formatCurrency(longRepaymentStock)}</td>
                <td class="number" style="opacity: 0.7;">${Utils.formatCurrency(longRepaymentExpected)}</td>
                <td class="number">${Utils.formatCurrency(r.longSellAmt || 0)}</td>
                <td class="number ${periodProfit > 0 ? 'text-success' : ''}">${Utils.formatCurrency(periodProfit)}</td>
                <td class="number ${(r.purchaseAmount || 0) > 0 ? 'text-info' : ''}">${Utils.formatCurrency(r.purchaseAmount || 0)}</td>
            </tr>
        `;
    });
    assetTbody.innerHTML = assetHtml;
    
    // 资金端表格（v3.40.0 新增税费和管理费列，v3.40.1 拆分资产/资金管理费）
    let fundingHtml = '';
    let cumulativeOutflow = 0;
    let cumulativeTax = 0;
    let cumulativeAssetMgmtFee = 0;
    let cumulativeFundMgmtFee = 0;
    
    fundingResults.forEach((r, idx) => {
        const isQuarterEnd = (idx + 1) % 3 === 0;
        const rowClass = isQuarterEnd ? 'quarter-end-row' : '';
        
        // 累计值（税费+管理费+本息）
        cumulativeTax += r.periodTax || 0;
        cumulativeAssetMgmtFee += r.periodAssetMgmtFee || 0;
        cumulativeFundMgmtFee += r.periodFundMgmtFee || 0;
        cumulativeOutflow += (r.totalExpense || r.totalOutflow || 0);
        
        if (fundingType === 'flat') {
            fundingHtml += `
                <tr class="${rowClass}">
                    <td>${r.periodLabel}</td>
                    <td class="number ${(r.periodTax || 0) > 0 ? 'text-warning' : ''}">${Utils.formatCurrency(r.periodTax || 0)}</td>
                    <td class="number ${(r.periodAssetMgmtFee || 0) > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(r.periodAssetMgmtFee || 0)}</td>
                    <td class="number ${(r.periodFundMgmtFee || 0) > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(r.periodFundMgmtFee || 0)}</td>
                    <td class="number ${(r.interestPayment || 0) > 0 ? 'text-danger' : ''}">${Utils.formatCurrency(r.interestPayment || 0)}</td>
                    <td class="number ${(r.principalPayment || 0) > 0 ? 'text-info' : ''}">${Utils.formatCurrency(r.principalPayment || 0)}</td>
                    <td class="number ${r.remainingPrincipal <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(r.remainingPrincipal || 0)}</td>
                    <td class="number">${Utils.formatCurrency(cumulativeOutflow)}</td>
                </tr>
            `;
        } else {
            fundingHtml += `
                <tr class="${rowClass}">
                    <td>${r.periodLabel}</td>
                    <td class="number ${(r.periodTax || 0) > 0 ? 'text-warning' : ''}">${Utils.formatCurrency(r.periodTax || 0)}</td>
                    <td class="number ${(r.periodAssetMgmtFee || 0) > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(r.periodAssetMgmtFee || 0)}</td>
                    <td class="number ${(r.periodFundMgmtFee || 0) > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(r.periodFundMgmtFee || 0)}</td>
                    <td class="number">${Utils.formatCurrency(r.seniorInterest || 0)}</td>
                    <td class="number">${Utils.formatCurrency(r.seniorPrincipalPay || 0)}</td>
                    <td class="number">${Utils.formatCurrency(r.subordinateInterest || 0)}</td>
                    <td class="number">${Utils.formatCurrency(r.subordinatePrincipalPay || 0)}</td>
                    <td class="number ${r.remainingPrincipal <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(r.remainingPrincipal || 0)}</td>
                </tr>
            `;
        }
    });
    fundingTbody.innerHTML = fundingHtml;
}

/**
 * 渲染季度汇总现金流表格（v3.35.0 重构）
 * 季度末显示规模，汇总显示回款和购买
 */
function renderQuarterlyCashflow(assetResults, fundingResults, assetTbody, fundingTbody, fundingType) {
    // 按季度汇总数据
    const quarterlyAsset = {};
    const quarterlyFunding = {};
    
    assetResults.forEach((r, idx) => {
        const quarter = Math.ceil((idx + 1) / 3);
        if (!quarterlyAsset[quarter]) {
            quarterlyAsset[quarter] = {
                quarter,
                periodLabel: `Q${quarter}`,
                // 规模取季末值
                totalPoolSize: 0,
                shortAssetSize: 0,
                longAssetSize: 0,
                // v3.43.0: 分存量/预期规模
                shortAssetSizeStock: 0,
                shortAssetSizeExpected: 0,
                longAssetSizeStock: 0,
                longAssetSizeExpected: 0,
                // 流量累加
                shortRepayment: 0,
                longRepayment: 0,
                longSellAmt: 0,
                // v3.43.0: 分存量/预期回款
                shortRepaymentStock: 0,
                shortRepaymentExpected: 0,
                longRepaymentStock: 0,
                longRepaymentExpected: 0,
                periodProfit: 0,
                purchaseAmount: 0
            };
        }
        const q = quarterlyAsset[quarter];
        // 取季末池总规模（期末资产 + 现金）
        q.totalPoolSize = (r.shortAssetSizeEnd || 0) + (r.longAssetSizeEnd || 0) + (r.cashBalance || 0);
        q.shortAssetSize = r.shortAssetSizeEnd || 0;
        q.longAssetSize = r.longAssetSizeEnd || 0;
        // v3.43.0: 取季末分存量/预期规模
        q.shortAssetSizeStock = r.shortAssetSizeEndStock || 0;
        q.shortAssetSizeExpected = r.shortAssetSizeEndExpected || 0;
        q.longAssetSizeStock = r.longAssetSizeEndStock || 0;
        q.longAssetSizeExpected = r.longAssetSizeEndExpected || 0;
        // 累加流量
        q.shortRepayment += r.shortRepayment || 0;
        q.longRepayment += r.longRepayment || 0;
        q.longSellAmt += r.longSellAmt || 0;
        // v3.43.0: 累加分存量/预期回款
        q.shortRepaymentStock += r.shortRepaymentStock || 0;
        q.shortRepaymentExpected += r.shortRepaymentExpected || 0;
        q.longRepaymentStock += r.longRepaymentStock || 0;
        q.longRepaymentExpected += r.longRepaymentExpected || 0;
        q.periodProfit += r.periodProfit || 0;
        q.purchaseAmount += r.purchaseAmount || 0;
    });
    
    fundingResults.forEach((r, idx) => {
        const quarter = Math.ceil((idx + 1) / 3);
        if (!quarterlyFunding[quarter]) {
            quarterlyFunding[quarter] = {
                quarter,
                periodLabel: `Q${quarter}`,
                // 税费和管理费（v3.40.0新增，v3.40.1拆分资产/资金管理费）
                periodTax: 0,
                periodAssetMgmtFee: 0,
                periodFundMgmtFee: 0,
                interestPayment: 0,
                principalPayment: 0,
                seniorInterest: 0,
                seniorPrincipalPay: 0,
                subordinateInterest: 0,
                subordinatePrincipalPay: 0,
                remainingPrincipal: 0,
                totalOutflow: 0,
                totalExpense: 0
            };
        }
        const q = quarterlyFunding[quarter];
        // 累加税费和管理费（分别累加资产管理费和资金管理费）
        q.periodTax += r.periodTax || 0;
        q.periodAssetMgmtFee += r.periodAssetMgmtFee || 0;
        q.periodFundMgmtFee += r.periodFundMgmtFee || 0;
        q.interestPayment += r.interestPayment || 0;
        q.principalPayment += r.principalPayment || 0;
        q.seniorInterest += r.seniorInterest || 0;
        q.seniorPrincipalPay += r.seniorPrincipalPay || 0;
        q.subordinateInterest += r.subordinateInterest || 0;
        q.subordinatePrincipalPay += r.subordinatePrincipalPay || 0;
        q.remainingPrincipal = r.remainingPrincipal;
        q.totalOutflow += r.totalOutflow || 0;
        q.totalExpense += r.totalExpense || 0;
    });
    
    // v3.43.0: 更新资产端表头（区分存量/预期）- 季度汇总模式
    const assetTableHead = document.getElementById('assetTableHead');
    if (assetTableHead) {
        assetTableHead.innerHTML = `
            <tr>
                <th rowspan="2">季度</th>
                <th rowspan="2">池总规模</th>
                <th colspan="2" style="background: rgba(56, 161, 105, 0.1); border-bottom: 1px solid var(--border-color);">短期资产规模</th>
                <th colspan="2" style="background: rgba(49, 130, 206, 0.1); border-bottom: 1px solid var(--border-color);">中长期资产规模</th>
                <th colspan="2" style="background: rgba(56, 161, 105, 0.1); border-bottom: 1px solid var(--border-color);">短期回款</th>
                <th colspan="2" style="background: rgba(49, 130, 206, 0.1); border-bottom: 1px solid var(--border-color);">中长期回款</th>
                <th rowspan="2">中长期卖出</th>
                <th rowspan="2">本期收益</th>
                <th rowspan="2">循环购买</th>
            </tr>
            <tr>
                <th style="background: rgba(56, 161, 105, 0.05);">存量</th>
                <th style="background: rgba(56, 161, 105, 0.05);">预期</th>
                <th style="background: rgba(49, 130, 206, 0.05);">存量</th>
                <th style="background: rgba(49, 130, 206, 0.05);">预期</th>
                <th style="background: rgba(56, 161, 105, 0.05);">存量</th>
                <th style="background: rgba(56, 161, 105, 0.05);">预期</th>
                <th style="background: rgba(49, 130, 206, 0.05);">存量</th>
                <th style="background: rgba(49, 130, 206, 0.05);">预期</th>
            </tr>
        `;
    }
    
    // 渲染资产端
    let assetHtml = '';
    let cumulativeOutflow = 0;
    
    Object.values(quarterlyAsset).forEach(q => {
        assetHtml += `
            <tr class="quarter-row">
                <td><strong>${q.periodLabel}</strong></td>
                <td class="number highlight-value">${Utils.formatCurrency(q.totalPoolSize)}</td>
                <td class="number text-success">${Utils.formatCurrency(q.shortAssetSizeStock)}</td>
                <td class="number" style="color: var(--success-color); opacity: 0.7;">${Utils.formatCurrency(q.shortAssetSizeExpected)}</td>
                <td class="number text-primary">${Utils.formatCurrency(q.longAssetSizeStock)}</td>
                <td class="number" style="color: var(--accent-color); opacity: 0.7;">${Utils.formatCurrency(q.longAssetSizeExpected)}</td>
                <td class="number">${Utils.formatCurrency(q.shortRepaymentStock)}</td>
                <td class="number" style="opacity: 0.7;">${Utils.formatCurrency(q.shortRepaymentExpected)}</td>
                <td class="number">${Utils.formatCurrency(q.longRepaymentStock)}</td>
                <td class="number" style="opacity: 0.7;">${Utils.formatCurrency(q.longRepaymentExpected)}</td>
                <td class="number">${Utils.formatCurrency(q.longSellAmt)}</td>
                <td class="number ${q.periodProfit > 0 ? 'text-success' : ''}">${Utils.formatCurrency(q.periodProfit)}</td>
                <td class="number ${q.purchaseAmount > 0 ? 'text-info' : ''}">${Utils.formatCurrency(q.purchaseAmount)}</td>
            </tr>
        `;
    });
    assetTbody.innerHTML = assetHtml;
    
    // 渲染资金端（v3.40.0 新增税费和管理费列，v3.40.1 拆分资产/资金管理费）
    let fundingHtml = '';
    Object.values(quarterlyFunding).forEach(q => {
        cumulativeOutflow += q.totalExpense || q.totalOutflow;
        
        if (fundingType === 'flat') {
            fundingHtml += `
                <tr class="quarter-row">
                    <td><strong>${q.periodLabel}</strong></td>
                    <td class="number ${q.periodTax > 0 ? 'text-warning' : ''}">${Utils.formatCurrency(q.periodTax)}</td>
                    <td class="number ${q.periodAssetMgmtFee > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(q.periodAssetMgmtFee)}</td>
                    <td class="number ${q.periodFundMgmtFee > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(q.periodFundMgmtFee)}</td>
                    <td class="number ${q.interestPayment > 0 ? 'text-danger' : ''}">${Utils.formatCurrency(q.interestPayment)}</td>
                    <td class="number ${q.principalPayment > 0 ? 'text-info' : ''}">${Utils.formatCurrency(q.principalPayment)}</td>
                    <td class="number ${q.remainingPrincipal <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(q.remainingPrincipal)}</td>
                    <td class="number">${Utils.formatCurrency(cumulativeOutflow)}</td>
                </tr>
            `;
        } else {
            fundingHtml += `
                <tr class="quarter-row">
                    <td><strong>${q.periodLabel}</strong></td>
                    <td class="number ${q.periodTax > 0 ? 'text-warning' : ''}">${Utils.formatCurrency(q.periodTax)}</td>
                    <td class="number ${q.periodAssetMgmtFee > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(q.periodAssetMgmtFee)}</td>
                    <td class="number ${q.periodFundMgmtFee > 0 ? 'text-purple' : ''}">${Utils.formatCurrency(q.periodFundMgmtFee)}</td>
                    <td class="number">${Utils.formatCurrency(q.seniorInterest)}</td>
                    <td class="number">${Utils.formatCurrency(q.seniorPrincipalPay)}</td>
                    <td class="number">${Utils.formatCurrency(q.subordinateInterest)}</td>
                    <td class="number">${Utils.formatCurrency(q.subordinatePrincipalPay)}</td>
                    <td class="number ${q.remainingPrincipal <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(q.remainingPrincipal)}</td>
                </tr>
            `;
        }
    });
    fundingTbody.innerHTML = fundingHtml;
}

/**
 * 【辅助函数】重新渲染循环池现金流表格（用于切换显示模式）
 */
function renderCirculationCashflowTable() {
    const cashflow = AppState.circulationCashflow;
    if (!cashflow) return;
    
    const assetTbody = document.getElementById('assetInflowTableBody');
    const fundingTbody = document.getElementById('fundingOutflowTableBody');
    if (!assetTbody || !fundingTbody) return;
    
    const collapseToQuarter = document.getElementById('collapseToQuarter')?.checked || false;
    const fundingType = cashflow.summary?.fundingType || 'flat';
    
    if (collapseToQuarter) {
        renderQuarterlyCashflow(cashflow.assetResults, cashflow.fundingResults, assetTbody, fundingTbody, fundingType);
    } else {
        renderMonthlyCashflow(cashflow.assetResults, cashflow.fundingResults, assetTbody, fundingTbody, fundingType);
    }
}

/**
 * 【已废弃 v3.44.6】旧版信托端现金流表格更新函数
 * 请使用 updatePTCashflowTable 或 updateFACashflowTable
 * @param {string} tableBodyId - 表格body的ID
 * @param {Array} periods - 期数数据
 * @param {boolean} expandMonthly - 是否展开月度明细
 */
function updateTrustCashflowTableLegacy(tableBodyId, periods, expandMonthly = false) {
    const tbody = document.getElementById(tableBodyId);
    if (!tbody) return;
    
    // 只处理季度末数据
    const quarterPeriods = periods.filter(p => p.isQuarterEnd);
    
    let cumulativeExcess = 0;
    let rowsHtml = [];
    
    quarterPeriods.forEach((p, index) => {
        const netInflow = p.netInflow !== undefined ? p.netInflow : p.assetInflow;
        
        // 当期超额/沉淀
        const currentPeriodValue = p.excessReturn || p.periodReserveIncrease || 0;
        cumulativeExcess += currentPeriodValue;
        
        // 如果展开月度明细
        if (expandMonthly && p.monthlyDetails && p.monthlyDetails.length > 0) {
            p.monthlyDetails.forEach(m => {
                const monthRow = `
                    <tr class="monthly-row">
                        <td style="color: var(--text-light); padding-left: 20px;">${m.month}</td>
                        <td style="font-size: 0.75rem; color: var(--text-secondary);">${m.label}</td>
                        <td class="number" style="color: var(--text-secondary);">${Utils.formatCurrency(m.assetInflow || 0)}</td>
                        <td class="number default-col" style="color: var(--text-light);">${Utils.formatCurrency(m.defaultAmount || 0)}</td>
                        <td class="number recovery-col" style="color: var(--text-light);">${Utils.formatCurrency(m.recoveryAmount || 0)}</td>
                        <td class="number fee-col" style="color: var(--text-light);">${Utils.formatCurrency(m.managementFee || 0)}</td>
                        <td class="number" style="color: var(--text-secondary);">${Utils.formatCurrency(m.netInflow || 0)}</td>
                        <td class="number upfront-col" style="color: var(--text-light);">-</td>
                        <td class="number tax-col" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                    </tr>
                `;
                rowsHtml.push(monthRow);
            });
        }
        
        // 资金利息 = 优先级利息 + 劣后级利息
        const fundingInterest = (p.seniorInterest || 0) + (p.subordinateInterest || 0);
        // 资金本金 = 优先级本金 + 劣后级本金
        const fundingPrincipal = (p.seniorPrincipalRepay || 0) + (p.subordinatePrincipalRepay || 0);
        // 资金余额 = 优先级余额 + 劣后级余额
        const fundingBalance = (p.seniorBalance || 0) + (p.subordinateBalance || 0);
        
        // 利息收入显示
        const interestIncome = p.interestIncome || 0;
        const interestClass = interestIncome > 0 ? 'interest-income positive' : 'interest-income';
        
        const quarterRowClass = expandMonthly ? 'quarter-row' : '';
        const highlightClass = fundingBalance <= 0.01 ? 'highlight-row' : '';
        
        const quarterRow = `
            <tr class="${quarterRowClass} ${highlightClass}">
                <td><strong>Q${Math.ceil(p.period / 3)}</strong></td>
                <td>${p.label}</td>
                <td class="number">${Utils.formatCurrency(p.assetInflow || 0)}</td>
                <td class="number default-col">${Utils.formatCurrency(p.defaultAmount || 0)}</td>
                <td class="number recovery-col">${Utils.formatCurrency(p.recoveryAmount || 0)}</td>
                <td class="number fee-col">${Utils.formatCurrency(p.managementFee || 0)}</td>
                <td class="number">${Utils.formatCurrency(netInflow)}</td>
                <td class="number upfront-col">${Utils.formatCurrency(p.upfrontFee || 0)}</td>
                <td class="number tax-col">${Utils.formatCurrency(p.taxAmount || 0)}</td>
                <td class="number ${interestClass}">${Utils.formatCurrency(interestIncome)}</td>
                <td class="number">${Utils.formatCurrency(fundingInterest)}</td>
                <td class="number">${Utils.formatCurrency(fundingPrincipal)}</td>
                <td class="number ${fundingBalance <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(fundingBalance)}</td>
                <td class="number ${currentPeriodValue < 0 ? 'negative-value' : ''}">${Utils.formatCurrencyAccounting(currentPeriodValue)}</td>
                <td class="number highlight-value">${Utils.formatCurrencyAccounting(cumulativeExcess)}</td>
            </tr>
        `;
        rowsHtml.push(quarterRow);
    });
    
    tbody.innerHTML = rowsHtml.join('');
}

/**
 * 更新单个模式的表格
 * @param {string} tableBodyId - 表格body的ID
 * @param {Array} periods - 期数数据
 * @param {boolean} showCashReserve - true显示信托池沉淀，false显示超额收益
 * @param {boolean} expandMonthly - 是否展开月度明细
 */
function updateModeTable(tableBodyId, periods, showCashReserve, expandMonthly = false) {
    const tbody = document.getElementById(tableBodyId);
    if (!tbody) return;
    
    // 只处理季度末数据（包含月度明细）
    const quarterPeriods = periods.filter(p => p.isQuarterEnd);
    
    // 计算累计值
    let cumulativeExcess = 0;           // 累计超额收益
    let lastCumulativeReserve = 0;      // 最后一次有效的累计沉淀
    let rowsHtml = [];
    
    // 如果是固定摊还模式，预计算非现处置收益
    let nonCurrentDisposalData = null;
    if (showCashReserve) {
        nonCurrentDisposalData = calculateNonCurrentDisposalReturns(periods);
    }
    
    quarterPeriods.forEach((p, index) => {
        // 计算净回款
        const netInflow = p.netInflow !== undefined ? p.netInflow : p.assetInflow;
        
        let currentPeriodValue = 0;
        let cumulativeValue = 0;
        
        if (showCashReserve) {
            const periodIncrease = p.periodReserveIncrease !== undefined ? p.periodReserveIncrease : 0;
            const endingReserve = p.cashReserve || 0;
            
            if (p.seniorBalance <= 0.01) {
                currentPeriodValue = p.excessReturn || 0;
                cumulativeExcess += currentPeriodValue;
                cumulativeValue = lastCumulativeReserve + cumulativeExcess;
            } else {
                currentPeriodValue = periodIncrease;
                cumulativeValue = endingReserve;
                lastCumulativeReserve = endingReserve;
            }
        } else {
            currentPeriodValue = p.excessReturn || 0;
            cumulativeExcess += currentPeriodValue;
            cumulativeValue = cumulativeExcess;
        }
        
        // 如果展开月度明细，先添加月度行
        if (expandMonthly && p.monthlyDetails && p.monthlyDetails.length > 0) {
            p.monthlyDetails.forEach(m => {
                const monthRow = `
                    <tr class="monthly-row">
                        <td style="color: var(--text-light); padding-left: 20px;">${m.month}</td>
                        <td style="font-size: 0.75rem; color: var(--text-secondary);">${m.label}</td>
                        <td class="number" style="color: var(--text-secondary);">${Utils.formatCurrency(m.assetInflow || 0)}</td>
                        <td class="number default-col" style="color: var(--text-light);">${Utils.formatCurrency(m.defaultAmount || 0)}</td>
                        <td class="number recovery-col" style="color: var(--text-light);">${Utils.formatCurrency(m.recoveryAmount || 0)}</td>
                        <td class="number fee-col" style="color: var(--text-light);">${Utils.formatCurrency(m.managementFee || 0)}</td>
                        <td class="number" style="color: var(--text-secondary);">${Utils.formatCurrency(m.netInflow || 0)}</td>
                        <td class="number upfront-col" style="color: var(--text-light);">-</td>
                        <td class="number tax-col" style="color: var(--text-light);">-</td>
                        <td class="number interest-income" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                        <td class="number" style="color: var(--text-light);">-</td>
                    </tr>
                `;
                rowsHtml.push(monthRow);
            });
        }
        
        // 利息收入显示（分类）
        const interestIncome = p.interestIncome || 0;
        const interestClass = interestIncome > 0 ? 'interest-income positive' : 'interest-income';
        
        // 构建利息明细tooltip（根据模式区分）
        let interestTooltipHtml = '';
        if (interestIncome > 0) {
            if (showCashReserve) {
                // 固定摊还：沉淀资金利息 + 季度暂存利息
                const reserveInt = p.reserveInterest || 0;
                const quarterlyInt = p.quarterlyInterest || 0;
                interestTooltipHtml = `
                    <span class="interest-tooltip">
                        ${Utils.formatCurrency(interestIncome)}
                        <span class="tooltip-content">
                            <div class="tooltip-row"><span class="label">沉淀资金利息:</span><span class="value">${Utils.formatCurrency(reserveInt)}</span></div>
                            <div class="tooltip-row"><span class="label">季度暂存利息:</span><span class="value">${Utils.formatCurrency(quarterlyInt)}</span></div>
                            <div class="tooltip-row"><span class="label">合计:</span><span class="value">${Utils.formatCurrency(interestIncome)}</span></div>
                        </span>
                    </span>`;
            } else {
                // 过手摊还：信保基金利息 + 季度暂存利息 + 超额沉淀利息
                const gfInt = p.guaranteeFundInterest || 0;
                const quarterlyInt = p.quarterlyInterest || 0;
                const excessInt = p.excessReserveInterest || 0;
                interestTooltipHtml = `
                    <span class="interest-tooltip">
                        ${Utils.formatCurrency(interestIncome)}
                        <span class="tooltip-content">
                            <div class="tooltip-row"><span class="label">信保基金利息:</span><span class="value">${Utils.formatCurrency(gfInt)}</span></div>
                            <div class="tooltip-row"><span class="label">季度暂存利息:</span><span class="value">${Utils.formatCurrency(quarterlyInt)}</span></div>
                            <div class="tooltip-row"><span class="label">超额沉淀利息:</span><span class="value">${Utils.formatCurrency(excessInt)}</span></div>
                            <div class="tooltip-row"><span class="label">合计:</span><span class="value">${Utils.formatCurrency(interestIncome)}</span></div>
                        </span>
                    </span>`;
            }
        } else {
            interestTooltipHtml = Utils.formatCurrency(interestIncome);
        }
        
        // 季度汇总行
        const quarterRowClass = expandMonthly ? 'quarter-row' : '';
        const highlightClass = p.seniorBalance <= 0.01 && p.subordinateBalance > 0.01 ? 'highlight-row' : '';
        
        // 构建累计沉淀/超额的显示HTML（固定摊还模式添加非现处置收益tooltip）
        let cumulativeValueHtml = Utils.formatCurrencyAccounting(cumulativeValue);
        let isMaxNCD = false;  // 是否是非现处置收益最大的期
        
        if (showCashReserve && nonCurrentDisposalData) {
            // 找到当前期数对应的非现处置收益数据
            const ncdData = nonCurrentDisposalData.data.find(d => d.period === p.period);
            if (ncdData) {
                const ncdReturn = ncdData.nonCurrentDisposalReturn;
                // 检查是否是最大值期
                isMaxNCD = (p.period === nonCurrentDisposalData.maxPeriod);
                
                const maxBadge = isMaxNCD ? '<span class="max-ncd-badge"><i class="fas fa-star"></i> 最优</span>' : '';
                
                cumulativeValueHtml = `
                    <span class="reserve-tooltip ${isMaxNCD ? 'max-ncd' : ''}">
                        ${Utils.formatCurrencyAccounting(cumulativeValue)}${isMaxNCD ? ' <i class="fas fa-star ncd-star"></i>' : ''}
                        <span class="tooltip-content ncd-tooltip">
                            <div class="tooltip-title"><i class="fas fa-info-circle"></i> 非现处置收益 ${maxBadge}</div>
                            <div class="tooltip-row"><span class="label">后续现金流回款:</span><span class="value">${Utils.formatCurrency(ncdData.futureNetInflow)}</span></div>
                            <div class="tooltip-row"><span class="label">+ 累计沉淀:</span><span class="value">${Utils.formatCurrency(ncdData.cashReserve)}</span></div>
                            <div class="tooltip-row"><span class="label">- 优先级余额:</span><span class="value">${Utils.formatCurrency(ncdData.seniorBalance)}</span></div>
                            <div class="tooltip-row"><span class="label">- 劣后级余额:</span><span class="value">${Utils.formatCurrency(ncdData.subordinateBalance)}</span></div>
                            <div class="tooltip-divider"></div>
                            <div class="tooltip-row total"><span class="label">= 非现处置收益:</span><span class="value ${ncdReturn >= 0 ? 'positive' : 'negative'}">${Utils.formatCurrency(ncdReturn)}</span></div>
                        </span>
                    </span>`;
            }
        }
        
        // 为最大非现处置收益的行添加特殊样式
        const maxNCDRowClass = isMaxNCD ? 'max-ncd-row' : '';
        
        const quarterRow = `
            <tr class="${quarterRowClass} ${highlightClass} ${maxNCDRowClass}">
                <td><strong>Q${Math.ceil(p.period / 3)}</strong></td>
                <td>${p.label}</td>
                <td class="number">${Utils.formatCurrency(p.assetInflow || 0)}</td>
                <td class="number default-col">${Utils.formatCurrency(p.defaultAmount || 0)}</td>
                <td class="number recovery-col">${Utils.formatCurrency(p.recoveryAmount || 0)}</td>
                <td class="number fee-col">${Utils.formatCurrency(p.managementFee || 0)}</td>
                <td class="number">${Utils.formatCurrency(netInflow)}</td>
                <td class="number upfront-col">${Utils.formatCurrency(p.upfrontFee || 0)}</td>
                <td class="number tax-col">${Utils.formatCurrency(p.taxAmount || 0)}</td>
                <td class="number ${interestClass}">${interestTooltipHtml}</td>
                <td class="number">${Utils.formatCurrency(p.seniorInterest)}</td>
                <td class="number">${Utils.formatCurrency(p.subordinateInterest)}</td>
                <td class="number">${Utils.formatCurrency(p.seniorPrincipalRepay)}</td>
                <td class="number ${p.seniorBalance <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(p.seniorBalance)}</td>
                <td class="number">${Utils.formatCurrency(p.subordinatePrincipalRepay)}</td>
                <td class="number ${p.subordinateBalance <= 0.01 ? 'text-success' : ''}">${Utils.formatCurrency(p.subordinateBalance)}</td>
                <td class="number ${currentPeriodValue < 0 ? 'negative-value' : ''}">${Utils.formatCurrencyAccounting(currentPeriodValue)}</td>
                <td class="number highlight-value">${cumulativeValueHtml}</td>
            </tr>
        `;
        rowsHtml.push(quarterRow);
    });
    
    tbody.innerHTML = rowsHtml.join('');
}

