// 一次遍历提取所有图表需要的数据
function prepareTrustChartData(trustCashflow) {
    const periods = trustCashflow.periods;
    const len = periods.length;
    
    const labels = new Array(len);
    const seniorInterest = new Array(len);
    const subordinateInterest = new Array(len);
    const seniorPrincipalRepay = new Array(len);
    const subordinatePrincipalRepay = new Array(len);
    const excessReturn = new Array(len);
    const seniorBalance = new Array(len);
    const subordinateBalance = new Array(len);
    const assetInflow = new Array(len);
    
    for (let i = 0; i < len; i++) {
        const p = periods[i];
        labels[i] = p.label;
        seniorInterest[i] = p.seniorInterest;
        subordinateInterest[i] = p.subordinateInterest;
        seniorPrincipalRepay[i] = p.seniorPrincipalRepay;
        subordinatePrincipalRepay[i] = p.subordinatePrincipalRepay;
        excessReturn[i] = p.excessReturn;
        seniorBalance[i] = p.seniorBalance;
        subordinateBalance[i] = p.subordinateBalance;
        assetInflow[i] = p.assetInflow;
    }
    
    return {
        labels, seniorInterest, subordinateInterest, 
        seniorPrincipalRepay, subordinatePrincipalRepay,
        excessReturn, seniorBalance, subordinateBalance, assetInflow
    };
}

