                { label: '劣后级本金', data: chartData.subordinatePrincipalRepay, backgroundColor: '#3b82f6', stack: 'stack1' },
                { label: '超额收益', data: chartData.excessReturn, backgroundColor: '#10b981', stack: 'stack1' }
