function updateTrustTable(trustCashflow) {
    const tbody = document.getElementById('trustCashflowTableBody');
    const periods = trustCashflow.periods;
    const len = periods.length;
    
    // 使用数组拼接，比map+join更快
    const rows = new Array(len);
    let cumulativeReserve = 0;
    
    for (let i = 0; i < len; i++) {
        const p = periods[i];
        cumulativeReserve += p.excessReturn || 0;
        const rowClass = p.isQuarterEnd ? 'quarter-end-row' : '';
        const quarterBadge = p.isQuarterEnd ? ' <span class="quarter-badge">季末</span>' : '';
        
        rows[i] = `<tr class="${rowClass}"><td>${p.period}${quarterBadge}</td><td>${p.label}</td><td>${Utils.formatCurrency(p.assetInflow)}</td><td>${Utils.formatCurrency(p.seniorInterest)}</td><td>${Utils.formatCurrency(p.subordinateInterest)}</td><td>${Utils.formatCurrency(p.seniorPrincipalRepay)}</td><td>${Utils.formatCurrency(p.seniorBalance)}</td><td>${Utils.formatCurrency(p.subordinatePrincipalRepay)}</td><td>${Utils.formatCurrency(p.subordinateBalance)}</td><td>${Utils.formatCurrency(p.excessReturn)}</td><td class="highlight-cell">${Utils.formatCurrency(cumulativeReserve)}</td></tr>`;
    }
    
    tbody.innerHTML = rows.join('');
}

// ========================================
// 数据导入
// ========================================

function initImport() {
    const dropZone = document.getElementById('dropZone');
    const fileInput = document.getElementById('fileInput');
    const selectFileBtn = document.getElementById('selectFileBtn');
    
    // 安全绑定事件
    if (selectFileBtn && fileInput) {
        selectFileBtn.addEventListener('click', () => fileInput.click());
    }
    if (dropZone && fileInput) {
        dropZone.addEventListener('click', (e) => {
            if (e.target === dropZone || e.target.tagName === 'I' || 
                e.target.tagName === 'H3' || e.target.tagName === 'P') {
                fileInput.click();
            }
        });
        
        dropZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropZone.classList.add('drag-over');
        });
        
        dropZone.addEventListener('dragleave', () => {
            dropZone.classList.remove('drag-over');
        });
        
        dropZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropZone.classList.remove('drag-over');
            if (e.dataTransfer.files.length > 0) handleFile(e.dataTransfer.files[0]);
        });
    }
    
    if (fileInput) {
        fileInput.addEventListener('change', (e) => {
            if (e.target.files.length > 0) handleFile(e.target.files[0]);
        });
    }
    
    const downloadBtn = document.getElementById('downloadTemplate');
    const cancelBtn = document.getElementById('cancelImport');
    const confirmBtn = document.getElementById('confirmImport');
    const clearBtn = document.getElementById('clearAllData');
    
    if (downloadBtn) downloadBtn.addEventListener('click', downloadTemplate);
    if (cancelBtn) {
        cancelBtn.addEventListener('click', () => {
            const preview = document.getElementById('previewSection');
            if (preview) preview.style.display = 'none';
            AppState.previewData = null;
        });
    }
    if (confirmBtn) confirmBtn.addEventListener('click', confirmImport);
    if (clearBtn) clearBtn.addEventListener('click', clearAllAssetData);
    
    // 迁移孤立数据按钮
    const migrateBtn = document.getElementById('migrateOrphanData');
    if (migrateBtn) migrateBtn.addEventListener('click', migrateOrphanDataToCurrentModel);
    
    // 更新当前资产数量显示
    updateCurrentAssetCount();
}

// 更新当前资产数量显示
async function updateCurrentAssetCount() {
    try {
        const result = await API.getAssets(1, 1);
        const total = result.total || 0;
        document.getElementById('currentAssetCount').textContent = Utils.formatNumber(total);
    } catch (error) {
        document.getElementById('currentAssetCount').textContent = '0';
    }
}

// 迁移孤立数据到当前模型
async function migrateOrphanDataToCurrentModel() {
    const currentModelId = ModelManager.currentModelId;
    const currentModelName = ModelManager.getCurrentModel()?.name || '当前模型';
    
    const confirmed = confirm(`此操作会将数据库中所有关联到其他模型ID的资产数据迁移到"${currentModelName}"。\n\n确定要继续吗？`);
    if (!confirmed) return;
    
    try {
        showToast('正在扫描孤立数据...', 'info');
        console.log(`【数据迁移】当前模型ID: ${currentModelId}`);
        
        // 获取所有数据（不过滤modelId）
        const response = await fetch(`${API.baseUrl}?page=1&limit=100`);
        const firstResult = await response.json();
        const totalInDb = firstResult.total || 0;
        
        console.log(`【数据迁移】数据库总数据量: ${totalInDb}`);
        
        if (totalInDb === 0) {
            showToast('数据库中没有任何数据', 'warning');
            return;
        }
        
        // 收集所有孤立数据（modelId不是当前模型的）
        let orphanAssets = [];
        const totalPages = Math.ceil(totalInDb / 100);
        
        showToast(`正在扫描 ${totalInDb} 条数据...`, 'info');
        
        for (let page = 1; page <= Math.min(totalPages, 50); page++) {
            const res = await fetch(`${API.baseUrl}?page=${page}&limit=100`);
            const result = await res.json();
            const assets = result.data || [];
            
            // 找出不属于当前模型的数据
            const orphans = assets.filter(a => a.modelId !== currentModelId);
            orphanAssets = orphanAssets.concat(orphans);
            
            if (page % 10 === 0) {
                console.log(`【数据迁移】已扫描 ${page}/${totalPages} 页，发现 ${orphanAssets.length} 条孤立数据`);
            }
        }
        
        console.log(`【数据迁移】共发现 ${orphanAssets.length} 条孤立数据`);
        
        if (orphanAssets.length === 0) {
            showToast('没有发现孤立数据，所有数据都已关联到当前模型', 'success');
            return;
        }
        
        const confirmMigrate = confirm(`发现 ${orphanAssets.length} 条孤立数据，确定要将它们迁移到"${currentModelName}"吗？`);
        if (!confirmMigrate) return;
        
        showToast(`正在迁移 ${orphanAssets.length} 条数据...`, 'info');
        
        // 批量更新modelId
        let successCount = 0;
        let failCount = 0;
        const BATCH_SIZE = 50;
        
        for (let i = 0; i < orphanAssets.length; i += BATCH_SIZE) {
            const batch = orphanAssets.slice(i, i + BATCH_SIZE);
            
            const promises = batch.map(asset => 
                fetch(`${API.baseUrl}/${asset.id}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ modelId: currentModelId })
                }).then(res => {
                    if (res.ok) successCount++;
                    else failCount++;
                }).catch(() => failCount++)
            );
            
            await Promise.all(promises);
            
            const progress = Math.round((i + batch.length) / orphanAssets.length * 100);
            console.log(`【数据迁移】进度: ${progress}% (${successCount} 成功, ${failCount} 失败)`);
        }
        
        console.log(`【数据迁移】完成: ${successCount} 成功, ${failCount} 失败`);
        showToast(`迁移完成: ${successCount} 条成功, ${failCount} 条失败`, successCount > 0 ? 'success' : 'error');
        
        // 刷新数据
        if (successCount > 0) {
            await updateDashboard(true); // 强制重新加载
            await updateCurrentAssetCount();
            ModelManager.renderModelList();
        }
        
    } catch (error) {
        console.error('数据迁移失败:', error);
        showToast('数据迁移失败: ' + error.message, 'error');
    }
}

// 【全局】清空数据库中所有信托模型的资产数据
/**
 * 【v3.44.4重构】全局清空数据
 * 使用优化的批量删除API
 */
async function clearAllDataGlobal() {
    // 第一次确认
    const confirmed = confirm('⚠️ 警告：此操作将删除数据库中【所有信托模型】的资产数据！\n\n这包括：信托一号、信托二号等所有模型的数据。\n\n确定要继续吗？此操作不可恢复！');
    if (!confirmed) return;
    
    try {
        // 【v3.45.30优化】快速获取数据总数和ID列表
        showToast('正在统计数据...', 'info');
        
        // 并行获取所有数据（使用服务端允许的最大分页）
        const pageSize = API.maxLimit;
        const firstResult = await API.getAssetsRaw(1, pageSize);
        const totalInDb = firstResult.total || 0;
        
        if (totalInDb === 0) {
            showToast('数据库中没有任何数据', 'info');
            return;
        }
        
        // 快速获取所有ID
        let allAssets = firstResult.data || [];
        const totalPages = Math.ceil(totalInDb / pageSize);
        
        if (totalPages > 1) {
            // 并行获取剩余页
            const FETCH_CONCURRENT = 10;
            for (let page = 2; page <= totalPages; page += FETCH_CONCURRENT) {
                const batch = [];
                for (let p = page; p < page + FETCH_CONCURRENT && p <= totalPages; p++) {
                    batch.push(API.getAssetsRaw(p, pageSize));
                }
                const results = await Promise.all(batch);
                results.forEach(r => {
                    if (r.data) allAssets = allAssets.concat(r.data);
                });
            }
        }
        
        console.log(`【全局清空 v3.45.30】获取到 ${allAssets.length} 条数据`);
        
        // 第二次确认（显示具体数量）
        const doubleConfirmed = confirm(`🚨 最后确认：数据库中共有 ${totalInDb} 条资产数据，确定要全部删除吗？\n\n删除后所有信托模型将变为空！`);
        if (!doubleConfirmed) return;
        
        // 显示删除进度条
        const progressHtml = `
            <div id="deleteProgressOverlay" style="position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.7); z-index: 10000; display: flex; align-items: center; justify-content: center;">
                <div style="background: var(--bg-card); padding: 24px 32px; border-radius: var(--radius-lg); min-width: 320px; text-align: center;">
                    <h3 style="margin: 0 0 16px 0; color: var(--danger-color);">正在清空数据</h3>
                    <div style="background: var(--bg-secondary); border-radius: 4px; height: 24px; overflow: hidden; margin-bottom: 8px;">
                        <div id="deleteProgressBar" style="height: 100%; background: linear-gradient(90deg, var(--danger-color), var(--warning-color)); width: 0%; transition: width 0.3s;"></div>
                    </div>
                    <div id="deleteProgressText" style="color: var(--text-muted); font-size: 0.85rem;">准备中...</div>
                </div>
            </div>
        `;
        document.body.insertAdjacentHTML('beforeend', progressHtml);
        
        console.log(`【全局清空】开始删除 ${totalInDb} 条数据...`);
        const startTime = Date.now();
        
        // 【v3.45.30】使用超高性能批量删除API
        const allAssetIds = allAssets.map(a => a.id);
        const result = await API.deleteAssetsBatch(allAssetIds, (progress, deleted) => {
            const progressBar = document.getElementById('deleteProgressBar');
            const progressText = document.getElementById('deleteProgressText');
            if (progressBar) progressBar.style.width = progress + '%';
            if (progressText) {
                const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
                const speed = elapsed > 0 ? Math.round(deleted / elapsed) : 0;
                progressText.textContent = `${progress}% - 已删除 ${deleted}/${totalInDb} 条 (${speed}条/秒)`;
            }
        });
        
        let totalDeleted = result.deleted;
        
        let totalTime = ((Date.now() - startTime) / 1000).toFixed(1);
        let speed = Math.round(totalDeleted / (Date.now() - startTime) * 1000);
        console.log(`【全局清空】第一轮完成，共删除 ${totalDeleted} 条数据，耗时 ${totalTime}s，速度 ${speed}条/秒`);
        
        // 🔧 v3.45.51: 验证并循环删除，直到完全清空
        let remainingAfterDelete = 0;
        let retryCount = 0;
        const MAX_RETRIES = 5;
        
        while (retryCount < MAX_RETRIES) {
            const verifyResponse = await fetch(`${API.baseUrl}?page=1&limit=1`);
            const verifyResult = await verifyResponse.json();
            remainingAfterDelete = verifyResult.total || 0;
            console.log(`【全局清空 v3.45.51】验证: 删除后剩余 ${remainingAfterDelete} 条`);
            
            if (remainingAfterDelete === 0) {
                break; // 完全清空了
            }
            
            retryCount++;
            console.log(`【全局清空 v3.45.51】第 ${retryCount + 1} 轮清空，剩余 ${remainingAfterDelete} 条...`);
            
            // 更新进度文字
            const progressText = document.getElementById('deleteProgressText');
            if (progressText) {
                progressText.textContent = `第 ${retryCount + 1} 轮清空，剩余 ${remainingAfterDelete} 条...`;
            }
            
            // 重新获取剩余数据并删除
            const remainingResult = await API.getAssetsRaw(1, pageSize);
            let remainingAssets = remainingResult.data || [];
            const remainingPages = Math.ceil(remainingAfterDelete / pageSize);
            
            if (remainingPages > 1) {
                for (let page = 2; page <= remainingPages; page++) {
                    const pageResult = await API.getAssetsRaw(page, pageSize);
                    if (pageResult.data) remainingAssets = remainingAssets.concat(pageResult.data);
                }
            }
            
            if (remainingAssets.length > 0) {
                const remainingIds = remainingAssets.map(a => a.id);
                const retryResult = await API.deleteAssetsBatch(remainingIds, (progress, deleted) => {
                    const progressBar = document.getElementById('deleteProgressBar');
                    if (progressBar) progressBar.style.width = progress + '%';
                    if (progressText) {
                        progressText.textContent = `第 ${retryCount + 1} 轮: ${progress}% - 已删除 ${deleted}/${remainingIds.length} 条`;
                    }
                });
                totalDeleted += retryResult.deleted;
            }
        }
        
        totalTime = ((Date.now() - startTime) / 1000).toFixed(1);
        speed = Math.round(totalDeleted / parseFloat(totalTime));
        console.log(`【全局清空 v3.45.51】最终完成，共删除 ${totalDeleted} 条数据，耗时 ${totalTime}s`);
        
        // 清空所有本地状态
        AppState.assets = [];
        AppState.assetsModelId = API.getCurrentModelId();
        AppState.totalAssetCount = 0;
        AppState.currentPage = 1;
        AppState.totalPages = 1;
        AppState.fullAssets = [];
        AppState.partialAssets = [];
        AppState.stats = {};
        trustAssetData.fullAssetTotal = 0;
        trustAssetData.partialAssetTotal = 0;
        trustAssetData.totalAssetPool = 0;
        trustAssetData.trustPoolSize = 0;
        
        // 清空所有模型的本地缓存
        console.log(`【全局清空】清空 ${ModelManager.models.length} 个模型的本地缓存`);
        ModelManager.models.forEach(model => {
            console.log(`【全局清空】清空模型 "${model.name}" 的数据（原有 ${(model.data.assets || []).length} 条）`);
            model.data.assets = [];
            model.data.analysisResults = null;
        });
        ModelManager.saveToStorage();
        console.log('【全局清空】已保存到localStorage');
        
        // 强制更新UI - 确保显示0
        updateAllStats();
        updateCategoryStats();
        updateAssetDataDisplay();
        updateTrustPoolSize();
        updateTrustPrincipalDisplay();
        
        // 更新侧边栏显示
        console.log(`【全局清空】刷新侧边栏，AppState.assets.length = ${AppState.assets.length}`);
        ModelManager.models.forEach(m => {
            console.log(`【全局清空】模型 "${m.name}": data.assets.length = ${(m.data.assets || []).length}`);
        });
        ModelManager.renderModelList();
        
        // 更新数据导入页面的计数
        const countEl = document.getElementById('currentAssetCount');
        if (countEl) countEl.textContent = '0';
        
        // 移除进度条
        const overlay = document.getElementById('deleteProgressOverlay');
        if (overlay) overlay.remove();
        
        if (remainingAfterDelete > 0) {
            showToast(`已删除 ${totalDeleted} 条，但仍有 ${remainingAfterDelete} 条未能删除（可能是软删除）`, 'warning');
        } else {
            showToast(`已清空所有数据，共删除 ${totalDeleted} 条`, 'success');
        }
        
    } catch (error) {
        console.error('【全局清空】失败:', error);
        showToast('清空数据失败: ' + error.message, 'error');
        
        // 移除进度条
        const overlay = document.getElementById('deleteProgressOverlay');
        if (overlay) overlay.remove();
    }
}

