    if (!fullAnalysisResults) {
        showToast('请先运行全部分析', 'warning');
        return;
    }
    
    // 判断模型类型
    const isCirculation = isCirculationPoolModel();
    
    if (isCirculation) {
        // 流转型信托使用专用导出
        await downloadCirculationResults();
        return;
    }
    
    // 以下是持有型信托的导出逻辑
