// 创建报告摘要
function createExecutiveSummary(assetSummary, trustPoolSize, seniorPrincipal, subordinatePrincipal, ptMode, faMode, config, assetCashflow) {
    const { Paragraph, TextRun } = docx;
    const formatCurrencyWan = (val) => ((val || 0) / 10000).toFixed(2) + '万';
    const ptExcessRatio = trustPoolSize > 0 ? (ptMode.totalExcess / trustPoolSize * 100).toFixed(2) : '0';
    const defaultRate = trustPoolSize > 0 ? (assetCashflow.totalDefaultAmount / trustPoolSize * 100).toFixed(4) : '0';
    
    return [
        new Paragraph({
            children: [
                new TextRun({ text: "本报告是对外贸信托-美好生活1号集合资金信托计划的现金流预测分析，基于贝壳装修施工应收账款模拟基础资产池，采用静态情景假设，全面评估资产池未来现金流分布、偿付能力及风险敞口。", size: 22 })
            ],
            spacing: { after: 200 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "核心结论：", bold: true, size: 22 }),
                new TextRun({ text: `本信托计划基础资产池共计${assetSummary.totalCount}笔资产，入池金额¥${formatCurrencyWan(trustPoolSize)}。在当前假设参数下，资产端预计总回款¥${formatCurrencyWan(assetCashflow.totalIncome)}，累计违约损失率${defaultRate}%。`, size: 22 })
            ],
            spacing: { after: 150 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "偿付能力分析：", bold: true, size: 22 }),
                new TextRun({ text: `过手摊还模式下，优先级本金（¥${formatCurrencyWan(seniorPrincipal)}）预计于第${ptMode.clearTimes?.seniorClearTime?.period || '-'}期还清，劣后级本金预计于第${ptMode.clearTimes?.subordinateClearTime?.period || '-'}期还清。超额收益¥${formatCurrencyWan(ptMode.totalExcess)}（占信托规模${ptExcessRatio}%），表明资产池具备充足的偿付能力和安全边际。`, size: 22 })
            ],
            spacing: { after: 150 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "固定摊还模式下，优先级采用", size: 22 }),
                new TextRun({ text: config.faSeniorPeriods ? `${config.faSeniorPeriods/4}年` : "2年", bold: true, size: 22 }),
                new TextRun({ text: "等额本息还款，季度还款额稳定，有利于投资人现金流规划。期末累计沉淀¥" + formatCurrencyWan(faMode.cashReserve) + "，作为流动性储备。", size: 22 })
            ],
            spacing: { after: 200 }
        })
    ];
}

