// 创建资产池概况说明
function createAssetPoolDesc(assetSummary, pooledAssets, config) {
    const { Paragraph, TextRun } = docx;
    const formatCurrencyWan = (val) => '¥' + ((val || 0) / 10000).toFixed(2) + '万';
    const fullRatio = ((pooledAssets.fullTotal / pooledAssets.total) * 100).toFixed(1);
    const partialRatio = ((pooledAssets.partialTotal / pooledAssets.total) * 100).toFixed(1);
    
    return [
        new Paragraph({
            children: [
                new TextRun({ text: `本次入池的模拟基础资产池共计${assetSummary.totalCount}笔资产，应收账款余额合计${formatCurrencyWan(assetSummary.remainingAmount)}。按照约定的折价购买方式，入池金额为${formatCurrencyWan(pooledAssets.total)}。`, size: 22 })
            ],
            spacing: { after: 150 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "资产构成：", bold: true, size: 22 }),
                new TextRun({ text: `整装资产${assetSummary.fullCount}笔，入池金额${formatCurrencyWan(pooledAssets.fullTotal)}，占比${fullRatio}%；局装资产${assetSummary.partialCount}笔，入池金额${formatCurrencyWan(pooledAssets.partialTotal)}，占比${partialRatio}%。资产池以整装资产为主，具有较高的单笔金额和较长的回款周期。`, size: 22 })
            ],
            spacing: { after: 200 }
        })
    ];
}

