// 创建敏感性分析
function createSensitivityAnalysis(stressTest, trustPoolSize, config) {
    const { Paragraph, TextRun } = docx;
    
    if (!stressTest || !stressTest.scenarios || stressTest.scenarios.length < 6) {
        return [new Paragraph({ children: [new TextRun({ text: "敏感性分析数据暂未生成。", size: 22 })] })];
    }
    
    const base = stressTest.scenarios.find(s => s.name.includes('当前'));
    const pdUp = stressTest.scenarios.find(s => s.name.includes('PD') && !s.name.includes('双重') && !s.name.includes('临界'));
    const vacUp = stressTest.scenarios.find(s => s.name.includes('空置') && !s.name.includes('双重'));
    
    const baseExcess = base ? (base.ptExcess || base.excess || 0) : 0;
    const pdUpExcess = pdUp ? (pdUp.ptExcess || pdUp.excess || 0) : 0;
    const vacUpExcess = vacUp ? (vacUp.ptExcess || vacUp.excess || 0) : 0;
    
    const pdSensitivity = baseExcess > 0 ? ((baseExcess - pdUpExcess) / baseExcess * 100).toFixed(1) : '-';
    const vacSensitivity = baseExcess > 0 ? ((baseExcess - vacUpExcess) / baseExcess * 100).toFixed(1) : '-';
    
    return [
        new Paragraph({
            children: [
                new TextRun({ text: "敏感性分析结果表明：", size: 22 })
            ],
            spacing: { after: 150 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "违约概率敏感性：", bold: true, size: 22 }),
                new TextRun({ text: `当PD提高50%时，超额收益下降约${pdSensitivity}%。违约概率是影响信托偿付能力的关键因素。`, size: 22 })
            ],
            spacing: { after: 100 },
            indent: { left: 300 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "空置期敏感性：", bold: true, size: 22 }),
                new TextRun({ text: `当空置期延长至40天时，超额收益下降约${vacSensitivity}%。空置期对现金流时点有一定影响，但因不产生金额损失，影响相对有限。`, size: 22 })
            ],
            spacing: { after: 100 },
            indent: { left: 300 }
        }),
        new Paragraph({
            children: [
                new TextRun({ text: "风险排序：", bold: true, size: 22 }),
                new TextRun({ text: "信用风险（违约概率）> 市场风险（空置期），建议重点关注基础资产的信用质量和违约率变化。", size: 22 })
            ],
            spacing: { after: 200 },
            indent: { left: 300 }
        })
    ];
}

