// 创建核心指标表格
function createKeyMetricsTable(assetSummary, trustPoolSize, seniorPrincipal, subordinatePrincipal, ptMode, faMode, config) {
    const { Table, TableRow, TableCell, Paragraph, TextRun, WidthType, BorderStyle } = docx;
    const formatCurrency = (val) => '¥' + ((val || 0) / 10000).toFixed(2) + '万';
    const formatPercent = (val) => (val || 0).toFixed(2) + '%';
    
    const ptExcessRatio = trustPoolSize > 0 ? (ptMode.totalExcess / trustPoolSize * 100) : 0;
    
    const rows = [
        ['核心指标', '数值', '核心指标', '数值'],
        ['资产池规模', assetSummary.totalCount + '笔', '信托规模', formatCurrency(trustPoolSize)],
        ['优先级本金', formatCurrency(seniorPrincipal), '劣后级本金', formatCurrency(subordinatePrincipal)],
        ['优先级利率', config.seniorRate + '%/年', '劣后级收益率', config.subordinateRate + '%/年'],
        ['过手超额收益', formatCurrency(ptMode.totalExcess), '超额收益比例', formatPercent(ptExcessRatio)],
        ['优先级还清', ptMode.clearTimes?.seniorClearTime ? '第' + ptMode.clearTimes.seniorClearTime.period + '期' : '-', 
         '劣后级还清', ptMode.clearTimes?.subordinateClearTime ? '第' + ptMode.clearTimes.subordinateClearTime.period + '期' : '-']
    ];
    
    return new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: rows.map((row, idx) => new TableRow({
            children: row.map((cell, cidx) => new TableCell({
                children: [new Paragraph({
                    children: [new TextRun({ text: cell, bold: idx === 0 || cidx % 2 === 0, size: 20, 
                        color: idx === 0 ? "FFFFFF" : undefined })],
                    alignment: cidx % 2 === 1 ? docx.AlignmentType.RIGHT : docx.AlignmentType.LEFT
                })],
                shading: idx === 0 ? { fill: "00263A" } : (idx % 2 === 0 ? { fill: "F5F5F5" } : undefined),
                borders: { top: { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" },
                          bottom: { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" } }
            }))
        }))
    });
}

