// 创建术语表
function createGlossaryTable() {
    const { Table, TableRow, TableCell, Paragraph, TextRun, WidthType } = docx;
    
    const terms = [
        ['PD (违约概率)', 'Probability of Default，借款人在一定时期内违约的可能性'],
        ['LGD (违约损失率)', 'Loss Given Default，违约发生后无法回收的损失比例'],
        ['过手摊还', 'Pass-Through，回款全部用于偿还，先息后本'],
        ['固定摊还', 'Fixed Amortization，按固定计划偿还本息'],
        ['等额本息', '每期还款金额固定，本金递增、利息递减'],
        ['等额本金', '每期还本金固定，还款金额递减'],
        ['信保基金', '信用保障基金，用于补偿可能的损失'],
        ['超额收益', '偿还全部本息后的剩余现金流'],
        ['沉淀资金', '固定摊还模式下，优先级还清前的累计剩余资金'],
        ['空置期', '整装资产续租时的空置时间，仅延迟回款不产生损失'],
        ['空置效应', '= 资产回款 - 原始回款。正数表示信托期前累积的推迟使回款"移入"信托期；负数表示信托期内的推迟使回款"移出"到信托期后'],
        ['原始回款', '不含空置期调整的理论回款金额，与资产端现金流分析一致'],
        ['资产回款', '含空置期调整的实际到账金额，整装资产每12个月续租推迟0.5个月']
    ];
    
    const rows = [['术语', '解释']];
    terms.forEach(t => rows.push(t));
    
    return new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: rows.map((row, idx) => new TableRow({
            children: row.map((cell, cidx) => new TableCell({
                children: [new Paragraph({
                    children: [new TextRun({ text: cell, bold: idx === 0 || cidx === 0, size: 20,
                        color: idx === 0 ? "FFFFFF" : undefined })],
                    alignment: docx.AlignmentType.LEFT
                })],
                width: { size: cidx === 0 ? 25 : 75, type: WidthType.PERCENTAGE },
                shading: idx === 0 ? { fill: "003366" } : (cidx === 0 ? { fill: "E8E8E8" } : undefined)
            }))
        }))
    });
}

