/**
 * 生成导入模板（v3.45.9 优先使用房源维度物资底表数据）
 * 
 * 【v3.45.9更新】处理模式：
 * - 单文件模式：直接使用该文件的所有资产，按字段映射规则生成模板
 * - 多文件模式：拼接去重后，按字段映射规则生成模板
 * 
 * 数据来源优先级：
 * 1. 已代扣金额：优先使用房源维度表的"贝壳已租金代扣金额合计"
 * 2. 资产起租日：优先使用房源维度表的"首次付款日期"
 * 3. 代扣总期数：使用房源维度表的"预计代扣周期"
 * 4. 剩余代扣期数：使用房源维度表的"当前剩余期数"
 * 5. 每期代扣金额：优先使用房源维度表的"每期应付款金额"
 * 6. 代扣数据仅作为补充（可选）
 */
function generateImportTemplate() {
    const isSingleFileMode = DataProcessState.assetFiles.length === 1;
    const hasRentalData = DataProcessState.rentalData && DataProcessState.rentalData.length > 0;
    
    console.log(`【数据加工 v3.45.9】开始生成导入模板 - ${isSingleFileMode ? '单文件模式' : '多文件合并模式'}${hasRentalData ? '（含代扣数据）' : '（仅房源底表）'}`);
    
    // 只需要房源底表，代扣数据为可选
    if (!DataProcessState.assetData || DataProcessState.assetData.length === 0) {
        showToast('请先上传房源维度物资底表', 'error');
        return;
    }
    
    const modeText = isSingleFileMode ? '单文件全量入池' : '多文件合并';
    showToast(`正在生成导入模板（${modeText}${hasRentalData ? '，含代扣数据补充' : ''}）...`, 'info');
    
    // 清空之前的数据质量记录
    DataProcessState.incompleteRecords = [];
    DataProcessState.missingRentalRecords = [];
    DataProcessState.disqualifiedRecords = [];
    DataProcessState.longTermRecords = [];  // 🆕 剩余期数>36期的记录
    
    try {
        // 1. 找出字段名称（支持多种可能的命名，忽略空格和特殊字符）
        const findField = (headers, possibleNames) => {
            // 防御性检查
            if (!headers || !Array.isArray(headers) || headers.length === 0) {
                console.warn('【数据加工】findField: headers为空或无效', headers);
                return null;
            }
            
            // 清理函数：去除空格、特殊字符、转小写
            const cleanStr = (s) => String(s).trim().replace(/[\s\-_\.\/\\]+/g, '').toLowerCase();
            
            // 1. 先尝试精确匹配
            for (const name of possibleNames) {
                const found = headers.find(h => String(h).trim() === name);
                if (found) return found;
            }
            
            // 2. 尝试包含匹配
            for (const name of possibleNames) {
                const found = headers.find(h => {
                    const hClean = String(h).trim();
                    return hClean.includes(name) || name.includes(hClean);
                });
                if (found) return found;
            }
            
            // 3. 尝试去除空格和特殊字符后匹配
            for (const name of possibleNames) {
                const nameClean = cleanStr(name);
                const found = headers.find(h => {
                    const hClean = cleanStr(h);
                    return hClean.includes(nameClean) || nameClean.includes(hClean);
                });
                if (found) return found;
            }
            
            // 4. 尝试模糊匹配（检查是否包含关键词）
            const keywords = ['房源', '编码', '编号', 'id', 'ID', '标识'];
            for (const keyword of keywords) {
                if (possibleNames.some(n => n.includes(keyword) || keyword.includes(n))) {
                    const found = headers.find(h => cleanStr(h).includes(cleanStr(keyword)));
                    if (found) {
                        console.log('【数据加工】模糊匹配到字段:', found, '(通过关键词:', keyword, ')');
                        return found;
                    }
                }
            }
            
            return null;
        };
        
        // 检查表头是否有效
        console.log('【数据加工 v3.45.9】房源底表表头:', DataProcessState.assetHeaders);
        console.log('【数据加工 v3.45.9】代扣数据表头:', DataProcessState.rentalHeaders);
        
        // ========================================
        // 【v3.45.9】房源维度物资底表字段映射（优先数据源）
        // ========================================
        // 扩展房源编码的可能字段名（支持更多变体）
        const assetIdField = findField(DataProcessState.assetHeaders, [
            // 标准名称
            '房源编码', '房源ID', '房源编号', '资产编号',
            // 变体
            '房源id', '房源 编码', '房源_编码', '房源-编码',
            // 简化名称
            '编码', '房源', '物资编码', '物资编号',
            // 英文变体
            'ID', 'id', 'Id', 'assetId', 'asset_id', 'houseId', 'house_id',
            // 其他可能的名称
            '资产ID', '资产id', '唯一标识', '标识码', '序号', '编号',
            '房屋编码', '房屋编号', '房屋ID', '物业编码', '物业编号'
        ]);
        const brandField = findField(DataProcessState.assetHeaders, ['品牌', '品牌名称']);
        const totalAmountField = findField(DataProcessState.assetHeaders, ['MIN金融机构可转让', '可转让金额', '总代扣金额', '总金额']);
        
        // 【v3.45.8新增】房源维度表优先字段
        const assetDeductedField = findField(DataProcessState.assetHeaders, ['贝壳已租金代扣金额合计', '已代扣金额合计', '累计代扣金额']);
        const assetStartDateField = findField(DataProcessState.assetHeaders, ['首次付款日期', '首次付款日', '首付日期', '起租日期']);
        // 【v3.45.10修改】代扣总期数优先匹配"预计代扣周期-当前剩余资金"
        const assetTotalPeriodsField = findField(DataProcessState.assetHeaders, ['预计代扣周期-当前剩余资金', '预计代扣周期', '总代扣期数', '代扣总期数']);
        const assetRemainingPeriodsField = findField(DataProcessState.assetHeaders, ['当前剩余期数', '剩余期数', '剩余代扣期数', '预计代扣周期-当前剩余资金']);
        const assetPeriodAmountField = findField(DataProcessState.assetHeaders, ['每期应付款金额', '每期代扣金额', '月付金额', '每期金额']);
        // 【v3.45.10新增】租金代扣比例字段（扩展匹配列表）
        const assetRentDeductRatioField = findField(DataProcessState.assetHeaders, [
            '租金代扣比例', '代扣比例', '总代扣比例', '总代扣比例(%)', 
            '代扣总比例', '代扣总比例(%)', '租金代扣比例(%)', '比例',
            '代扣比例(%)', '扣款比例', '扣款比例(%)'
        ]);
        console.log('【数据加工 v3.45.10】租金代扣比例字段:', assetRentDeductRatioField);
        
        // 旧字段（兼容）
        const periodsField = findField(DataProcessState.assetHeaders, ['预计代扣周期-初始', '预计代扣周期', '代扣周期', '总期数']);
        
        // ========================================
        // 代扣出租数据字段映射（补充数据源）
        // ========================================
        const rentalIdField = findField(DataProcessState.rentalHeaders, ['房源编码', '房源ID', '房源编号', '资产编号']);
        const deductedField = findField(DataProcessState.rentalHeaders, ['已代扣金额', '已扣金额', '累计代扣']);
        const startDateField = findField(DataProcessState.rentalHeaders, ['首次支付时间', '首次支付日', '首次代扣日', '起租日', '开始日期', '支付日期', '首付日']);
        const ratioField = findField(DataProcessState.rentalHeaders, ['代扣总比例', '代扣比例', '比例']);
        const priceField = findField(DataProcessState.rentalHeaders, ['出房价格', '租金', '月租']);
        const collectPriceField = findField(DataProcessState.rentalHeaders, ['收房价格', '收房租金', '收房月租', '收租价格']);
        
        // 入池条件校验字段
        const contractStatusField = findField(DataProcessState.rentalHeaders, ['出房合同状态', '合同状态', '签约状态', '出房状态']);
        const rentalTotalAmountField = findField(DataProcessState.rentalHeaders, ['代扣总金额', '总代扣金额', '代扣金额合计']);
        
        // 签约年限字段（用于补全代扣总期数）
        const contractYearsField = findField(DataProcessState.rentalHeaders, ['签约年限', '合同年限', '租约年限', '签约期限', '合同期限']);
        
        console.log('【数据加工】v3.45.8 房源维度表优先字段:', {
            assetDeductedField,
            assetStartDateField,
            assetTotalPeriodsField,
            assetRemainingPeriodsField,
            assetPeriodAmountField
        });
        
        // 调试：输出代扣数据的表头，帮助定位字段
        console.log('【数据加工】房源底表表头:', DataProcessState.assetHeaders);
        console.log('【数据加工】代扣数据表头:', DataProcessState.rentalHeaders);
        console.log('【数据加工】找到的首次支付日字段:', startDateField);
        
        // 如果没有找到首次支付日字段，提示用户
        if (!startDateField) {
            console.warn('【数据加工】⚠️ 未找到首次支付日字段！代扣数据表头为:', DataProcessState.rentalHeaders);
            showToast('注意：未找到"首次支付日"字段，资产起租日将为空', 'warning');
        }
        
        // 缓存字段映射
        DataProcessState.fieldMapping = {
            assetIdField, brandField, totalAmountField, periodsField,
            rentalIdField, deductedField, startDateField, ratioField, priceField,
            collectPriceField,  // 🆕 收房价格字段
            contractStatusField, rentalTotalAmountField,  // 🆕 入池校验字段
            contractYearsField  // 🆕 签约年限字段
        };
        
        console.log('【数据加工】完整字段映射:', DataProcessState.fieldMapping);
        console.log('【数据加工】入池校验字段 - 出房合同状态:', contractStatusField, '代扣总金额:', rentalTotalAmountField);
        
        // 输出第一条代扣数据记录，帮助调试
        if (hasRentalData && DataProcessState.rentalData.length > 0) {
            console.log('【数据加工】第一条代扣数据样例:', DataProcessState.rentalData[0]);
        } else {
            console.log('【数据加工 v3.45.9】无代扣数据，仅使用房源维度物资底表');
        }
        
        // 2. 建立房源编码索引
        const assetMap = new Map();
        
        // 检查关键字段是否找到，如果没找到则尝试智能匹配
        let finalAssetIdField = assetIdField;
        
        if (!finalAssetIdField) {
            const headerList = DataProcessState.assetHeaders.slice(0, 15).join(', ');
            console.warn('【数据加工】⚠️ 未找到标准房源编码字段');
            console.warn('【数据加工】当前表头（前15列）:', headerList);
            console.log('【数据加工】全部表头:', DataProcessState.assetHeaders);
            
            // 智能匹配：查找包含"编码"、"编号"、"ID"的字段
            const smartMatch = DataProcessState.assetHeaders.find(h => {
                const hLower = String(h).toLowerCase();
                return hLower.includes('编码') || hLower.includes('编号') || 
                       hLower.includes('id') || hLower.includes('房源');
            });
            
            if (smartMatch) {
                finalAssetIdField = smartMatch;
                console.log('【数据加工】✅ 智能匹配到房源编码字段:', finalAssetIdField);
                showToast(`已自动识别"${finalAssetIdField}"作为房源编码字段`, 'info');
            } else {
                // 最后的后备：使用第一列
                finalAssetIdField = DataProcessState.assetHeaders[0];
                console.warn('【数据加工】⚠️ 使用第一列作为房源编码:', finalAssetIdField);
                showToast(`未找到房源编码字段，已使用第一列"${finalAssetIdField}"作为标识`, 'warning');
            }
        }
        
        console.log('【数据加工】✅ 资产编号使用房源编码字段:', finalAssetIdField);
        console.log('【数据加工】资产数据条数:', DataProcessState.assetData.length);
        
        // 输出第一条数据的房源编码示例
        if (DataProcessState.assetData.length > 0) {
            const firstRow = DataProcessState.assetData[0];
            console.log('【数据加工】首条资产房源编码:', firstRow[finalAssetIdField]);
        }
        
        DataProcessState.assetData.forEach((row, idx) => {
            const id = row[finalAssetIdField];
            if (id) {
                assetMap.set(String(id).trim(), row);
            } else if (idx < 3) {
                // 输出前3条没有ID的记录便于调试
                console.warn('【数据加工】⚠️ 记录无房源编码:', idx, row);
            }
        });
        
        console.log('【数据加工】建立房源索引完成，有效记录:', assetMap.size);
        
        // 建立代扣数据索引（如果有的话）
        const rentalMap = new Map();          // 合并后的数据（用于数据处理）
        const rentalMapAllRecords = new Map(); // 🆕 v3.45.35: 所有原始记录（用于导出）
        
        if (hasRentalData) {
            DataProcessState.rentalData.forEach(row => {
                const id = row[rentalIdField];
                if (id) {
                    const key = String(id).trim();
                    
                    // 🆕 v3.45.35: 存储所有原始记录
                    if (!rentalMapAllRecords.has(key)) {
                        rentalMapAllRecords.set(key, []);
                    }
                    rentalMapAllRecords.get(key).push({ ...row });
                    
                    // 如果有多条记录，需要合并处理
                    if (rentalMap.has(key)) {
                        const existing = rentalMap.get(key);
                        
                        // 1. 累加已代扣金额
                        const existingDeducted = parseFloat(existing[deductedField]) || 0;
                        const newDeducted = parseFloat(row[deductedField]) || 0;
                        existing[deductedField] = existingDeducted + newDeducted;
                        
                        // 2. 使用最早的首次支付时间
                        if (startDateField && row[startDateField]) {
                            const existingDate = Utils.parseDate(existing[startDateField]);
                            const newDate = Utils.parseDate(row[startDateField]);
                            if (newDate && (!existingDate || newDate < existingDate)) {
                                existing[startDateField] = row[startDateField];
                            }
                        }
                        
                        // 3. 🆕 代扣总金额：如果当前记录有值而之前没有，则使用当前值
                        if (rentalTotalAmountField) {
                            const existingTotal = existing[rentalTotalAmountField];
                            const newTotal = row[rentalTotalAmountField];
                            const existingHasValue = existingTotal && String(existingTotal).trim() !== '' && parseFloat(existingTotal) > 0;
                            const newHasValue = newTotal && String(newTotal).trim() !== '' && parseFloat(newTotal) > 0;
                            if (!existingHasValue && newHasValue) {
                                existing[rentalTotalAmountField] = newTotal;
                            }
                        }
                        
                        // 4. 🆕 出房合同状态：如果任一条记录是"已签约"，则标记为已签约
                        if (contractStatusField) {
                            const existingStatus = String(existing[contractStatusField] || '').trim();
                            const newStatus = String(row[contractStatusField] || '').trim();
                            if (newStatus === '已签约' && existingStatus !== '已签约') {
                                existing[contractStatusField] = '已签约';
                            }
                        }
                        
                        // 5. 🆕 收房价格：选取不为0的值
                        if (collectPriceField) {
                            const existingPrice = parseFloat(existing[collectPriceField]) || 0;
                            const newPrice = parseFloat(row[collectPriceField]) || 0;
                            if (existingPrice === 0 && newPrice > 0) {
                                existing[collectPriceField] = newPrice;
                            }
                        }
                        
                        // 6. 🆕 代扣总比例：选取0-1之间的有效值
                        if (ratioField) {
                            const existingRatio = parseFloat(existing[ratioField]) || 0;
                            const newRatio = parseFloat(row[ratioField]) || 0;
                            const existingValid = existingRatio > 0 && existingRatio <= 1;
                            const newValid = newRatio > 0 && newRatio <= 1;
                            if (!existingValid && newValid) {
                                existing[ratioField] = newRatio;
                            }
                        }
                        
                        // 7. 🆕 出房价格：选取不为0的值（用于计算每期代扣金额的备选）
                        if (priceField) {
                            const existingOutPrice = parseFloat(existing[priceField]) || 0;
                            const newOutPrice = parseFloat(row[priceField]) || 0;
                            if (existingOutPrice === 0 && newOutPrice > 0) {
                                existing[priceField] = newOutPrice;
                            }
                        }
                    } else {
                        rentalMap.set(key, { ...row });
                    }
                }
            });
        }
        
        // 3. 遍历房源底表生成数据
        // 【v3.45.9】所有资产都入池，房源维度表数据优先，代扣数据仅作为补充
        // - 单文件：全部资产入池
        // - 多文件：合并去重后全部入池
        const generatedData = [];
        let matchedCount = 0;
        
        console.log('【数据加工 v3.45.9】开始生成模板数据，资产数:', assetMap.size, '代扣数据:', rentalMap.size);
        
        if (assetMap.size === 0) {
            console.error('【数据加工】❌ 没有有效的资产数据！');
            showToast('错误：没有有效的资产数据，请检查文件内容', 'error');
            return;
        }
        
        assetMap.forEach((assetRow, assetId) => {
            const rentalRow = rentalMap.get(assetId);  // 可能为 null（没有代扣数据或未匹配时）
            const brand = assetRow[brandField] || '';
            const assetType = brand.includes('舒里') || brand.includes('简逸') ? '局装' : '整装';
            
            // ========================================
            // 【v3.45.44】总代扣金额：仅使用房源表MIN金融机构可转让金额，不做补充
            // ========================================
            let totalDeduction = parseFloat(assetRow[totalAmountField]) || 0;
            let totalDeductionSource = totalDeduction > 0 ? '房源维度表' : '';
            // 🆕 v3.45.44: 不再从代扣表补充总代扣金额
            
            const totalPeriods = parseInt(assetRow[periodsField]) || 0;
            
            // 统计匹配数量（有代扣数据匹配的）
            if (rentalRow) {
                matchedCount++;
            }
            
            // ========================================
            // 【v3.45.42】入池条件校验①：总代扣金额 > 0
            // ========================================
            if (totalDeduction <= 0) {
                DataProcessState.disqualifiedRecords.push({
                    房源编码: assetId,
                    品牌: brand,
                    资产类型: assetType,
                    总代扣金额: totalDeduction,
                    代扣记录数: rentalMapAllRecords.get(assetId)?.length || 0,
                    代扣出房价格: null,
                    代扣收房价格: null,
                    不符合原因: '总代扣金额为0或缺失',
                    来源文件: assetRow._sourceFile || '未知',
                    _rawAsset: assetRow,
                    _rawRentals: rentalMapAllRecords.get(assetId) || [],
                    _rawRental: rentalRow
                });
                console.log(`【数据加工 v3.45.42】房源${assetId}不符合入池条件：总代扣金额为0或缺失`);
                return; // 跳过该资产，不加入generatedData
            }
            
            // ========================================
            // 【v3.45.41】入池条件校验②：代扣表中所有记录的收房和出房价格同时为null则不符合入池
            // 需要检查该房源下的所有代扣记录，而不仅仅是合并后的单条记录
            // ========================================
            const allRentalRecords = rentalMapAllRecords.get(assetId) || [];
            
            if (allRentalRecords.length > 0) {
                // 🆕 v3.45.45: 检查所有代扣记录的收房和出房价格
                // 空值定义：null、undefined、''、0、字符串"null"（Excel中常见）
                let allRecordsHaveBothEmpty = true;  // 假设所有记录都是收房出房同时为空
                let emptyRecordCount = 0;
                let validRecordCount = 0;
                
                // 🆕 v3.45.45: 判断是否为空值的辅助函数（包括字符串"null"）
                const isEmptyValue = (val) => {
                    if (val === null || val === undefined || val === '') return true;
                    if (typeof val === 'string') {
                        const trimmed = val.trim().toLowerCase();
                        if (trimmed === 'null' || trimmed === 'undefined' || trimmed === '') return true;
                    }
                    if (parseFloat(val) === 0) return true;
                    return false;
                };
                
                const recordDetails = allRentalRecords.map((record, idx) => {
                    const outPrice = priceField ? record[priceField] : null;
                    const collectPrice = collectPriceField ? record[collectPriceField] : null;
                    
                    // 🆕 v3.45.45: 使用新的空值判断函数
                    const outPriceEmpty = isEmptyValue(outPrice);
                    const collectPriceEmpty = isEmptyValue(collectPrice);
                    
                    const bothEmpty = outPriceEmpty && collectPriceEmpty;
                    
                    if (bothEmpty) {
                        emptyRecordCount++;
                    } else {
                        validRecordCount++;
                        allRecordsHaveBothEmpty = false;  // 只要有一条记录不是同时为空，就不算不符合入池
                    }
                    
                    return {
                        序号: idx + 1,
                        出房价格: outPrice,
                        收房价格: collectPrice,
                        出房为空: outPriceEmpty,
                        收房为空: collectPriceEmpty,
                        同时为空: bothEmpty
                    };
                });
                
                // 只有当所有代扣记录的收房和出房价格都同时为空时，才判定为不符合入池（已解约）
                if (allRecordsHaveBothEmpty) {
                    // 取第一条记录的价格用于展示
                    const firstRecord = allRentalRecords[0];
                    const rentalOutPrice = priceField ? firstRecord[priceField] : null;
                    const rentalCollectPrice = collectPriceField ? firstRecord[collectPriceField] : null;
                    
                    // 记录到不符合入池条件
                    DataProcessState.disqualifiedRecords.push({
                        房源编码: assetId,
                        品牌: brand,
                        资产类型: assetType,
                        总代扣金额: totalDeduction,
                        代扣记录数: allRentalRecords.length,
                        代扣出房价格: rentalOutPrice,
                        代扣收房价格: rentalCollectPrice,
                        不符合原因: '已解约，无法入池（收房和出房价格同时为null）',  // 🆕 v3.45.45: 更新原因描述
                        来源文件: assetRow._sourceFile || '未知',
                        _rawAsset: assetRow,
                        _rawRentals: allRentalRecords,
                        _rawRental: rentalRow,
                        _recordDetails: recordDetails
                    });
                    console.log(`【数据加工 v3.45.45】房源${assetId}不符合入池条件：已解约（收房和出房价格同时为null）`);
                    return; // 跳过该资产，不加入generatedData
                }
            }
            
            // ========================================
            // 【v3.45.43】已代扣金额：仅使用房源维度表，不从代扣表补充
            // ========================================
            
            // 1. 已代扣金额：仅使用房源维度表的"贝壳已租金代扣金额合计"，房源表为空则显示为空
            let deductedAmount = 0;
            let deductedAmountSource = '';
            if (assetDeductedField && assetRow[assetDeductedField]) {
                deductedAmount = parseFloat(assetRow[assetDeductedField]) || 0;
                deductedAmountSource = '房源维度表';
            }
            // 🆕 v3.45.43: 不再从代扣表补充已代扣金额，房源表为空则保持为0
            
            // 2. 资产起租日：仅使用房源维度表的"首次付款日期"，不做补充
            // 🆕 v3.45.44: 不再从代扣表补充资产起租日
            let leaseStartDate = '';
            let leaseStartDateSource = '';
            if (assetStartDateField && assetRow[assetStartDateField]) {
                leaseStartDate = parseExcelDate(assetRow[assetStartDateField]);
                leaseStartDateSource = '房源维度表';
            }
            
            // 调试输出（第一条记录）
            if (generatedData.length === 0) {
                console.log('【数据加工 v3.45.10】首条记录数据来源调试:', {
                    总代扣金额: { value: totalDeduction, source: totalDeductionSource },
                    已代扣金额: { value: deductedAmount, source: deductedAmountSource },
                    资产起租日: { value: leaseStartDate, source: leaseStartDateSource }
                });
            }
            
            // ========================================
            // 3. 代扣总期数：仅使用房源表字段，不做补充
            // 🆕 v3.45.44: 不再从代扣表补充，不再按规则补录
            // ========================================
            let calculatedTotalPeriods = 0;
            let totalPeriodsSource = '';
            const assetTotalPeriods = parseInt(assetRow[assetTotalPeriodsField]) || 0;
            const assetRemainingPeriods = parseInt(assetRow[assetRemainingPeriodsField]) || 0;
            
            if (assetTotalPeriods > 0) {
                // 使用预计代扣周期作为总期数
                calculatedTotalPeriods = assetTotalPeriods;
                totalPeriodsSource = '房源维度表(预计代扣周期)';
            } else if (totalPeriods > 0) {
                calculatedTotalPeriods = totalPeriods;
                totalPeriodsSource = '房源维度表(旧字段)';
            }
            // 🆕 v3.45.44: 如果房源表没有代扣期数，则保持为0，不做补录
            
            // 剩余代扣期数：仅使用房源表字段，不做补充
            // 🆕 v3.45.44: 不再使用 calculatedTotalPeriods 作为默认值
            const remainingPeriods = assetRemainingPeriods;
            
            // ========================================
            // 4. 每期代扣金额：仅使用房源表字段，不做补充
            // 🆕 v3.45.44: 不再从代扣表获取，不再计算补充
            // ========================================
            let periodDeduction = 0;
            let periodDeductionSource = '';
            let periodRatio = 0;  // 每期比例（用于提示）
            
            // 🆕 v3.45.44: 仅使用房源维度表的"每期应付款金额"
            if (assetPeriodAmountField && assetRow[assetPeriodAmountField]) {
                periodDeduction = parseFloat(assetRow[assetPeriodAmountField]) || 0;
                periodDeductionSource = '房源维度表(每期应付款金额)';
            }
            // 如果房源表没有每期代扣金额，则保持为0，不做补充
            
            // 输出首条记录的完整数据来源
            if (generatedData.length === 0) {
                console.log('【数据加工 v3.45.9】首条记录完整数据来源:', {
                    代扣总期数: { value: calculatedTotalPeriods, source: totalPeriodsSource, 剩余期数: remainingPeriods },
                    每期代扣金额: { value: periodDeduction, source: periodDeductionSource, 每期比例: periodRatio }
                });
            }
            
            // 检查是否数据不全，并记录具体缺失来源
            // 🆕 v3.45.44: 所有字段仅从房源表获取，不做补充
            const missingDetails = [];
            if (!calculatedTotalPeriods) {
                missingDetails.push({ field: '代扣总期数', source: '房源维度表', sourceField: assetTotalPeriodsField || '预计代扣周期-当前剩余资金' });
            }
            if (!periodDeduction) {
                missingDetails.push({ field: '每期代扣金额', source: '房源维度表', sourceField: assetPeriodAmountField || '每期应付款金额' });
            }
            if (!deductedAmount && deductedAmount !== 0) {
                missingDetails.push({ field: '已代扣金额', source: '房源维度表', sourceField: assetDeductedField || '贝壳已租金代扣金额合计' });
            }
            if (!leaseStartDate || leaseStartDate === '') {
                missingDetails.push({ field: '资产起租日', source: '房源维度表', sourceField: assetStartDateField || '首次付款日期' });
            }
            
            // 【v3.45.10新增】获取租金代扣比例（从房源信息表）
            let rentDeductRatio = '';
            if (assetRentDeductRatioField && assetRow[assetRentDeductRatioField] !== undefined && assetRow[assetRentDeductRatioField] !== '') {
                rentDeductRatio = assetRow[assetRentDeductRatioField];
            } else {
                // 如果通过预设字段名找不到，尝试在原始数据中搜索包含"比例"的字段
                const assetKeys = Object.keys(assetRow);
                for (const key of assetKeys) {
                    if ((key.includes('代扣') && key.includes('比例')) || key === '比例' || key.includes('租金代扣比例')) {
                        const val = assetRow[key];
                        if (val !== undefined && val !== null && val !== '') {
                            rentDeductRatio = val;
                            if (generatedData.length === 0) {
                                console.log('【数据加工 v3.45.10】找到租金代扣比例字段:', key, '值:', val);
                            }
                            break;
                        }
                    }
                }
            }
            
            // 首条记录输出调试信息
            if (generatedData.length === 0) {
                console.log('【数据加工 v3.45.10】首条记录租金代扣比例:', {
                    字段名: assetRentDeductRatioField,
                    值: rentDeductRatio,
                    原始数据keys: Object.keys(assetRow).filter(k => k.includes('比例'))
                });
            }
            
            // 计算资产折扣率：整装/局装均使用统一配置折扣率
            const isPartialAssetType = assetType === '局装';
            const discountRate = getUnifiedAssetDiscountRate(assetType);
            const discountLabel = isPartialAssetType ? '局装统一折扣' : '整装统一折扣';
            const poolContribution = totalDeduction * (discountRate / 100);
            
            // 🆕 v3.45.35: 获取该房源的所有代扣记录（使用之前已获取的 allRentalRecords）
            // 注意：allRentalRecords 已在入池条件检查时声明，这里直接使用
            
            const record = {
                asset_id: assetId,
                asset_type: assetType,
                total_deduction: totalDeduction,
                deducted_amount: deductedAmount,
                lease_start_date: leaseStartDate,
                total_periods: calculatedTotalPeriods || 12,
                period_deduction: periodDeduction,
                remaining_periods: remainingPeriods,  // 🆕 剩余代扣期数
                period_ratio: periodRatio,            // 🆕 每期比例
                rent_deduct_ratio: rentDeductRatio,   // 🆕 v3.45.10: 租金代扣比例
                discount_rate: discountRate,          // 🆕 v3.45.32: 折扣率
                discount_label: discountLabel,        // 🆕 v3.45.32: 折扣标签
                pool_contribution: poolContribution,  // 🆕 v3.45.32: 入池金额
                _brand: brand,
                _deductedAmountSource: deductedAmountSource,    // 数据来源追踪
                _leaseStartDateSource: leaseStartDateSource,
                _totalPeriodsSource: totalPeriodsSource,
                _periodDeductionSource: periodDeductionSource,
                _sourceFile: assetRow._sourceFile || '未知',
                _isIncomplete: missingDetails.length > 0,
                _missingFields: missingDetails.map(m => m.field),
                _rawAsset: assetRow,
                _rawRental: rentalRow || null,         // 保留合并后的数据（兼容）
                _rawRentals: allRentalRecords          // 🆕 v3.45.35: 所有原始代扣记录
            };
            
            generatedData.push(record);
                
            // 🆕 v3.45.9: 检查剩余代扣期数是否>36期
            if (remainingPeriods > 36) {
                DataProcessState.longTermRecords.push({
                    房源编码: assetId,
                    品牌: brand,
                    资产类型: assetType,
                    总代扣金额: totalDeduction,
                    已代扣金额: deductedAmount,
                    剩余期数: remainingPeriods,
                    每期代扣金额: periodDeduction,
                    每期比例: periodRatio,
                    来源文件: assetRow._sourceFile || '未知',
                    _index: generatedData.length - 1,
                    _rawAsset: assetRow,
                    _rawRental: rentalRow,
                    _rawRentals: allRentalRecords,  // 🆕 v3.45.35: 所有代扣记录
                    _record: record
                });
            }
            
            // 记录数据不全的记录
            if (missingDetails.length > 0) {
                // 🆕 判断是否仅缺代扣总期数（可使用签约年限补全）
                const onlyMissingPeriods = missingDetails.length === 1 && missingDetails[0].field === '代扣总期数';
                
                // 🆕 判断是否仅缺每期代扣金额（可使用收房价格×代扣总比例补全）
                const onlyMissingPeriodDeduction = missingDetails.length === 1 && missingDetails[0].field === '每期代扣金额';
                
                // 🆕 获取签约年限（用于补全代扣总期数）- 需检查rentalRow
                let contractYears = null;
                if (rentalRow && contractYearsField && rentalRow[contractYearsField]) {
                    contractYears = parseFloat(rentalRow[contractYearsField]) || null;
                }
                
                // 🆕 获取收房价格和代扣总比例（用于补全每期代扣金额）
                let collectPrice = null;
                let deductRatio = null;
                let calculatedPeriodDeduction = null;
                
                if (rentalRow) {
                    // 优先使用收房价格
                    if (collectPriceField && rentalRow[collectPriceField]) {
                        collectPrice = parseFloat(rentalRow[collectPriceField]) || null;
                    }
                    // 如果没有收房价格，尝试使用出房价格
                    if (!collectPrice && priceField && rentalRow[priceField]) {
                        collectPrice = parseFloat(rentalRow[priceField]) || null;
                    }
                    
                    // 获取代扣总比例（必须是0-1之间）
                    if (ratioField && rentalRow[ratioField]) {
                        const ratio = parseFloat(rentalRow[ratioField]) || 0;
                        if (ratio > 0 && ratio <= 1) {
                            deductRatio = ratio;
                        }
                    }
                }
                
                // 计算每期代扣金额
                if (collectPrice && collectPrice > 0 && deductRatio && deductRatio > 0) {
                    calculatedPeriodDeduction = collectPrice * deductRatio;
                }
                
                DataProcessState.incompleteRecords.push({
                    房源编码: assetId,
                    品牌: brand,
                    资产类型: assetType,
                    总代扣金额: totalDeduction,
                    来源文件: assetRow._sourceFile || '未知',
                    缺失详情: missingDetails,
                    缺失字段: missingDetails.map(m => `${m.field}(${m.source})`).join(', '),
                    _index: generatedData.length - 1,
                    _rawAsset: assetRow,
                    _rawRental: rentalRow,
                    // 🆕 代扣总期数补全相关
                    _onlyMissingPeriods: onlyMissingPeriods,
                    _contractYears: contractYears,
                    _calculatedPeriods: contractYears ? Math.round((contractYears / 2) * 12) : null,
                    // 🆕 每期代扣金额补全相关
                    _onlyMissingPeriodDeduction: onlyMissingPeriodDeduction,
                    _collectPrice: collectPrice,
                    _deductRatio: deductRatio,
                    _calculatedPeriodDeduction: calculatedPeriodDeduction
                });
            }
            
            // v3.45.9: 如果有代扣数据但未匹配，记录到缺失代扣信息列表（仅在有代扣数据时）
            if (hasRentalData && !rentalRow) {
                DataProcessState.missingRentalRecords.push({
                    房源编码: assetId,
                    品牌: brand,
                    资产类型: assetType,
                    总代扣金额: totalDeduction,
                    代扣总期数: calculatedTotalPeriods || '',
                    _rawAsset: assetRow
                });
            }
        });
        
        // 按资产类型和总金额排序
        generatedData.sort((a, b) => {
            if (a.asset_type !== b.asset_type) {
                return a.asset_type === '整装' ? -1 : 1;
            }
            return b.total_deduction - a.total_deduction;
        });
        
        DataProcessState.generatedData = generatedData;
        DataProcessState.currentPage = 1;
        
        console.log('【数据加工 v3.45.9】生成完成，准备显示结果');
        console.log('【数据加工 v3.45.9】生成数据条数:', generatedData.length);
        console.log('【数据加工 v3.45.9】长期资产条数:', DataProcessState.longTermRecords.length);
        console.log('【数据加工 v3.45.9】不完整记录条数:', DataProcessState.incompleteRecords.length);
        
        // 4. 显示结果（扣除不符合入池条件的记录）
        const qualifiedCount = generatedData.length;
        const disqualifiedCount = DataProcessState.disqualifiedRecords.length;
        
        const matchedCountEl = document.getElementById('matchedCount');
        const unmatchedCountEl = document.getElementById('unmatchedCount');
        const resultSection = document.getElementById('generatedResultSection');
        
        console.log('【数据加工 v3.45.9】UI元素检查:', {
            matchedCount: !!matchedCountEl,
            unmatchedCount: !!unmatchedCountEl,
            resultSection: !!resultSection
        });
        
        if (matchedCountEl) matchedCountEl.textContent = qualifiedCount;
        if (unmatchedCountEl) unmatchedCountEl.textContent = DataProcessState.missingRentalRecords.length;
        if (resultSection) {
            resultSection.style.display = 'block';
            console.log('【数据加工 v3.45.9】✅ 结果区域已显示');
        } else {
            console.error('【数据加工 v3.45.9】❌ 找不到结果区域元素 generatedResultSection');
        }
        
        // 渲染主表格
        console.log('【数据加工 v3.45.9】开始渲染主表格...');
        renderGeneratedDataTable();
        console.log('【数据加工 v3.45.9】主表格渲染完成');
        
        // 🆕 渲染数据质量汇总表格（包含超期资产）
        renderDataQualitySummary();
        
        // 🆕 v3.45.30 执行数据交叉校验
        performDataCrossValidation();
        
        // 🆕 更新可导出数量（需要在渲染数据质量汇总后计算）
        updateExportableCount();
        
        // 更新目标模型选择器
        updateTargetModelSelector();
        
        const exportableCount = getExportableData().length;
        const longTermCount = DataProcessState.longTermRecords.length;
        
        // 【v3.45.9】生成提示信息
        const modeLabel = isSingleFileMode ? '单文件全量入池' : '多文件合并去重';
        let summaryMsg = `【${modeLabel}】共 ${qualifiedCount} 条资产`;
        
        if (hasRentalData) {
            summaryMsg += `，代扣匹配 ${matchedCount} 条`;
        }
        if (DataProcessState.incompleteRecords.length > 0) {
            summaryMsg += `，数据不全 ${DataProcessState.incompleteRecords.length} 条`;
        }
        if (longTermCount > 0) {
            summaryMsg += `，剩余期数>36期 ${longTermCount} 条`;
        }
        summaryMsg += `，可导出/导入 ${exportableCount} 条`;
        
        showToast(`模板生成成功！${summaryMsg}`, 'success');
        
        console.log('【数据加工 v3.45.9】生成结果:', {
            mode: modeLabel,
            totalAssets: qualifiedCount,
            matchedWithRental: matchedCount,
            duplicateRecords: DataProcessState.duplicateRecords.length,
            incompleteRecords: DataProcessState.incompleteRecords.length,
            longTermRecords: longTermCount,
            exportableCount
        });
        
    } catch (error) {
        console.error('生成模板失败:', error);
        showToast('生成模板失败: ' + error.message, 'error');
    }
}

/**
 * 解析Excel日期（支持数字序列号和多种字符串格式）
 */
function parseExcelDate(dateValue) {
    if (!dateValue && dateValue !== 0) return '';
    
    try {
        // Excel日期序列号（数字）
        if (typeof dateValue === 'number') {
            // Excel日期序列号转换 (Excel以1900-01-01为基准)
            const excelDate = new Date((dateValue - 25569) * 86400 * 1000);
            if (!isNaN(excelDate.getTime())) {
                return excelDate.toISOString().split('T')[0];
            }
        }
        
        // 字符串日期
        const strValue = String(dateValue).trim();
        if (!strValue) return '';
        
        // 尝试多种格式解析
        let parsed = null;
        
        // 1. 尝试直接解析 ISO 格式 (2024-01-15)
        if (/^\d{4}-\d{2}-\d{2}/.test(strValue)) {
            parsed = new Date(strValue);
        }
        // 2. 尝试解析中文格式 (2024年1月15日 或 2024/1/15)
        else if (/^\d{4}[年\/]\d{1,2}[月\/]\d{1,2}/.test(strValue)) {
            const match = strValue.match(/(\d{4})[年\/](\d{1,2})[月\/](\d{1,2})/);
            if (match) {
                parsed = new Date(parseInt(match[1]), parseInt(match[2]) - 1, parseInt(match[3]));
            }
        }
        // 3. 尝试解析 mm/dd/yyyy 或 dd/mm/yyyy
        else if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(strValue)) {
            const parts = strValue.split('/');
            // 假设是 mm/dd/yyyy
            parsed = new Date(parseInt(parts[2]), parseInt(parts[0]) - 1, parseInt(parts[1]));
        }
        // 4. 尝试直接使用 Date 构造函数
        else {
            parsed = new Date(strValue);
        }
        
        // 检查解析结果是否有效
        if (parsed && !isNaN(parsed.getTime())) {
            return parsed.toISOString().split('T')[0];
        }
        
        // 使用 Utils.parseDate 作为后备
        const utilsParsed = Utils.parseDate(dateValue);
        if (utilsParsed && !isNaN(utilsParsed.getTime())) {
            return utilsParsed.toISOString().split('T')[0];
        }
        
        // 无法解析，返回原始字符串
        console.warn('【数据加工】无法解析日期:', dateValue);
        return strValue;
    } catch (e) {
        console.error('【数据加工】日期解析错误:', dateValue, e);
        return String(dateValue);
    }
}

/**
 * 渲染数据质量汇总表格
 */
function renderDataQualitySummary() {
    const summarySection = document.getElementById('dataQualitySummary');
    if (!summarySection) return;
    
    const duplicates = DataProcessState.duplicateRecords;
    const incompletes = DataProcessState.incompleteRecords;
    const missingRentals = DataProcessState.missingRentalRecords;
    const disqualified = DataProcessState.disqualifiedRecords;
    const longTermRecords = DataProcessState.longTermRecords || [];
    
    // 如果没有任何问题数据，隐藏汇总区域
    if (duplicates.length === 0 && incompletes.length === 0 && missingRentals.length === 0 && disqualified.length === 0 && longTermRecords.length === 0) {
        summarySection.style.display = 'none';
        return;
    }
    
    summarySection.style.display = 'block';
    
    // 渲染五个表格
    renderDisqualifiedRecordsTable(disqualified);  // 不符合入池条件
    renderIncompleteRecordsTable(incompletes);      // 数据信息不全
    renderDuplicateRecordsTable(duplicates);        // 重复房源信息
    renderMissingRentalRecordsTable(missingRentals); // 缺失代扣信息
    renderOvertimeRecordsTable(longTermRecords);     // 🆕 v3.45.10 超期资产
}

/**
 * 🆕 v3.45.10: 渲染超期资产表格（剩余期数>36期）
 */
function renderOvertimeRecordsTable(records) {
    const card = document.getElementById('overtimeCard');
    const countEl = document.getElementById('overtimeCount');
    const summaryEl = document.getElementById('overtimeSummary');
    const container = document.getElementById('overtimeRecordsContainer');
    
    if (!card || !container) return;
    
    if (!records || records.length === 0) {
        card.style.display = 'none';
        return;
    }
    
    card.style.display = 'block';
    if (countEl) countEl.textContent = records.length;
    
    // 计算汇总信息
    const totalAmount = records.reduce((sum, r) => sum + (r.总代扣金额 || 0), 0);
    const avgPeriods = records.reduce((sum, r) => sum + (r.剩余期数 || 0), 0) / records.length;
    
    if (summaryEl) {
        summaryEl.innerHTML = `
            <div style="display: flex; gap: 20px; margin-bottom: 10px; padding: 10px; background: rgba(255,193,7,0.1); border-radius: 4px;">
                <span><strong>涉及资产:</strong> ${records.length} 条</span>
                <span><strong>总代扣金额:</strong> ${Utils.formatCurrency(totalAmount)}</span>
                <span><strong>平均剩余期数:</strong> ${avgPeriods.toFixed(1)} 期</span>
            </div>
        `;
    }
    
    // 渲染表格
    container.innerHTML = `
        <table class="quality-table">
            <thead>
                <tr>
                    <th style="width: 40px;">
                        <input type="checkbox" id="selectAllOvertime" checked onchange="toggleAllOvertimeRecords(this.checked)">
                    </th>
                    <th>房源编码</th>
                    <th>品牌</th>
                    <th>资产类型</th>
                    <th>总代扣金额</th>
                    <th>已代扣金额</th>
                    <th>剩余期数</th>
                    <th>每期代扣金额</th>
                    <th>风险等级</th>
                </tr>
            </thead>
            <tbody>
                ${records.map((r, idx) => `
                    <tr data-index="${r._index}">
                        <td>
                            <input type="checkbox" class="overtime-checkbox" data-index="${r._index}" checked>
                        </td>
                        <td>${r.房源编码 || ''}</td>
                        <td>${r.品牌 || ''}</td>
                        <td><span class="type-badge ${r.资产类型 === '整装' ? 'full' : 'partial'}">${r.资产类型 || ''}</span></td>
                        <td class="number-cell">${Utils.formatCurrency(r.总代扣金额 || 0)}</td>
                        <td class="number-cell">${Utils.formatCurrency(r.已代扣金额 || 0)}</td>
                        <td class="number-cell text-warning"><strong>${r.剩余期数 || 0}</strong> 期</td>
                        <td class="number-cell">${Utils.formatCurrency(r.每期代扣金额 || 0)}</td>
                        <td>
                            <span class="risk-badge ${(r.剩余期数 || 0) > 60 ? 'high' : 'medium'}">
                                ${(r.剩余期数 || 0) > 60 ? '高风险(>60期)' : '中风险(>36期)'}
                            </span>
                        </td>
                    </tr>
                `).join('')}
            </tbody>
        </table>
    `;
}

/**
 * 🆕 v3.45.35: 执行数据交叉校验
 * 使用房源编码作为识别码，对比房源表与代扣表数据
 * 
 * 【v3.45.35更新】：
 * 1. 出房价格一致性校验阈值改为1000元
 * 2. 代扣总金额校验：代扣表按房源编码汇总所有订单金额
 * 3. 每期应付金额校验改用代扣表数据
 * 4. 建立代扣表多记录索引（同一房源编码可能有多条记录）
 */
function performDataCrossValidation() {
    console.log('【数据校验 v3.45.35】开始执行数据交叉校验...');
    
    const validationSection = document.getElementById('dataValidationSection');
    if (!validationSection) {
        console.warn('【数据校验】未找到校验区域元素');
        return;
    }
    
    // 检查是否有代扣数据（需要两表对比）
    const hasRentalData = DataProcessState.rentalData && DataProcessState.rentalData.length > 0;
    const hasAssetData = DataProcessState.assetData && DataProcessState.assetData.length > 0;
    
    if (!hasAssetData) {
        validationSection.style.display = 'none';
        return;
    }
    
    // 显示校验区域
    validationSection.style.display = 'block';
    
    // 重置校验结果
    DataProcessState.validationResults = {
        passRecords: [],
        priceCheckFailed: [],
        totalCheckFailed: [],
        periodCheckFailed: []
    };
    
    // 获取字段映射
    const fieldMapping = DataProcessState.fieldMapping || {};
    const assetHeaders = DataProcessState.assetHeaders || [];
    const rentalHeaders = DataProcessState.rentalHeaders || [];
    
    // 辅助函数：查找字段
    const findField = (headers, possibleNames) => {
        if (!headers || !Array.isArray(headers)) return null;
        for (const name of possibleNames) {
            const found = headers.find(h => String(h).trim() === name || String(h).includes(name));
            if (found) return found;
        }
        return null;
    };
    
    // 房源表字段
    const assetIdField = findField(assetHeaders, ['房源编码', '房源ID', '资产编号']);
    const assetPriceField = findField(assetHeaders, ['出房价格', '月租金', '租金']);
    const assetDeductedUnpaidField = findField(assetHeaders, ['已代扣未付款', '已代扣未付', '未付款金额']);
    const assetUndeductedField = findField(assetHeaders, ['贝壳未代扣', '未代扣金额', '剩余未还款']);
    const assetRatioField = findField(assetHeaders, ['租金代扣比例', '代扣比例', '总代扣比例']);
    const assetPeriodAmountField = findField(assetHeaders, ['每期应付款金额', '每期代扣金额', '月付金额']);
    const assetRemainingPeriodsField = findField(assetHeaders, ['当前剩余期数', '剩余期数', '预计代扣周期-当前剩余资金']);
    const assetBrandField = findField(assetHeaders, ['品牌', '品牌名称']);
    // 🆕 v3.45.31: 添加代扣总期数字段（用于局装折扣率判断）
    const assetTotalPeriodsField = findField(assetHeaders, ['预计代扣周期-当前剩余资金', '预计代扣周期', '总代扣期数', '代扣总期数']);
    // 🆕 v3.45.36: 已租金代扣到账合计字段（用于Check2校验）
    const assetDeductedPaidField = findField(assetHeaders, ['已租金代扣到账合计', '已代扣到账', '代扣到账合计', '已到账金额']);
    
    // 代扣表字段
    const rentalIdField = findField(rentalHeaders, ['房源编码', '房源ID', '资产编号']);
    const rentalPriceField = findField(rentalHeaders, ['出房价格', '月租金', '租金']);
    const rentalTotalDeductField = findField(rentalHeaders, ['代扣总金额', '总代扣金额', '代扣金额']);
    // 🆕 v3.45.35: 代扣表中用于Check3的每期代扣金额字段
    const rentalPeriodAmountField = findField(rentalHeaders, ['每期代扣金额', '每期应付款金额', '月付金额', '每期金额']);
    const rentalRatioField = findField(rentalHeaders, ['代扣总比例', '代扣比例', '比例']);
    // 🆕 v3.45.37: 订单号字段（用于去重，相同订单号只取一条）
    const rentalOrderIdField = findField(rentalHeaders, ['订单号', '订单编号', '订单ID', '合同编号', '合同号', '协议编号']);
    
    console.log('【数据校验 v3.45.35】字段映射:', {
        assetIdField, assetPriceField, assetDeductedUnpaidField, assetUndeductedField,
        assetRatioField, assetPeriodAmountField, assetRemainingPeriodsField, assetTotalPeriodsField,
        rentalIdField, rentalPriceField, rentalTotalDeductField, rentalPeriodAmountField, rentalRatioField
    });
    
    // 🆕 v3.45.37: 建立代扣数据索引（按订单号去重后汇总）
    // rentalMapAll: 房源编码 -> 所有记录数组
    // rentalMapAggregated: 房源编码 -> 聚合数据（按订单号去重后的代扣总金额汇总）
    const rentalMapAll = new Map();
    const rentalMapAggregated = new Map();
    
    if (hasRentalData && rentalIdField) {
        // 第一步：按房源编码收集所有记录
        DataProcessState.rentalData.forEach(row => {
            const id = String(row[rentalIdField] || '').trim();
            if (!id) return;
            
            // 存储所有记录
            if (!rentalMapAll.has(id)) {
                rentalMapAll.set(id, []);
            }
            rentalMapAll.get(id).push(row);
        });
        
        // 第二步：对每个房源，按订单号去重后聚合
        // 🆕 v3.45.39: 改进去重逻辑
        // 策略：优先使用订单号去重；如果没有订单号字段，则使用"代扣总金额"去重（相同金额视为重复）
        rentalMapAll.forEach((rows, assetId) => {
            const seenKeys = new Set();  // 已处理的去重键
            let totalDeductSum = 0;
            let uniqueOrderCount = 0;
            let firstPrice = null;
            let firstPeriodAmount = null;
            let firstRatio = null;
            
            rows.forEach((row, rowIndex) => {
                // 获取去重键
                let dedupeKey = '';
                
                if (rentalOrderIdField) {
                    // 有订单号字段时，使用订单号作为去重键
                    const orderId = row[rentalOrderIdField];
                    if (orderId !== null && orderId !== undefined && String(orderId).trim() !== '') {
                        dedupeKey = `order_${String(orderId).trim()}`;
                    }
                }
                
                // 如果没有订单号或订单号为空，使用代扣总金额作为去重键
                // 逻辑：同一房源下，相同代扣总金额的记录视为重复
                if (dedupeKey === '') {
                    const totalDeduct = parseFloat(row[rentalTotalDeductField]) || 0;
                    dedupeKey = `amount_${totalDeduct.toFixed(2)}`;
                }
                
                // 判断是否应该计入汇总
                if (!seenKeys.has(dedupeKey)) {
                    seenKeys.add(dedupeKey);
                    uniqueOrderCount++;
                    
                    // 累加代扣总金额（只计入去重后的订单）
                    const totalDeduct = parseFloat(row[rentalTotalDeductField]) || 0;
                    totalDeductSum += totalDeduct;
                    
                    // 取第一条记录的价格和每期金额
                    if (firstPrice === null) {
                        firstPrice = parseFloat(row[rentalPriceField]) || 0;
                        firstPeriodAmount = parseFloat(row[rentalPeriodAmountField]) || 0;
                        firstRatio = parseFloat(row[rentalRatioField]) || 0;
                    }
                }
            });
            
            rentalMapAggregated.set(assetId, {
                totalDeductSum: totalDeductSum,       // 去重后的代扣总金额汇总
                firstPrice: firstPrice,              // 第一条记录的出房价格
                firstPeriodAmount: firstPeriodAmount, // 第一条记录的每期代扣金额
                firstRatio: firstRatio,              // 第一条记录的代扣比例
                recordCount: rows.length,            // 原始记录数量
                uniqueOrderCount: uniqueOrderCount   // 🆕 去重后的订单数量
            });
        });
        
        // 🆕 v3.45.39: 添加详细日志，帮助调试去重逻辑
        console.log('【数据校验 v3.45.39】代扣表索引建立完成（按订单号去重）:', {
            唯一房源编码数: rentalMapAll.size,
            总记录数: DataProcessState.rentalData.length,
            订单号字段: rentalOrderIdField || '未找到'
        });
        
        // 输出前3个房源的去重详情，用于验证逻辑
        let debugCount = 0;
        rentalMapAggregated.forEach((agg, assetId) => {
            if (debugCount < 3 && agg.recordCount > 1) {
                const rows = rentalMapAll.get(assetId);
                const orderIds = rows.map(r => rentalOrderIdField ? r[rentalOrderIdField] : '无订单号字段');
                console.log(`【数据校验 v3.45.39】房源${assetId}去重详情:`, {
                    原始记录数: agg.recordCount,
                    去重后订单数: agg.uniqueOrderCount,
                    代扣汇总: agg.totalDeductSum,
                    各记录订单号: orderIds,
                    各记录代扣金额: rows.map(r => parseFloat(r[rentalTotalDeductField]) || 0)
                });
                debugCount++;
            }
        });
    }
    
    // 🆕 v3.45.47: 建立已入池资产的房源编码集合（只校验已入池的数据）
    const pooledAssetIds = new Set();
    if (DataProcessState.generatedData && DataProcessState.generatedData.length > 0) {
        DataProcessState.generatedData.forEach(row => {
            const id = String(row.asset_id || '').trim();
            if (id) pooledAssetIds.add(id);
        });
    }
    
    console.log('【数据校验 v3.45.47】只校验已入池资产:', {
        已入池资产数: pooledAssetIds.size,
        原始房源数据数: DataProcessState.assetData.length,
        不符合入池条件数: DataProcessState.disqualifiedRecords?.length || 0
    });
    
    // 遍历房源数据执行校验（只校验已入池的资产）
    DataProcessState.assetData.forEach((assetRow, index) => {
        const assetId = String(assetRow[assetIdField] || '').trim();
        if (!assetId) return;
        
        // 🆕 v3.45.47: 跳过未入池的资产
        if (pooledAssetIds.size > 0 && !pooledAssetIds.has(assetId)) {
            return; // 该资产未入池，跳过校验
        }
        
        // 获取该房源的所有代扣记录和聚合数据
        const rentalRows = rentalMapAll.get(assetId) || [];
        const rentalAgg = rentalMapAggregated.get(assetId);
        const rentalRow = rentalRows.length > 0 ? rentalRows[0] : null; // 第一条记录用于基础信息
        
        // 提取房源表数据
        const assetPrice = parseFloat(assetRow[assetPriceField]) || 0;
        const deductedUnpaid = parseFloat(assetRow[assetDeductedUnpaidField]) || 0;
        const undeducted = parseFloat(assetRow[assetUndeductedField]) || 0;
        const deductRatio = parseFloat(assetRow[assetRatioField]) || 0;
        const periodAmount = parseFloat(assetRow[assetPeriodAmountField]) || 0;
        const remainingPeriods = parseInt(assetRow[assetRemainingPeriodsField]) || 0;
        const brand = assetRow[assetBrandField] || '';
        const totalPeriods = parseInt(assetRow[assetTotalPeriodsField]) || 0;
        // 🆕 v3.45.36: 已租金代扣到账合计
        const deductedPaid = parseFloat(assetRow[assetDeductedPaidField]) || 0;
        
        // 🆕 v3.45.37: 从聚合数据获取代扣表信息（按订单号去重后）
        const rentalPrice = rentalAgg ? rentalAgg.firstPrice : null;
        const rentalTotalDeductSum = rentalAgg ? rentalAgg.totalDeductSum : null;  // 去重后的汇总金额
        const rentalPeriodAmount = rentalAgg ? rentalAgg.firstPeriodAmount : null;
        const rentalRatio = rentalAgg ? rentalAgg.firstRatio : null;
        const rentalRecordCount = rentalAgg ? rentalAgg.recordCount : 0;        // 原始记录数
        const rentalUniqueOrderCount = rentalAgg ? rentalAgg.uniqueOrderCount : 0;  // 去重后订单数
        
        // 判断资产类型和折扣率
        const isPartial = ['舒里', '简逸'].includes(brand);
        const assetType = isPartial ? '局装' : '整装';
        const discountRate = getUnifiedAssetDiscountRate(assetType);
        const discountLabel = isPartial ? '局装统一折扣' : '整装统一折扣';
        
        // 创建基础记录
        const baseRecord = {
            房源编码: assetId,
            品牌: brand,
            资产类型: assetType,
            剩余期数: remainingPeriods,
            代扣总期数: totalPeriods,
            折扣率: discountRate,
            折扣标签: discountLabel,
            房源出房价格: assetPrice,
            代扣出房价格: rentalPrice,
            代扣记录数: rentalRecordCount,      // 原始记录数量
            去重订单数: rentalUniqueOrderCount,  // 🆕 v3.45.37: 按订单号去重后的订单数
            房源每期应付: periodAmount,
            代扣每期应付: rentalPeriodAmount,  // 🆕 代扣表的每期金额
            代扣比例_代扣表: rentalRatio,      // 🆕 代扣表的比例
            计算每期应付: rentalPrice && rentalRatio ? rentalPrice * (rentalRatio / 100) : null,  // 🆕 用代扣表数据计算
            租金代扣比例: deductRatio,
            已代扣未付款: deductedUnpaid,
            贝壳未代扣: undeducted,
            房源合计: deductedUnpaid + undeducted,
            已租金代扣到账合计: deductedPaid,  // 🆕 v3.45.36
            代扣总金额汇总: rentalTotalDeductSum,  // 🆕 汇总金额
            _rawAsset: assetRow,
            _rawRentals: rentalRows,  // 🆕 所有代扣记录
            _rawRental: rentalRow,    // 保留第一条用于兼容
            _index: index
        };
        
        let allPass = true;
        const checkResults = { price: true, total: true, period: true };
        
        // ========================================
        // Check 1: 出房价格一致性（容差±1000元）
        // 🆕 v3.45.35: 阈值从1元改为1000元
        // ========================================
        if (hasRentalData && rentalPrice !== null && rentalPrice > 0 && assetPrice > 0) {
            const priceDiff = Math.abs(assetPrice - rentalPrice);
            if (priceDiff > 1000) {  // 🆕 阈值改为1000元
                checkResults.price = false;
                allPass = false;
                DataProcessState.validationResults.priceCheckFailed.push({
                    ...baseRecord,
                    差异金额: rentalPrice - assetPrice,
                    差异百分比: assetPrice > 0 ? ((rentalPrice - assetPrice) / assetPrice * 100).toFixed(2) + '%' : 'N/A'
                });
            }
        }
        
        // ========================================
        // Check 2: 代扣总金额校验（容差±10元或±1%）
        // 🆕 v3.45.36: 新公式：Σ代扣表.代扣总金额(同房源) - 房源表.已租金代扣到账合计 ≈ 房源表.(已代扣未付款 + 贝壳未代扣)
        // ========================================
        if (hasRentalData && rentalTotalDeductSum !== null && rentalTotalDeductSum > 0) {
            const assetTotal = deductedUnpaid + undeducted;  // 房源表：已代扣未付款 + 贝壳未代扣
            const rentalNetAmount = rentalTotalDeductSum - deductedPaid;  // 代扣汇总 - 已到账合计
            const totalDiff = Math.abs(rentalNetAmount - assetTotal);
            const toleranceAbs = 10;
            const tolerancePct = Math.abs(assetTotal) * 0.01;
            const tolerance = Math.max(toleranceAbs, tolerancePct);
            
            if (totalDiff > tolerance) {
                checkResults.total = false;
                allPass = false;
                
                // 🆕 v3.45.40: 诊断检测 - 判断差异是否可能由未去重导致
                const actualDiff = rentalNetAmount - assetTotal;
                let diagnosticNote = '';
                
                // 检测1：差异金额 ≈ 房源合计（可能所有订单都重复了）
                if (Math.abs(actualDiff - assetTotal) < 100) {
                    diagnosticNote = '⚠️ 差异≈房源合计，疑似全部重复';
                }
                // 检测2：差异金额 ≈ 代扣汇总的一半（可能订单都重复了一次）
                else if (Math.abs(actualDiff - rentalTotalDeductSum / 2) < 100) {
                    diagnosticNote = '⚠️ 差异≈汇总/2，疑似二倍重复';
                }
                // 检测3：代扣记录数 > 去重订单数（确实发生了去重）
                else if (rentalRecordCount > rentalUniqueOrderCount) {
                    diagnosticNote = `已去重: ${rentalRecordCount}→${rentalUniqueOrderCount}条`;
                }
                // 检测4：代扣记录数 = 去重订单数 = 1（单条记录，不存在去重问题）
                else if (rentalRecordCount === 1) {
                    diagnosticNote = '单条记录，无去重';
                }
                // 检测5：差异较大但原因不明
                else if (Math.abs(actualDiff / assetTotal) > 0.5) {
                    diagnosticNote = '⚠️ 差异>50%，需人工核查';
                }
                
                DataProcessState.validationResults.totalCheckFailed.push({
                    ...baseRecord,
                    代扣汇总减到账: rentalNetAmount,  // 🆕 代扣汇总 - 已到账
                    差异金额: actualDiff,
                    差异百分比: assetTotal > 0 ? (actualDiff / assetTotal * 100).toFixed(2) + '%' : 'N/A',
                    诊断备注: diagnosticNote  // 🆕 v3.45.40: 诊断信息
                });
            }
        }
        
        // ========================================
        // Check 3: 每期应付金额校验（容差±1元）
        // 🆕 v3.45.35: 改用代扣表数据进行校验
        // 公式：代扣表.出房价格 × 代扣表.代扣比例 ≈ 代扣表.每期代扣金额
        // ========================================
        if (hasRentalData && rentalPrice > 0 && rentalRatio > 0 && rentalPeriodAmount > 0) {
            const calculatedPeriod = rentalPrice * (rentalRatio / 100);
            const periodDiff = Math.abs(calculatedPeriod - rentalPeriodAmount);
            if (periodDiff > 1) {
                checkResults.period = false;
                allPass = false;
                DataProcessState.validationResults.periodCheckFailed.push({
                    ...baseRecord,
                    差异金额: calculatedPeriod - rentalPeriodAmount,
                    差异百分比: rentalPeriodAmount > 0 ? ((calculatedPeriod - rentalPeriodAmount) / rentalPeriodAmount * 100).toFixed(2) + '%' : 'N/A'
                });
            }
        }
        
        // 全部通过
        if (allPass) {
            DataProcessState.validationResults.passRecords.push(baseRecord);
        }
    });
    
    // 更新UI
    renderValidationSummary();
    renderValidationDetails();
    
    console.log('【数据校验 v3.45.30】校验完成:', {
        全部通过: DataProcessState.validationResults.passRecords.length,
        出房价格不一致: DataProcessState.validationResults.priceCheckFailed.length,
        代扣总金额校验失败: DataProcessState.validationResults.totalCheckFailed.length,
        每期金额校验失败: DataProcessState.validationResults.periodCheckFailed.length
    });
}

/**
 * 🆕 v3.45.30: 渲染校验汇总卡片
 */
function renderValidationSummary() {
    const results = DataProcessState.validationResults;
    
    // 更新汇总数字
    const passEl = document.getElementById('validationPassCount');
    const priceEl = document.getElementById('validationPriceCount');
    const totalEl = document.getElementById('validationTotalCount');
    const periodEl = document.getElementById('validationPeriodCount');
    
    if (passEl) passEl.textContent = results.passRecords.length;
    if (priceEl) priceEl.textContent = results.priceCheckFailed.length;
    if (totalEl) totalEl.textContent = results.totalCheckFailed.length;
    if (periodEl) periodEl.textContent = results.periodCheckFailed.length;
}

