/**
 * 🆕 v3.45.10: 重新计算超期资产列表（删除后更新索引）
 */
function recalculateLongTermRecords() {
    DataProcessState.longTermRecords = [];
    
    DataProcessState.generatedData.forEach((row, idx) => {
        if ((row.remaining_periods || 0) > 36) {
            DataProcessState.longTermRecords.push({
                房源编码: row.asset_id,
                品牌: row._brand,
                资产类型: row.asset_type,
                总代扣金额: row.total_deduction,
                已代扣金额: row.deducted_amount,
                剩余期数: row.remaining_periods,
                每期代扣金额: row.period_deduction,
                每期比例: row.period_ratio,
                来源文件: row._sourceFile,
                _index: idx,
                _record: row
            });
        }
    });
}

/**
 * 🆕 v3.45.10: 删除记录后刷新界面
 */
function refreshAfterRemoval(removedCount, recordType) {
    // 刷新显示
    document.getElementById('matchedCount').textContent = DataProcessState.generatedData.length;
    renderGeneratedDataTable();
    renderDataQualitySummary();
    updateExportableCount();
    
    showToast(`已从入池清单中删除 ${removedCount} 条${recordType}的资产`, 'success');
    
    console.log(`【数据加工 v3.45.10】删除${recordType}:`, {
        删除数量: removedCount,
        剩余总数: DataProcessState.generatedData.length,
        剩余超期数: DataProcessState.longTermRecords.length,
        剩余不完整数: DataProcessState.incompleteRecords.length,
        剩余重复数: DataProcessState.duplicateRecords.length,
        剩余缺失数: DataProcessState.missingRentalRecords.length
    });
}

/**
 * 🆕 渲染不符合入池条件表格
 */
function renderDisqualifiedRecordsTable(records) {
    const container = document.getElementById('disqualifiedRecordsContainer');
    const countEl = document.getElementById('disqualifiedCount');
    
    if (!container) return;
    
    countEl.textContent = records.length;
    
    if (records.length === 0) {
        container.innerHTML = '<p class="no-data-hint">✓ 所有记录都符合入池条件</p>';
        return;
    }
    
    // 🆕 v3.45.41: 更新表格列，显示代扣记录数和所有记录的收房/出房价格检查结果
    container.innerHTML = `
        <table class="quality-table">
            <thead>
                <tr>
                    <th>房源编码</th>
                    <th>品牌</th>
                    <th>资产类型</th>
                    <th>总代扣金额</th>
                    <th>代扣记录数</th>
                    <th>代扣出房价格</th>
                    <th>代扣收房价格</th>
                    <th>不符合原因</th>
                    <th>来源文件</th>
                </tr>
            </thead>
            <tbody>
                ${records.map((r, idx) => {
                    // 格式化价格显示
                    const formatPrice = (val) => {
                        if (val === null || val === undefined || val === '') return '<span class="status-bad">空</span>';
                        const num = parseFloat(val);
                        if (isNaN(num) || num === 0) return '<span class="status-bad">0/空</span>';
                        return Utils.formatCurrency(num);
                    };
                    // 🆕 v3.45.41: 显示代扣记录数
                    const recordCount = r.代扣记录数 || 1;
                    const recordCountDisplay = recordCount > 1 
                        ? `<span class="status-warning">${recordCount}条</span>` 
                        : `${recordCount}条`;
                    return `
                    <tr data-index="${idx}">
                        <td>${r.房源编码}</td>
                        <td>${r.品牌 || '-'}</td>
                        <td><span class="type-badge ${r.资产类型 === '整装' ? 'full' : 'partial'}">${r.资产类型}</span></td>
                        <td class="number-cell">${Utils.formatCurrency(r.总代扣金额)}</td>
                        <td class="number-cell">${recordCountDisplay}</td>
                        <td class="number-cell">${formatPrice(r.代扣出房价格)}</td>
                        <td class="number-cell">${formatPrice(r.代扣收房价格)}</td>
                        <td><span class="disqualify-reason">${r.不符合原因}</span></td>
                        <td class="source-file" title="${r.来源文件 || ''}">${r.来源文件 || '-'}</td>
                    </tr>
                `}).join('')}
            </tbody>
        </table>
    `;
}

/**
 * 渲染数据信息不全表格（显示来源文件和缺失字段来源）
 */
function renderIncompleteRecordsTable(records) {
    const container = document.getElementById('incompleteRecordsContainer');
    const countEl = document.getElementById('incompleteCount');
    
    if (!container) return;
    
    countEl.textContent = records.length;
    
    if (records.length === 0) {
        container.innerHTML = '<p class="no-data-hint">✓ 无数据信息不全的记录</p>';
        return;
    }
    
    // 🆕 统计可自动补全的记录数量
    const canAutoFillPeriodsCount = records.filter(r => r._onlyMissingPeriods && r._contractYears).length;
    const canAutoFillDeductionCount = records.filter(r => r._onlyMissingPeriodDeduction && r._calculatedPeriodDeduction).length;
    
    // 生成缺失详情的展示
    const formatMissingDetails = (details) => {
        if (!details || !Array.isArray(details)) return '-';
        return details.map(d => 
            `<span class="missing-item"><span class="missing-field">${d.field}</span><span class="missing-source">${d.source}:${d.sourceField}</span></span>`
        ).join('');
    };
    
    // 🆕 生成操作按钮
    const formatActionButtons = (r, idx) => {
        let buttons = `<button class="btn btn-small btn-primary" onclick="editIncompleteRecord(${idx})" title="手动编辑">
            <i class="fas fa-edit"></i>
        </button>`;
        
        // 如果仅缺代扣总期数且有签约年限，显示一键补全按钮
        if (r._onlyMissingPeriods && r._contractYears && r._calculatedPeriods) {
            buttons += ` <button class="btn btn-small btn-success" onclick="autoFillPeriods(${idx})" title="一键补全: 签约${r._contractYears}年 → ${r._calculatedPeriods}期">
                <i class="fas fa-magic"></i> ${r._calculatedPeriods}期
            </button>`;
        }
        
        // 🆕 如果仅缺每期代扣金额且可计算，显示一键补全按钮
        if (r._onlyMissingPeriodDeduction && r._calculatedPeriodDeduction) {
            const formattedAmount = Utils.formatCurrency(r._calculatedPeriodDeduction);
            buttons += ` <button class="btn btn-small btn-success" onclick="autoFillPeriodDeduction(${idx})" title="一键补全: 收房价格${r._collectPrice} × 比例${r._deductRatio} = ${formattedAmount}">
                <i class="fas fa-magic"></i> ${formattedAmount}
            </button>`;
        }
        
        return buttons;
    };
    
    // 🆕 生成批量补全操作栏
    let batchFillButtons = '';
    if (canAutoFillPeriodsCount > 0 || canAutoFillDeductionCount > 0) {
        batchFillButtons = '<div class="batch-action-bar-container">';
        
        if (canAutoFillPeriodsCount > 0) {
            batchFillButtons += `
                <div class="batch-action-bar periods">
                    <span class="batch-hint"><i class="fas fa-calendar-alt"></i> 发现 <strong>${canAutoFillPeriodsCount}</strong> 条仅缺代扣总期数，可用签约年限补全</span>
                    <button class="btn btn-success" onclick="batchAutoFillPeriods()">
                        <i class="fas fa-magic"></i> 批量补全期数
                    </button>
                </div>
            `;
        }
        
        if (canAutoFillDeductionCount > 0) {
            batchFillButtons += `
                <div class="batch-action-bar deduction">
                    <span class="batch-hint"><i class="fas fa-calculator"></i> 发现 <strong>${canAutoFillDeductionCount}</strong> 条仅缺每期代扣金额，可用收房价格×代扣比例补全</span>
                    <button class="btn btn-success" onclick="batchAutoFillPeriodDeduction()">
                        <i class="fas fa-magic"></i> 批量补全金额
                    </button>
                </div>
            `;
        }
        
        batchFillButtons += '</div>';
    }
    
    // 判断是否可以自动补全（期数或金额）
    const canAutoFill = (r) => {
        return (r._onlyMissingPeriods && r._contractYears) || (r._onlyMissingPeriodDeduction && r._calculatedPeriodDeduction);
    };
    
    // 格式化补全参考信息
    const formatFillInfo = (r) => {
        if (r._onlyMissingPeriods && r._contractYears) {
            return `签约${r._contractYears}年`;
        }
        if (r._onlyMissingPeriodDeduction && r._collectPrice && r._deductRatio) {
            return `${r._collectPrice}×${(r._deductRatio * 100).toFixed(0)}%`;
        }
        return '-';
    };
    
    container.innerHTML = `
        ${batchFillButtons}
        <table class="quality-table">
            <thead>
                <tr>
                    <th>房源编码</th>
                    <th>来源文件</th>
                    <th>品牌</th>
                    <th>资产类型</th>
                    <th>总代扣金额</th>
                    <th>缺失字段 (来源表:字段名)</th>
                    <th>补全参考</th>
                    <th>操作</th>
                </tr>
            </thead>
            <tbody>
                ${records.map((r, idx) => `
                    <tr data-index="${idx}" class="${canAutoFill(r) ? 'can-auto-fill' : ''}">
                        <td>${r.房源编码}</td>
                        <td class="source-file" title="${r.来源文件 || ''}">${r.来源文件 || '-'}</td>
                        <td>${r.品牌}</td>
                        <td><span class="type-badge ${r.资产类型 === '整装' ? 'full' : 'partial'}">${r.资产类型}</span></td>
                        <td class="number-cell">${Utils.formatCurrency(r.总代扣金额)}</td>
                        <td class="missing-details-cell">${formatMissingDetails(r.缺失详情)}</td>
                        <td class="number-cell">${formatFillInfo(r)}</td>
                        <td class="action-cell">
                            ${formatActionButtons(r, idx)}
                        </td>
                    </tr>
                `).join('')}
            </tbody>
        </table>
    `;
}

