/**
 * 编辑数据不全的记录
 */
function editIncompleteRecord(idx) {
    const record = DataProcessState.incompleteRecords[idx];
    if (!record) return;
    
    const mainIdx = record._index;
    const mainRecord = DataProcessState.generatedData[mainIdx];
    if (!mainRecord) return;
    
    // 弹出编辑对话框
    showEditRecordModal(mainIdx, mainRecord, record.缺失字段);
}

/**
 * 使用重复记录替换
 */
function useDuplicateRecord(idx) {
    const duplicate = DataProcessState.duplicateRecords[idx];
    if (!duplicate) return;
    
    // 找到主表中对应的记录
    const mainIdx = DataProcessState.generatedData.findIndex(r => r.asset_id === duplicate.房源编码);
    if (mainIdx < 0) {
        showToast('主表中未找到对应记录', 'error');
        return;
    }
    
    // 用重复记录的数据更新主表
    const rawRow = duplicate._rawRow;
    const fm = DataProcessState.fieldMapping;
    
    if (fm.totalAmountField && rawRow[fm.totalAmountField]) {
        DataProcessState.generatedData[mainIdx].total_deduction = parseFloat(rawRow[fm.totalAmountField]) || 0;
    }
    if (fm.periodsField && rawRow[fm.periodsField]) {
        DataProcessState.generatedData[mainIdx].total_periods = parseInt(rawRow[fm.periodsField]) || 12;
    }
    
    // 重新渲染
    renderGeneratedDataTable();
    showToast(`已使用 ${duplicate.来源文件} 中的记录更新`, 'success');
}

/**
 * 手动添加缺失代扣数据的记录
 */
function addMissingRentalRecord(idx) {
    const record = DataProcessState.missingRentalRecords[idx];
    if (!record) return;
    
    // 弹出补充数据对话框
    showAddMissingRecordModal(idx, record);
}

/**
 * 显示编辑记录对话框
 */
function showEditRecordModal(mainIdx, record, missingFields) {
    const modal = document.createElement('div');
    modal.className = 'modal-overlay';
    modal.id = 'editRecordModal';
    modal.innerHTML = `
        <div class="modal-content compact">
            <div class="modal-header">
                <h3><i class="fas fa-edit"></i> 补全数据</h3>
                <button class="modal-close" onclick="closeEditRecordModal()">&times;</button>
            </div>
            <div class="modal-body">
                <p class="edit-hint">房源编码: <strong>${record.asset_id}</strong>，缺失字段: <span class="missing-fields">${missingFields}</span></p>
                <div class="form-grid">
                    <div class="form-group">
                        <label>代扣总期数</label>
                        <input type="number" id="editTotalPeriods" value="${record.total_periods || 12}" min="1">
                    </div>
                    <div class="form-group">
                        <label>每期代扣金额</label>
                        <input type="number" id="editPeriodDeduction" value="${record.period_deduction || 0}" step="0.01">
                    </div>
                    <div class="form-group">
                        <label>已代扣金额</label>
                        <input type="number" id="editDeductedAmount" value="${record.deducted_amount || 0}" step="0.01">
                    </div>
                    <div class="form-group">
                        <label>资产起租日</label>
                        <input type="date" id="editLeaseStartDate" value="${record.lease_start_date || ''}">
                    </div>
                </div>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeEditRecordModal()">取消</button>
                <button class="btn btn-primary" onclick="saveEditedRecord(${mainIdx})">保存</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
}

/**
 * 关闭编辑对话框
 */
function closeEditRecordModal() {
    const modal = document.getElementById('editRecordModal');
    if (modal) modal.remove();
}

/**
 * 保存编辑的记录
 */
function saveEditedRecord(mainIdx) {
    const record = DataProcessState.generatedData[mainIdx];
    if (!record) return;
    
    record.total_periods = parseInt(document.getElementById('editTotalPeriods').value) || 12;
    record.period_deduction = parseFloat(document.getElementById('editPeriodDeduction').value) || 0;
    record.deducted_amount = parseFloat(document.getElementById('editDeductedAmount').value) || 0;
    record.lease_start_date = document.getElementById('editLeaseStartDate').value || '';
    
    // 更新不全状态
    const missingFields = [];
    if (!record.total_periods) missingFields.push('代扣总期数');
    if (!record.period_deduction) missingFields.push('每期代扣金额');
    record._isIncomplete = missingFields.length > 0;
    record._missingFields = missingFields;
    
    // 从不全列表中移除或更新
    const incompleteIdx = DataProcessState.incompleteRecords.findIndex(r => r._index === mainIdx);
    if (incompleteIdx >= 0) {
        if (missingFields.length === 0) {
            DataProcessState.incompleteRecords.splice(incompleteIdx, 1);
        } else {
            DataProcessState.incompleteRecords[incompleteIdx].缺失字段 = missingFields.join(', ');
        }
    }
    
    closeEditRecordModal();
    renderGeneratedDataTable();
    renderDataQualitySummary();
    showToast('记录已更新', 'success');
}

