/**
 * 关闭添加缺失记录对话框
 */
function closeAddMissingRecordModal() {
    const modal = document.getElementById('addMissingRecordModal');
    if (modal) modal.remove();
}

/**
 * 保存添加的缺失记录到主表
 */
function saveAddedMissingRecord(idx) {
    const record = DataProcessState.missingRentalRecords[idx];
    if (!record) return;
    
    const newRecord = {
        asset_id: record.房源编码,
        asset_type: record.资产类型,
        total_deduction: record.总代扣金额,
        deducted_amount: parseFloat(document.getElementById('addDeductedAmount').value) || 0,
        lease_start_date: document.getElementById('addLeaseStartDate').value || '',
        total_periods: parseInt(document.getElementById('addTotalPeriods').value) || 12,
        period_deduction: parseFloat(document.getElementById('addPeriodDeduction').value) || 0,
        _brand: record.品牌,
        _isIncomplete: false,
        _missingFields: []
    };
    
    // 添加到主表
    DataProcessState.generatedData.push(newRecord);
    
    // 从缺失列表中移除
    DataProcessState.missingRentalRecords.splice(idx, 1);
    
    // 重新排序
    DataProcessState.generatedData.sort((a, b) => {
        if (a.asset_type !== b.asset_type) {
            return a.asset_type === '整装' ? -1 : 1;
        }
        return b.total_deduction - a.total_deduction;
    });
    
    closeAddMissingRecordModal();
    
    // 更新计数
    document.getElementById('matchedCount').textContent = DataProcessState.generatedData.length;
    document.getElementById('unmatchedCount').textContent = DataProcessState.missingRentalRecords.length;
    
    renderGeneratedDataTable();
    renderDataQualitySummary();
    showToast(`已将 ${record.房源编码} 添加到主表`, 'success');
}

