window.closeAddMissingRecordModal = closeAddMissingRecordModal;
window.saveAddedMissingRecord = saveAddedMissingRecord;

/**
 * 🆕 一键补全代扣总期数（使用签约年限计算：签约年限 / 2 × 12）
 */
function autoFillPeriods(idx) {
    const record = DataProcessState.incompleteRecords[idx];
    if (!record) {
        showToast('记录不存在', 'error');
        return;
    }
    
    if (!record._onlyMissingPeriods || !record._contractYears || !record._calculatedPeriods) {
        showToast('该记录不支持自动补全', 'warning');
        return;
    }
    
    const mainIndex = record._index;
    const mainRecord = DataProcessState.generatedData[mainIndex];
    
    if (!mainRecord) {
        showToast('主表记录不存在', 'error');
        return;
    }
    
    // 更新代扣总期数
    mainRecord.total_periods = record._calculatedPeriods;
    
    // 重新计算每期代扣金额（如果之前没有）
    if (!mainRecord.period_deduction && mainRecord.total_deduction > 0 && mainRecord.total_periods > 0) {
        mainRecord.period_deduction = mainRecord.total_deduction / mainRecord.total_periods;
    }
    
    // 标记为已补全
    mainRecord._isIncomplete = false;
    mainRecord._missingFields = [];
    
    // 从不全列表中移除
    DataProcessState.incompleteRecords.splice(idx, 1);
    
    console.log(`【数据加工】已补全 ${record.房源编码} 的代扣总期数: ${record._calculatedPeriods}期（签约${record._contractYears}年）`);
    
    // 刷新显示
    renderGeneratedDataTable();
    renderDataQualitySummary();
    updateExportableCount();
    
    showToast(`已补全 ${record.房源编码}: 代扣总期数 = ${record._calculatedPeriods}期（签约${record._contractYears}年 ÷ 2 × 12）`, 'success');
}

/**
 * 🆕 批量一键补全所有仅缺代扣总期数的记录
 */
function batchAutoFillPeriods() {
    // 找出所有可以自动补全的记录
    const canFillRecords = DataProcessState.incompleteRecords.filter(r => 
        r._onlyMissingPeriods && r._contractYears && r._calculatedPeriods
    );
    
    if (canFillRecords.length === 0) {
        showToast('没有可自动补全的记录', 'warning');
        return;
    }
    
    let filledCount = 0;
    
    // 从后往前处理，避免索引变化问题
    for (let i = DataProcessState.incompleteRecords.length - 1; i >= 0; i--) {
        const record = DataProcessState.incompleteRecords[i];
        
        if (!record._onlyMissingPeriods || !record._contractYears || !record._calculatedPeriods) {
            continue;
        }
        
        const mainIndex = record._index;
        const mainRecord = DataProcessState.generatedData[mainIndex];
        
        if (!mainRecord) continue;
        
        // 更新代扣总期数
        mainRecord.total_periods = record._calculatedPeriods;
        
        // 重新计算每期代扣金额
        if (!mainRecord.period_deduction && mainRecord.total_deduction > 0 && mainRecord.total_periods > 0) {
            mainRecord.period_deduction = mainRecord.total_deduction / mainRecord.total_periods;
        }
        
        // 标记为已补全
        mainRecord._isIncomplete = false;
        mainRecord._missingFields = [];
        
        // 从不全列表中移除
        DataProcessState.incompleteRecords.splice(i, 1);
        
        filledCount++;
    }
    
    console.log(`【数据加工】批量补全完成，共补全 ${filledCount} 条记录`);
    
    // 刷新显示
    renderGeneratedDataTable();
    renderDataQualitySummary();
    updateExportableCount();
    
    showToast(`已批量补全 ${filledCount} 条记录的代扣总期数（使用签约年限 ÷ 2 × 12 计算）`, 'success');
}

window.autoFillPeriods = autoFillPeriods;
window.batchAutoFillPeriods = batchAutoFillPeriods;

