window.exportIncompleteRecords = exportIncompleteRecords;
window.exportDisqualifiedRecords = exportDisqualifiedRecords;
window.exportRatingData = exportRatingData;
window.exportTrustData = exportTrustData; // 🆕 v3.45.49: 生成信托数据
